/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250311-3","meetingId":"r07-c-budget","date":"2025年3月11日","dateIso":"2025-03-11","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時１８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を162件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度品川区一般会計予算","agenda":"令和７年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３０９ページ、保健予防費、それと時間があれば、２９９ページ、受動喫煙防止対策費についてお伺いいたします。よろしくお願いします。初めに３０９ページ、保健予防費、予防接種費の中から任意予防接種に関連しまして、百日ぜきの流行と３種混合ワクチン（ＤＰＴ）についてお尋ねしてまいります。初めに、現在の百日ぜきの流行の状況と、特に本区の流行状況についてお知らせいただきたいと思います。","respondent":"五十嵐保健予防課長","answer":"週によって報告数が違うのですが、１週間に７件ぐらいある週と、あまりない週と出てきているようで、累計していくと少しずつ増加してきているような印象を持って見ているところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"どうもありがとうあります。そうしますと、小学校では流行がこれから広まる可能性があるという認識でよろしいでしょうか。","respondent":"五十嵐保健予防課長","answer":"百日ぜきにつきましては、以前、３種混合（ＤＰＴ）という予防接種に入っておりましたが、今年から５種混合に変わっておりまして、増えている部分もあるのですけれども、小学生の方は、３種混合の予防接種を計４回受けていらっしゃる方がほぼいらっしゃいますので。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、分かりませんけれども、今後、小学校で流行が広がってきた場合、百日ぜきが流行すると何が問題なのでしょうか。教えてください。","respondent":"五十嵐保健予防課長","answer":"ただ、きちんと診断されて、効くお薬を飲めば落ち着いてくるものですので、私どもとしましては、気がついたら早めに受診していただきたいということで、今回ホームページにも上げさせていただいているところになります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"課長のご答弁のとおり、百日ぜきワクチンを含む５種混合ワクチンを接種する前の、まだ小さな新生児、そして乳児が百日ぜきに感染すると、激しいせきのために呼吸ができなくなって、全身が紫色のチアノーゼになったり、無呼吸、けいれん、脳症を起こし、窒息して死亡するケースもあるようです。","respondent":"五十嵐保健予防課長","answer":"乳幼児の重症化予防ということで、２０２３年からだったと思うのですけれども、当時は４種混合の予防接種が、生後３か月から定期接種が決められていたものが前倒しになって、２か月から接種できるということになりましたので、ホームページにも書かせていただいておりますが。","voiceIndex":10,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。１１歳の２種混合ワクチン（ＤＴ）追加接種にも、なぜか百日ぜきが入っておりません。ＷＨＯの勧める就学前の子へのＤＰＴ追加接種、あるいは、１１歳のときの２種混合ワクチン（ＤＴ）を、ＤＰＴ任意接種も代わりに打てるようにする、百日ぜきから小学生を守るＤＰＴ接種費用助成の施策を強く求めますが、いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"できれば定期予防接種にしていただきたいという思いもありますが、区が任意予防接種を実施するにしても、どの時期にどのように打つのがいいのかという知見がないと、やはりその辺が分からないと、なかなか打つことができませんので。","voiceIndex":12,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。大阪府の河南町、そして八王子市は、国の施策に先駆けて、２種混合ワクチンの代わりに３種混合ワクチン接種を認め、任意接種助成を行っております。ぜひ本区もいろいろ検討していただいて、百日ぜきの流行・感染を抑えるために取り組んでいただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"３０３ページ、母子保健指導事業費から、外国人の出産について、３０９ページ、骨粗しょう症検診、令和８年度の本格実施について、３１７ページ、粗大ごみからのリユース事業について、これは確認です。伺ってまいります。最初に、３０３ページの出産についてですけれども、日本語を母国語としない外国の方が、この品川区で母子ともに安心して出産ができるような整備を求めて質問をしたいと思います。","respondent":"石橋品川保健センター所長","answer":"令和６年度の出生率は３.１％となっており、昨年、令和５年度に比べて１.２％上昇しております。続きまして、保健センターでの対応についてになります。窓口や健診時には、１３言語のタブレットを活用して、言語による不利益等が生じないように丁寧に対応しております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"ここは戦略広報課との連携も必要かと思いますが、情報として所管課から、しっかりと丁寧な対応を進めていただきたいと思うのですが、文化の違う日本での出産であること、身近に寄り添ってくれる方がいない方の出産も考えられますので、的確な情報を区のホームページに出すということ、そしてまた公式ＬＩＮＥも活用していただきながら、外国人向けの出産に関する情報発信を行っていただきたいと思いますが。","respondent":"石橋品川保健センター所長","answer":"視覚的に情報を得るということは、いつでも情報の確認ができるということで、とても重要なことだと考えています。こちらからも戦略広報課と連携を図ってまいりまして、そのようなことを進めていけるように尽力してまいります。","voiceIndex":18,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"前向きなご答弁をありがとうあります。ぜひよろしくお願いいたします。次に、骨粗しょう症検診についてお伺いいたします。会派からもこの検診を求めてまいりました。来年度が試行実施ということで行われてまいります。所管が違うのですが、今年度、２か所で行われました出張型の国保基本健診の利用状況と、また、想定の人数にそこに集っていただいたのかという振り返りをお聞きしたいと思います。","respondent":"若生健康課長","answer":"今年度、国保医療年金課で実施しました国民健康保険の出張型の健診の実績につきましてですが、２回実施しておりまして、１回目につきましては１２名、２回目につきましては２１名、合計３３名の参加があったと伺っております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"３３名ご利用いただいたということが確認できました。そして、本格実施に向けてですけれども、その状況を受けてということになるかと思いますが、医療機関での実施なのか、また対象年齢、そして検診費用、検査内容、また男性も一定程度の割合、いらっしゃいますので、男性も対象としていただきたいと思いますが、現在の検討状況をお伺いいたします。","respondent":"若生健康課長","answer":"骨粗しょう症検診の本格実施に向けての検討状況ですが、こちらは医療機関や集団健診かというところですが、まず令和７年度に国保の集団健診という形で一応検証させていただきまして、令和８年度に向けて、各医療機関で実施できるように。","voiceIndex":22,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"しっかりと検証を行っていただいた上で、より多くの方が受診できる体制をお願いしたいと思います。時間がなくなってしまいましたが、最後のリユース事業につきましては、区のお考えをお聞きしたいのですが、委託費に対する収入に対しての区のお考えをお聞きしたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"リユース事業につきましては、委託料が１,０００万円ほどかかっているのに対して、歳入が３０万円程度ですので、一定の課題があるものと認識しております。","voiceIndex":24,"id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、３０３ページ、産後ケア事業、３１１ページ、こころの健康づくり事業について伺います。最初に産後ケア事業についてです。令和６年度の実績についてです。ちなみに、令和５年度の時点で私が質疑させていただいたときには、日帰りと訪問型の利用が少し目標値に達していないのではないかということで指摘させていただきました。その点についても変化があれば教えてください。","respondent":"石橋品川保健センター所長","answer":"もう既に５回の利用をされている方も多数いらっしゃいまして、かなり継続利用もしていただいているので、大幅な拡充が好評な結果を招いているかなと感じております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問","question":"約３倍だったり４倍だったりと、利用が進んでいる。前回質問したときには、日帰り型・訪問型の利用が進んでいないけれども、利用した方々の満足度がすごく高くて、多くの方が利用できるといいなと思っておりました。令和６年度の時点で実績がこれだけ伸びたということを大変ありがたく思っております。来年度の予算については、１億５,７００万円余と、また費用についても拡大しております。","respondent":"石橋品川保健センター所長","answer":"宿泊型につきましては、ベッドコントロールというところが必要になりますが、そちらについても、産後ケアとして利用できるベッド数の確保なども検討していただいているというご回答も頂いているので、しっかり需要と供給は受託者と調整して対応してまいりたいと考えております。","voiceIndex":29,"id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１点、利用者目線の改善ということで、昨年の一般質問でも、予約のオンライン化というところをずっと要望しております。その際の返答では、日帰り型・訪問型については受託者と今後、協議していくというようなお話がありましたので、そちらの進捗について、また検討状況についてもお伺いいたします。","respondent":"石橋品川保健センター所長","answer":"その後、受託者と調整と協議を重ねさせていただきまして、４月より電子申請ができる形で今進んでおります。より多くの方に、利便性を上げた形で利用していただけるということで、次年度もしっかりと対応してまいります。","voiceIndex":31,"id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"「利用したくても日付が合わなかったら嫌だ」などというお声を頂いておりましたので、今回の質疑の中で、その点がしっかりと対応できているということを確認できました。引き続き、皆さんが利用できる、そして安心して子育てができるような制度にしていっていただきたいと思います。区内の自殺者、事務事業評価シートを確認させていただきました。分析、課題等についても、あればお聞かせください。","respondent":"五十嵐保健予防課長","answer":"自殺対策としてやはり難しいのが、原因がはっきり分からないということと、何を積極的にやっていったら自殺が減ってくれるのかというところもなかなか難しい部分もありますので、今やっていることを続けさせていただきつつ、何かこれがということであれば。","voiceIndex":33,"id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"時間が限られているので、質問を先に伝えします。特に２０代から３０代の若い世代の自殺率が増加しているということで、インターネット・ゲートキーパーの活用が今進んでおります。品川区としても今行っておりまして、こちらの成果についてもお聞かせいただければと思います。","respondent":"五十嵐保健予防課長","answer":"品川区では、令和３年１２月１日からインターネット・ゲートキーパー事業を開始しているところです。昨年、令和５年につきましては、広告を表示していただいた回数が、１年間で９万６,６４９件になっております。","voiceIndex":35,"id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"すごく表示されているということは、それだけの数の方が自殺や死というところを検索しているのだろうと推察されます。社会情勢を見ながら、「このワードとこのワードが検索されたときには、この相談窓口」のような形で、インターネット・ゲートキーパーの活用というところをどんどん進めていただきたいと考えていますので、その点を最後に一言お願いいたします。","respondent":"五十嵐保健予防課長","answer":"検索ワードにつきましては、１つのワードだけではなく、いろいろなワードを組み合わせて使っているところです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"３１３ページ、環境調査測定費、大気汚染調査、３２３ページ、産業情報・景況調査等経費に関連して、インボイスの区内影響調査について伺います。これはもう、一人、二人の声ではなく、決して無視できるものではありません。伺いますけれども、区が実施したアンケートに、大気汚染や電波障害の被害の声が寄せられたのですから、まずは実態把握を区として行うべきだと思うのですけれども、いかがでしょうか。","respondent":"高梨都市計画課長","answer":"羽田新飛行ルートに関する区民アンケートの実施についてですが、今、委員からもご紹介がありましたとおり、特に自由記述におきましては、２万７,９２２件の様々なご意見を頂いたところです。","voiceIndex":40,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"昨年の決算特別委員会で大気汚染について、時間がなかったのですけれども、環境影響調査測定が必要ではないかと伺いますと、環境課長が、「一般環境大気測定を計４拠点でやっていて、令和元年度ではＳＰＭやＰＭ２.５など、それぞれが環境基準内」と回答されましたけれども、伺いますけれども、この６つの測定局のうち、新ルート直下にある測定局というのはあるのでしょうか。伺います。","respondent":"中西環境課長","answer":"区に設置されております測定局です。新ルートの直下という意味でいきますと、八潮局がそこに該当するかと考えています。","voiceIndex":42,"id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"環境課長に見せてあげてもらっていいですか。伺いますけれども、例えば「大気汚染」などのワードを地域とクロス分析すれば、大気汚染被害が発生している地域というのをある程度限定できるのではないかと思うのですけれども、例えばそういった感じで、実際に被害が発生すると思われるところで、大気汚染の測定局を設置して測定するよう提案いたしますけれども、いかがでしょうか。","respondent":"中西環境課長","answer":"様々、測定局を持ってありますので、その中では大気汚染、令和元年から環境基準の中に収まっているといった現状もありますので、今、現状としては新しく設置するといったことは考えているところではございませんが、引き続き東京都と連携しながら。","voiceIndex":44,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは一方でまた事実なわけです。被害は発生しているのです。次に、インボイスの区内実態調査について伺いたいのですが、２５日の区民委員会で、区内独自でインボイス制度に係る実態調査実施の陳情、そして中小企業の景況でインボイス制度に係る影響調査を要望する陳情が賛成多数で可決されました。なぜ、区民の苦境に寄り添って、品川区ができる調査をやらないのでしょうか。伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"インボイスの実態調査に関して、昨年１１月の時点で国が実施を予定していた調査につきましては、免税事業者等の小規模事業者ということを対象に、そこにターゲットをある程度絞って郵送して、実際にアンケートを行うというようなことでございました。","voiceIndex":46,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"本当に先ほど言いましたけれども、もう品川区のやりようで幾らでもあるわけです。本当に残念な答弁だと思います。品川区は今、現時点でそういう立場なので、ぜひ来る本会議でこの陳情を採択して、区議会として品川区に調査の実施を促していく必要があると私は思います。そのことを委員の皆さんに呼びかけて、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、２９５ページ、健康センター事業費、３０５ページ、猫の適正飼養および活動支援事業、そして３２９ページ、デジタル商品券発行事業についてお伺いいたします。この予算特別委員会でも長時間、委員も理事者の皆さんも座りっ放しですけれども、やはり健康に悪いということが最近言われておりますので、今後の品川区の健康施策にもぜひ反映していただきたいと思います。お答えください。","respondent":"若生健康課長","answer":"例えば、健康センターのホールや会議室の空き枠を利用しまして、健康に関する講座や、栄養士によるカウンセリング、あるいはウォーキングイベントなどを区民の方に無料で実施するといったサービスも考えられるかなというところで。","voiceIndex":50,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"修繕と目標人数について事務事業評価を見ますと、目標人数が、令和６年度から令和１１年度まで、フリー利用延べ参加者数を５年で５万人増やすとされており、コース型教室は５年で２万人増やすということで、フリーですと年間１万人増やす、教室ですと年間４,０００人増やすという、かなり強気な目標が書かれておりますけれども、荏原健康センターが今、改修中ですので。","respondent":"若生健康課長","answer":"今年度、大規模修繕の基本計画というところを今ちょうど進めているところでございまして、費用感というところも、それの結果によって出てくるようなところでございまして、現在のところ。","voiceIndex":52,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"ボランティアに腕章・ゼッケン、また近隣住民への周知などといった事前の約束が守られていないということで、この場所では度々、私もそうしたご相談を受けているのですけれども、やはり地域猫活動というのは、近隣住民とのコミュニケーション、近隣の住民の方に迷惑をかけないようにするというのが大前提で、また清掃も徹底していくということが大前提の事業だと思うのですけれども。","respondent":"赤木生活衛生課長","answer":"地域猫活動におきましては、要綱にも定めているところではありますけれども、地域猫活動における活動方針といたしまして、活動場所の地域住民とのコミュニケーションをしっかり取ること、徹底することというところで定めているところです。","voiceIndex":54,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"ぜひ適正なお声がけをお願いしたいと思います。今、猫アレルギーの方もおりますので、お引っ越しされてきて、お引っ越し先が、たまたま地域猫活動をやられている場所だったということもありますので、転居してくる方への情報提供のためにも、どこがやっている場所なのかということは非常に必要な情報だと思いますので、その辺り、いかがお考えなのでしょうか。","respondent":"赤木生活衛生課長","answer":"その場所を知ってしまうことによって、そういったことにもつながる懸念というのも区としては考えておりまして、今現在としては公表するというところでは考えてはおりません。","voiceIndex":56,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ個別に、問合せなどは、転居してくる方については情報提供をしていただきたいと存じます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-027"},{"speaker":"せらく委員","kind":"確認","question":"２９７ページから公衆浴場について、３０３ページの産後ケア事業、３１７ページのリサイクル活動支援事業について質問します。公衆浴場についてなのですけれども、事項別説明書を確認すると、公衆浴場物価高騰支援金が２１施設に毎月１０万円、こちらは一律になっていますが、どの浴場においても規模感などは近いものなのでしょうか。","respondent":"若生健康課長","answer":"物価高騰対策支援金につきましては、営業を続けているという前提ですけれども、一律どの浴場も固定の金額ということで支給する予定の支援金です。","voiceIndex":60,"id":"exchange-028"},{"speaker":"せらく委員","kind":"確認","question":"要綱も確認いたしまして、営業している月を申告することになっているかと思います。品川区では、物価高騰などで、公衆浴場への補助、補正予算の追加や、公衆浴場の確保対策として設備更新に対する補助、あと公衆浴場では高齢者福祉の事業で出会いの湯などが行われています。品川区民にとって公衆浴場とはどのような意義があると考えますか。","respondent":"若生健康課長","answer":"公衆浴場の意義です。公衆浴場につきましては、品川区内の公衆衛生の向上を期するものとして、区民の方の公衆衛生といったところでの利益になるというところで、区としても改修の支援や物価高騰の支援等を行っているところです。","voiceIndex":62,"id":"exchange-029"},{"speaker":"せらく委員","kind":"確認","question":"続きまして、産後ケアについては、次年度の方向性も、先日お話があったとおりに確認しています。そして、実績についても先ほど、ひがし委員の質疑の中で、令和６年度、結構高い目標だったと思うのですけれども、しっかり利用者が増えたことを確認させていただきました。","respondent":"石橋品川保健センター所長","answer":"利用者が大幅に増えているということについてになります。こちらにつきましては、やはり大幅に拡充したこと、あとは利用しやすく、利便性の向上等に努めたことが一因と考えております。","voiceIndex":64,"id":"exchange-030"},{"speaker":"せらく委員","kind":"質問","question":"産後ケアについては、宿泊型について、議員になり初めての決算特別委員会で触れさせていただきまして、そのときは対象者が初産のみ、産後１０週までと、利用できる範囲が結構限定的だったという記憶があります。公衆浴場が多くあり、区民の健康増進のために、公衆衛生のために、その維持にも力を入れている品川区ならではの産後ケア施策に期待したいのですが、藤沢市の取組について、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"今後、産後ケアの実施の場所につきましては、銭湯というご提案もありましたが、いろいろ検討を重ねさせていただいて、安全にケアを受けていただける場所を、利用者の要望を伺いながら考えていきたいと考えています。","voiceIndex":66,"id":"exchange-031"},{"speaker":"せらく委員","kind":"質問・要望","question":"やはり安全というところは大事だと思いますので、今後いろいろ利用者の声などをお聞きして考えていただけるということを確認いたしました。お風呂に入ることで母親同士の交流もできるのではないかと考えております。ぜひ、いろいろな形でサポートを行っていただきたいと思います。次に、リサイクル活動支援事業についてお聞きします。こちらはオンラインで画像と情報を併せて確認できます。","respondent":"篠田品川区清掃事務所長","answer":"今年度につきましては、現時点で出品数が２,１０９点で、引渡し件数が２,０４５点となっています。情報紙「くるくる」です。こちらは昨年度が、掲載件数が１３９件で成立件数が１３件、今年度、令和６年度が、掲載件数が１０７件で成立件数が１３件となっています。","voiceIndex":68,"id":"exchange-032"},{"speaker":"せらく委員","kind":"質問・要望","question":"「くるくる」のほうは、やはり紙で配布されている情報紙なので、なかなか届かないところもあったり、あとは文字での情報なので、どのようなものが出品されているのか分かりにくいのかと思いまして数字を確認させていただきましたが、あまり交渉が成立していないのかと思います。引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"私からは、２９５ページ、健康教育事業、３０５ページ、不妊治療等支援事業、３１１ページ、こころの健康づくり事業についてお伺いいたします。１点目に、健康教育事業についてお伺いいたします。歳入の続きで、べてるの家の当事者研究の事例をご紹介します。べてるの家では、主に精神障害を抱えた１７歳から７０歳代までの１００人以上の当事者が、北海道浦河町で多種多様な活動を行っています。","respondent":"三ツ橋荏原保健センター所長","answer":"様々なことで精神的なお悩みを抱えていらっしゃる区民の方に対して、保健センターでは保健師や心理士などがご相談に応じ、様々な個別支援を行うとともに、専門医相談、講演会など各種、こころの健康づくり事業を実施しています。","voiceIndex":72,"id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"今、ポピュレーションアプローチということで、広く伝えていただいているということなのですけれども、そういった当事者研究をその場でということではなくて、当事者研究の中でポピュレーションアプローチに対しても有効な考え方や理念などといった部分があるかと思いますので、そういったところをぜひ取り入れていただきたいということで、ぜひ広めていただきたい。","respondent":"若生健康課長、福地大井保健センター所長","answer":"ご紹介いただいたところで、私どもが実施している不妊治療等支援事業の関連で申し上げますと、まずポルノ依存等の影響で性機能障害や男性不妊につながるというような視点に関しまして。東京都立中部総合精神保健福祉センターが行っています本人プログラム、家族講座の紹介をするとともに、保健師等は研修会に参加し、対応技術を高めるように努めております。","voiceIndex":74,"id":"exchange-035"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。依存の部分なのですけれども、保健師はすごく知見が高くていらっしゃって、いろいろな研修を受けていただいていますので、ぜひそういった知識や海外の事例といったところを引き続き高めていっていただきたいと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-036"},{"speaker":"こしば委員","kind":"質問・要望","question":"私からは、３０９ページ、予防接種費に関連して、ＲＳウイルスに対するワクチンについて、また、３２９ページのデジタル商品券発行事業についてお伺いいたします。順不同ですが、初めに、品川区が来年度から運用を開始いたしますデジタル商品券について質問をいたします。そこで、まずお聞きいたします。デジタル商品券導入の目的や、期待される効果についてお伺いいたします。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"２点目の効果につきましては、デジタル商品券の導入によって、これまで紙の商品券というのは割と４０代から６０代の方たちのご利用が多かったところですので、新しくデジタルというところで、若年層の利用の拡大を図っていきたいと考えているところです。","voiceIndex":79,"id":"exchange-037"},{"speaker":"こしば委員","kind":"質問","question":"確かに統計を見ましたら、昨年の紙の共通商品券を購入した世代を割合で見ますと、２０代の方は大変少なく４％と伺っております。この原因をしっかり分析した上で、課題解決のために、このデジタル商品券の導入に至ったものとも考えておりますが、改めて、若年者の割合４％というものをどのように分析されたのか教えてください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"そういったところで、デジタルの商品券の導入に当たっては、対象店舗の拡大も図ってまいりたいと考えているところです。","voiceIndex":81,"id":"exchange-038"},{"speaker":"こしば委員","kind":"質問","question":"ぜひ、若年者の利用を増やすことにつながると考えておりますので、取組に期待したいと思います。若年層にとっての魅力的な仕組みをつくるためには、利便性というのももちろんですが、まずもって消費の喚起を明確にすることが重要だと考えております。その点について、消費の喚起に向けた取組についてどのように検討されているのか、教えてください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"消費の喚起についてです。来年度は、紙の商品券も実施しながらデジタルの商品券も実施するというような、両方で実施していくところです。","voiceIndex":83,"id":"exchange-039"},{"speaker":"こしば委員","kind":"質問・要望","question":"お店側の負担が大きくならないように、導入時の負担、また事業者に支払う手数料の負担を極力軽くしていただくことを検討いただきたいと思いますとともに、決済後に実際に売主の口座に売上金が振り込まれるまで、大体１か月ほどの時間がかかるとも言われておりますが、デジタルだからこそ、スピードを持って振り込まれるよう検討いただきたいと思いますが、併せてお考えを教えていただきたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"現在、区としましては、デジタル商品券を実施していくに当たっての委託事業者のプロポーザルをこれから実施していくところでございまして、そちらの提案の中で、事業者の負担をいかに軽減して、そして区民の利便性を向上していくか。","voiceIndex":85,"id":"exchange-040"},{"speaker":"こしば委員","kind":"質問・要望","question":"続きまして、予防接種に関連して、ＲＳウイルス母子免疫ワクチン、アブリスボについて、再度お尋ねいたします。昨年の決算特別委員会で私から、ＲＳウイルス母子免疫ワクチンの接種費用の助成について要望を行わせていただきました。前回、課長からご説明いただきましたように、ＲＳウイルス感染症は、生後６か月までの赤ちゃんにとって、最も死亡や入院のリスクの高い感染症です。","respondent":"五十嵐保健予防課長","answer":"今年度に入りまして東京都では、少し増えたりしていましたが、横ばいのような状況になってございまして、全国的には少し増加傾向が見られているような状況になってあります。","voiceIndex":87,"id":"exchange-041"},{"speaker":"こしば委員","kind":"質問・要望","question":"しかし、もし免疫ワクチン、アブリスボを妊娠中の女性に接種すれば、赤ちゃんは生まれて６か月、お母さんからもらった免疫で守られることになります。昨年の決算特別委員会では、接種費用の助成について要望を行いましたが、残念ながら実現には至りませんでした。予算でアブリスボに対する接種費用助成がなぜ見送られたのか、ご説明をお願いしたいと思います。","respondent":"五十嵐保健予防課長","answer":"区としましては、やはり妊婦に対する投与ということでセンシティブな問題になるという部分と、妊婦が広域で産婦人科を受診されているというところもございまして、区だけで実施するというところは難しいかと考えておりますので、国の状況を見守っているところです。","voiceIndex":89,"id":"exchange-042"},{"speaker":"こしば委員","kind":"確認","question":"丁寧なご説明をありがとうあります。その結果、我が国のアブリスボの市販後の市場調査でも、またアメリカのＡＣＩＰという、要はアメリカの政府においてワクチンに関する勧告を行う唯一の機関ですが、このＡＣＩＰの研究報告でも、ＲＳウイルス母子免疫ワクチンを接種しても、早産・低体重のリスクは増加しないことが確認されたわけです。この現状を区はどのようにお考えでしょうか。教えてください。","respondent":"五十嵐保健予防課長","answer":"そちらがうまく解消できて、妊婦の方たちにも安心して打っていただけるように、国の指針を待ちながら様子を見させていただきたいと考えているところです。","voiceIndex":91,"id":"exchange-043"},{"speaker":"こしば委員","kind":"質問・要望","question":"課長の答弁もよく分かりました。いろいろな情報が飛び交う中で、やはり大切な情報・事実に基づいた客観的なものを、妊婦の方々が知れるような取組をぜひ進めていっていただきたいと思いまして、また重ねて強く、ＲＳウイルス母子免疫ワクチンの接種費用の補助を、また本予算特別委員会でも要望いたしまして、私からの質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"これまでグリーフケアの観点というのは、いろいろなところで当事者意識の拡充・必要性というのは繰り返し求めてきて、少しずつだと思うのですけれども、品川区で取り入れていただいている。様々な対応がありました。感じるところもありました。そういう中で、品川区における職員の皆さんのグリーフケアの観点の研修や、対区民に対する部分というのは、今、どういう体制になっているのか、まず教えてください。","respondent":"遠藤健康推進部次長","answer":"当然、傾聴や、区民の方に対して寄り添うというのは非常に大事な観点と考えておりますので、そういう部分は大学の教授などを呼んで、いろいろ講義などを受けているところです。","voiceIndex":95,"id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"寄り添うべきなのか。民民です。品川区であれば、１３の地域センターや、支え愛・ほっとステーション、協働の観点で言えば地域町会の方など、そういった存在が非常に緩やかなつながりというか、そういったところの支援策の拡充というのが非常に大切だなと。学校の養護の先生とも相談して、スクールカウンセラーの先生にもいろいろお話を伺って、いろいろなアドバイスを頂いて、今やっている。","respondent":"森澤区長","answer":"いろいろな健康の部門、心の部門だけではなくて、様々な窓口でしっかりとそういった思いに寄り添っていくことが大事だと思いますので、そういった研修も含めて、今後しっかりと取り組んでまいりたいと考えています。","voiceIndex":97,"id":"exchange-046"},{"speaker":"つる委員","kind":"意見","question":"今、一生懸命頑張ったけれども、国でも頑張ったけれども、所得制限があって、税法上、独り親ではないのだなという課題にも、新たに見えてくる視界もありますし、また、今私が、これまでもそうですけれども、これからも生きていこうと思えるのは、私が所属している政党の公明党は大衆のためという立党精神があって、これはどのような状況であろうとも、おのれの命は大衆のために、福祉向上のために。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-047"},{"speaker":"おぎの委員","kind":"提案","question":"こちらは、厚生労働省２０２５年２月１８日公表の健康被害救済制度認定数です。ワクチンは本来、１０年以上かけてしっかりと安全性を確認して使用されるべきものですが、今回のｍＲＮＡワクチンは、全く新しいワクチンにもかかわらず緊急で承認されたため、誰も接種後１０年の経過を見たことがありません。紙に比べて保管しやすくなりますので、品川区でも保管期間の延長を提案しますが、いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"コロナウイルスワクチンの予防接種記録についてですが、ほかの予防接種と同様に、現在、紙のものにつきましては５年で廃棄しているような状況ですが、デジタル化して保管しているものがございまして、そちらについては今の時点で保管の年数は考えていないところですが。","voiceIndex":101,"id":"exchange-048"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今のところは５年ということですが、今後の動向を見て、できれば検討していただきたいと思います。令和８年３月で、初めてのｍＲＮＡワクチン接種から５年が経過する１つの区切りの時期でもあります。新規事業の５歳児健康診査事業についてお伺いします。はこの事業の狙いと、５歳児に設定した理由をお聞かせください。","respondent":"石橋品川保健センター所長","answer":"５歳児健康診査につきましては、国でも全国展開を積極的に進めていきたいという形で、推奨といいますか、通知が出ている事業になりまして、区としましても、子どもと保護者が安心して学校生活を送るために、就学時健診より早期に、円滑な就学に向け。","voiceIndex":103,"id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"円滑な就学に向けて、就学時健診よりも早期に、５歳のこの時期に発育状況や社会性の発達などの確認をするということですので、必要に応じて早めにサービスや支援につなげていただきたいと思います。５歳児健康診査に付随して、子どもの発達障害についてお聞きします。担当課として何かあればお聞かせください。","respondent":"石橋品川保健センター所長","answer":"引き続き、５歳児健康診査も実施することも踏まえまして、５歳児健康診査の事後フォローというところで、そのお子さんに今後どうやって継続的な支援をしていくかというところも含めまして、しっかりと対応していきたいと考えております。","voiceIndex":105,"id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問・要望","question":"状況を見ながら、ぜひ子どもの成長に寄り添った支援をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、３１１ページの、こころの健康づくり事業から自殺対策、それから３０７ページ、成人歯科健診から障害者歯科健診について、それから３１５・３１７ページで、環境啓発・推進事業と資源物再商品化経費について伺います。相談窓口がいっぱい書いてあるので、逆にどこに相談していいか分からないのではないかという懸念もあったのですけれども、その相談窓口の成果について、まず伺います。","respondent":"五十嵐保健予防課長","answer":"相談窓口の効果についてですけれども、どこの相談窓口に相談がとても増えたというようなデータは取っていないところではありますが、恐らく、心の問題がないときにはあまり気にならない状況で皆さん過ごされているかと思うのですけれども、少し気になったときに。","voiceIndex":109,"id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も全然、アナログ人間なので、インターネットと言われると、はっ、という感じなのですけれども、「死ぬ」、「自殺」などというキーワードが出てきたときは、適切なところに結びつくという意味では、電話の相談とインターネットの相談がうまく結びついて、自殺に限らずいろいろな事前の悩みの相談に結びつけられるような仕組みができたらいいと思うのですけれども、何かお考えがあれば伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"相談はかなり、必要があれば継続して聞いていただいているような状況でございまして、必要があれば区に連絡も頂いて、つなげていただいたりということで、連携を取らせていただいて、やらせていただいているところになってあります。","voiceIndex":111,"id":"exchange-053"},{"speaker":"吉田委員","kind":"質問・要望","question":"次には、成人歯科健診の中から障害者歯科健診について伺います。せっかくいい制度なのに、とても残念だと思って、対象を広げていただけないだろうかということを再三質問してきたのですけれども、その点についていかがでしょうか。それから、今の障害者歯科健診の利用者数など、本当にかつては低かったのですけれども、その辺の増減といいますか、その点についても伺いたいと思います。","respondent":"若生健康課長","answer":"昨年度、品川・荏原両歯科医師会にも、こういったお話で、障害者歯科健診をどうにかしなければいけないというところで協議を進めてまいりました。検討会も、障害者支援課にも入っていただいて行って、検討を進めてきたところです。","voiceIndex":113,"id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"引き続き、これからも、障害の種類もいろいろありますので、ぜひ当事者の方たちのご要望を聞きながら改善を進めて、利用者を増やしていっていただきたい。次に、環境啓発・推進事業について伺います。使い捨てプラスチックの削減推進の具体策はどうなのでしょうか。その辺の協力体制はどうなのでしょうかということと、再三、環境のところで申し上げております。","respondent":"中西環境課長","answer":"今、事業者の方々のアイデア等もいろいろ聞きながら、お話をしながら、何か区でできるかといったことは検討していますので、引き続き、様々な形で取り組んでまいりたいと考えています。人工芝の関係です。","voiceIndex":115,"id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"こちらこそ、度々同じ質問をしましてすみません。その状況を放置し、かつ推進してしまうような政策はいかがなものかということで、しつこくしつこく伺っております。それで、資源物再商品化経費について、再商品化の仕組みについて前に質問して、従来型の、日本容器包装リサイクル協会に依頼してというところまではご答弁を伺っているのですけれども、その後の何か進展があったら伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"ですので、例えば大臣認定をして、区独自の再商品化をしようとしても、それを引き受けてくれる事業者を探すのが非常に大変だ、難しいという状況があって、なかなかほかの自治体を含めてできない状況があるものと認識しています。","voiceIndex":117,"id":"exchange-056"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、ぜひ品川区の中でもセミナーをやっていただきたいということで強いプッシュがありまして、地域産業振興課長にお願いをいたしまして、そうしたら、「単独のセミナーは無理だけれども、説明会の中にその考え方を入れることは講師にお願いしてみます」ということで、非常にきちんとした資料を作っていただいて、私も頂きましたけれども、本当に労働者協同組合のことがきちんと説明されていて。","respondent":"小林地域産業振興課長","answer":"ただいまご質問のありました、労働者の協同組合ということで、１月３１日のセミナーの中でも、シニアの今後の多様な働き方ということを１つ、テーマにしまして、今までですと、シルバー人材センターや、あるいは企業の中の再雇用といった形で、雇用をある程度。","voiceIndex":119,"id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"いいご答弁を頂きまして、ありがとうございました。出資して、運営して、自ら働くという働き方は、私もこういう役割を終えた後の、今後の働き方の形として考えていきたいと考えていますし、ぜひ皆さんにも知っていていただきたいと思います。これは要望でとどめます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３２０ページから始まる産業経済費に関わって、中小・零細企業支援を求めて伺います。もう物価高騰が３年ぐらい続き、下がる見通しもないという中で、中小・零細企業の状況が大変になっています。現在の中小・零細企業の状況がよくなっているのか、悪くなっているのか、区の認識を伺います。","respondent":"小林地域産業振興課長","answer":"各種の経済統計などを見ましても、消費者物価あるいは企業物価、倒産件数といったものを見た場合でも、なかなか厳しい状況が続いていて、今後、令和７年度の予算案も含めまして、行政の支援というのは引き続き必要であろうと考えているところです。","voiceIndex":124,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"その理由を伺います。併せて、１月末で打ち切られた省エネルギー対策・業務改善設備更新助成金については、代表質問で実施を求めたところ、区は、政府支援が復活しているとして、今後の政府の取組などを注視しつつ、引き続き必要な事業者支援策を検討するとの答弁でした。この状況を見ると、喜ばれていた省エネルギー対策・業務改善設備更新助成金を復活させるべきではないかと思いますが、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"政府の激変緩和措置といいますか、補助についても、年間を通じて断続的にといいますか、予算措置の中で機動的に、いろいろ補助が復活する時期、そうでない時期というのはあるわけですけれども、我々はこの動向については引き続き注視して。","voiceIndex":126,"id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"省エネルギー対策・業務改善設備更新助成金については、タイミングを見てというお話でしたけれども、今、政府の電気・ガス代支援が終わっているという状況を見れば、実施するときではないかと思うのですけれども、いかがでしょうか。業種を限定せずに、固定費である家賃や水道光熱費の補助をぜひしていただきたいと思いますが、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"まとめてという部分がありますけれども、固定費というところで、電気代やガス代といったところも含めて、直接的な支援といいますか、そういうものを継続する場合に、こういった支援をどこまで続けるかという点も、１つ、論点にはなり得るかと思います。","voiceIndex":128,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"利益が上がらなくても、家賃や電気代、水道代などの固定費がかかってきてしまいますので、ぜひ固定費への補助をお願いしたいと思います。以前は区でも家賃支援助成というのをやっておりましたので、ぜひ、そうしたことも踏まえて実施していただきたいと思いますけれども、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"過去に家賃支援の助成ということでございましたけれども、これは委員のご指摘というのは、コロナのときに実施していた、国と都がやっているものに対する、区の上乗せ助成ということで、家賃支援給付です。","voiceIndex":130,"id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"確かに、どこまで支援するかという状況はあると思いますけれども、やはりこれは、ずっと物価高で景況は大変だという状況が続いておりますので、今は支援するべきときではないかと思いますので、固定費補助、あと省エネルギー対策・業務改善設備更新助成も、ぜひ実施していただきたいと思います。むしろ、省エネルギー対策・業務改善設備更新助成はもう恒久的な制度にすべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"３０４ページ、生活衛生費より、災害時の食事の質の確保やキッチンカーの活用について、保健所の役割を発揮させるための計画策定と訓練を求めて質問したいと思います。そこで、まずこの講演会ですけれども、参加者からどういった感想が寄せられたのか伺います。そして、講演会を受けて、今後、保健所として防災計画・防災対策に反映させたいもの、今後充実させたいものは何か、お考えを伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"２点目のご質問になりますけれども、この講習会を含めて、今後の保健所としての防災意識の向上や普及啓発ですけれども、区民向けの講習会のアンケートにもありますとおり、大変興味の高いテーマだったというところで保健所としても認識しておりますので、引き続きこういった形で。","voiceIndex":134,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"私もそのとおりだと思います。改めて、保健所としてはどういった計画や訓練が必要だと思っているのか伺いたいと思います。保健所は日常業務の中で、キッチンカーや飲食業の方々と、営業許可や保健指導で関わりがありますので、保健所としてもキッチンカーや飲食業界との連携を深めて、災害時の食事の提供へ、保健所としての力を発揮していただきたいと思いますが、併せていかがでしょうか。","respondent":"赤木生活衛生課長","answer":"そういった中で、保健所の職員の役割として、食品の安全の確保のために、避難住民に対する食品の衛生的な取扱いの指導等を行うというところになっておりますので、こういったところの部分につきまして、区内一斉防災訓練などといった訓練の機会を通じまして。","voiceIndex":136,"id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"今お話があったように、保健所としては衛生指導を行っていくといった役割が書かれていると思います。当日の講演会でも、東京都保健医療局の話で、例えば避難所で配られたおにぎりによる食中毒の事例などが紹介されて、避難所での対応について、例えば作り置きはしないで、調理後は２時間以内に食べるように提供するというお話もありました。改めて、今後の取組や具体化についてお考えを伺いたいと思います。","respondent":"赤木生活衛生課長","answer":"繰り返しとなりますけれども、保健所としましては、食品衛生の安全、食の安全という部分につきまして努めていきたいと思っているところと、そういった知識や技術といった部分につきまして、様々な機会を捉えて普及啓発に取り組んでまいりたいと考えています。","voiceIndex":138,"id":"exchange-066"},{"speaker":"澤田委員","kind":"質問","question":"本日は、３１９ページ、収集運搬作業費、３２３ページ、中小企業事業資金融資あっせん、時間があればチャレンジ支援資金もお願いしたいと思います。は３１９ページ、収集運搬作業費についてです。１４億６,７８５万８,０００円の予算のうち、車両雇上げ費が１２億５,７５６万８,０００円と一番大きな金額でありますが、車両雇上げ費とはどのような費用なのか、内容をご説明いただけますでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"予算書に載っているのは、そちらの一般のごみの分と粗大ごみの分の両方を合わせた経費となっています。","voiceIndex":141,"id":"exchange-067"},{"speaker":"澤田委員","kind":"質問","question":"民間・直営ともに、車両や人件費にも多くかかっているということだと思います。品川区では、可燃ごみ、不燃ごみともに個別回収となっているため、ごみの収集の際、車を何度も乗り降りするので体力的にも負担が大きく、すぐに離職してしまう方も多く、ドライバーについては２０２４年問題もありますし、人材確保が大変厳しいとお聞きしています。","respondent":"篠田品川区清掃事務所長","answer":"ごみ収集運搬のＤＸ化についてのお尋ねです。収集運搬作業というのが、人がやる作業ということですので、なかなか効率化というのが実は難しい部分がかなりあるとは認識しています。","voiceIndex":143,"id":"exchange-068"},{"speaker":"澤田委員","kind":"質問・要望","question":"今、様々調べていただいているというところで、ぜひ前向きにご検討いただければと思います。関連して資源ごみについてお聞きします。ほかにも、エコルとごしのごみ分別ゲームにおむつを加えてみるなど、おむつごみの捨て方をはじめ、ターゲットを絞り、他課と連携して、ごみの分別についての周知啓発の強化を進めていただきたいと考えますが、ご見解をお聞かせください。","respondent":"篠田品川区清掃事務所長、中西環境課長","answer":"不勉強で申し訳ないのですけれども、どういった形で、お配りするときに周知しているかというのは私どもも把握していないところはあるのですけれども、そういったときというのは。今月の２８日にも、清掃事務所と資源化センターに行って、捨てたごみがどのようになっていくかといったことを学ぶといった機会も設けてありますので、今後も様々な場面で連携してまいりたいと考えています。","voiceIndex":145,"id":"exchange-069"},{"speaker":"澤田委員","kind":"質問","question":"環境課とも連携して、またできれば保健センターなど、ほかの課とも連携して、様々、周知啓発に努めていただければと存じます。続きましては、３２３ページ、中小企業事業資金融資あっせん、チャレンジ支援資金についてご質問いたします。昨年の全国倒産件数は前年比１５.１％増の１万６件、１１年ぶりに倒産件数が１万件を超え、中小企業にとって大変厳しい経済状況であると言えます。","respondent":"小林地域産業振興課長","answer":"コロナ期においては、経営変化対策資金というメニューを新たにつくりまして、３年間無利子、３年間の据置期間というような特例措置も設けまして、区内企業の支援を行ってまいりまして、その後も、区内事業者を今我々が支援している融資総額ですけれども。","voiceIndex":148,"id":"exchange-070"},{"speaker":"澤田委員","kind":"確認","question":"様々な取組を行っていただいていることは確認できました。コロナ禍での企業倒産は全国的に低い水準でありました。国や都をはじめ、区の支援策によって救われた区内中小企業も多かったのではないでしょうか。原材料費やエネルギー価格の高騰が企業にとって頭の痛い問題となってきておりますが、区として物価高騰対策として具体的にどのような取組を進めてきたのか、お聞かせください。","respondent":"小林地域産業振興課長","answer":"ただいまご質問いただいた物価高騰ということに関しまして申し上げれば、融資あっせんのところでいけば、我々、原油価格物価高騰総合資金、翌年度には物価高騰等総合資金と名称を改めておりますけれども、そういったところを通じて。","voiceIndex":150,"id":"exchange-071"},{"speaker":"澤田委員","kind":"質問・要望","question":"都で３分２の費用の支援があって、区としても３分の１、ぜひこれから考えていただいて、前向きに検討していただければと思います。さらに、中小企業にとっては物価高騰以外にも、人材不足への対応やＤＸ化を求めるなど、新たな経営課題が様々出てきています。区としてはどのような対策を講じていくつもりなのか、教えてください。","respondent":"小林地域産業振興課長","answer":"ＤＸやＧＸ、あるいは新規事業展開といった新たなテーマについて、金利負担をゼロにするような形で、今までよりも拡充した支援というのを考えてまいりたいと考えています。","voiceIndex":154,"id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３０７ページ、健康診査、３０９ページ、アピアランスケア支援経費、３２９ページ、デジタル商品券発行事業の３点を伺っていきたいと思います。これは都の補助金というか、それを使ってのものなので、それを使ってもいいというふうになることが前提なのですけれども、そうなった時点から、区が対象拡大で進めていくスピード感、どのような段取りで進めていくのかについてお伺いしたいと思います。","respondent":"若生健康課長","answer":"がん以外の、エピテーゼといったところまでの拡充ですが、これにつきましては、現段階では、東京都の補助要綱などといった補助の内容というところが具体的に出てきていない部分ではございまして、「アピアランスケア等」ということで、「等」を補助事業の名称に。","voiceIndex":158,"id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"ありがとうございました。来年度の８月から申込なのです。ここで使えるお店や、あるいは品川区としても２０％ポイント還元を昨年実施していただいて、これで使えたお店といったところが１つの参考として考えられるのかと思いますけれども、いかがでしょうかというのが１点目。それから、デジタル商品券の購入者は区民に限るのか限らないのかというところについて、お伺いしたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"先ほど午前中の答弁で大型店舗という話をさせていただいたところですけれども、今年度、区では、デジタル商品券を先行で実施している自治体の調査などをしている中で、これまで商品券事業というのは、個店、とりわけ商店街支援の側面を強くやっていたところですけれども。","voiceIndex":160,"id":"exchange-074"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。８月から申込み開始ということで、現段階で、このシステムの仕様というのはもう固まっているというか、他自治体などでもやっているので、そういったものをそのまま使うということが前提として決まっているのか。具体的には、１つは店舗側の決済手数料がかかるのか、かからないのか。この辺のシステム周りのことについてお伺いしたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ですが、午前中の質問にもございましたけれども、個店商店におかれましては手数料が、負担がかかるということは大変認識しておりますので、そういった観点も含めてきちんと業者選定はやっていくことを考えているところです。","voiceIndex":162,"id":"exchange-075"},{"speaker":"塚本委員","kind":"質問","question":"一方、やはり心療内科などは、ざっとネットなどで調べると区内で３１件ぐらいで、内科は２４１件ですので、やはり少ないというところで、なかなかすぐに医療に行きづらいというところも、あまり一般的ではないというか、なかなかそういう病気で医者に行きにくいというか、そういったものもある中で、区の事業として精神衛生系の健康診査みたいなことを。","respondent":"三ツ橋荏原保健センター所長","answer":"区として、区民の方に対してまずはご相談を受けるというのが、保健センターでは丁寧にご相談を受けているところです。","voiceIndex":167,"id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"質問","question":"区は去年、大手コンビニチェーンとＡＥＤの設置の協定を結ばれて、区長もローソンと一緒に協定の会見をされておりますけれども、現状、コンビニへの設置状況と、今後、それ以外の施設でのＡＥＤの設置の予定、助成も含めてなのですけれども、そんなところをもしお伺いできればと思うのですが、いかがでしょうか。","respondent":"若生健康課長","answer":"コンビニ以外の設置につきましては、現状では２９６台、区の関係施設に設置しておりますが、そのほかに大幅に増やしていくというところでは、今のところ予定はないところですが、各所管で設置が必要と判断された場合は、健康課にご相談いただいた上で、予算等に上げていって。","voiceIndex":170,"id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"提案","question":"そこで提案したいのが、通所型や入居型の介護施設への設置助成です。ぜひ品川区の施設にもお願いしたいというところで、例えば区営の施設は３０か所ぐらい、通所・入所があって、そこは大体全部あると思うのですが、民間の施設は８０か所から９０か所ぐらいあるのですけれども、仮にそこに全部置いたとして、月４,０００円のリースが今あるのです。ぜひご検討いただきたいのですが、いかがでしょうか。","respondent":"若生健康課長","answer":"そもそも民間の施設につきましては、運営法人で必要に応じて設置の手続を進めているというところもありますので、そういったところは各所管で検討を進めているようなところかと認識しております。一方、健康課としましては、コンビニ設置というのを大幅に進めてきたところです。","voiceIndex":172,"id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"確認","question":"思ったような答弁ではなかったのですけれども、ぜひ、やはり介護施設でＡＥＤがどこにでもあるというのは利用者の安心にもつながると思いますので、前向きにご検討いただければと思います。次ですけれども、見守り定期便、おむつ定期便です。別の日に質疑がありましたけれども、利用者の満足度が９０％を超えていたと記憶しているのですが、その点を改めて確認させてください。","respondent":"石橋品川保健センター所長","answer":"２月に利用者のアンケートを行ったところ、事業全体の満足度が９２％という回答を頂いております。","voiceIndex":174,"id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"確認","question":"サービス全体でということだったので、この数字で注意しなくてはいけないのは、粉ミルクやおむつが３,０００円相当、物資の支給、支援があるという、それについての満足度なのか、本施策の要というか肝である見守りについての満足度なのかというのは、切り分ける必要があると思います。そういったアンケート調査になっていないということでよろしいですか。確認です。","respondent":"石橋品川保健センター所長","answer":"ただ、実際、相談状況としてアンケートを取っておりまして、「相談を行っていますか」というアンケートに対して、昨年度よりおよそ８％上昇しており、開始より、相談支援に対する評価が上がっていると認識はしています。","voiceIndex":176,"id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"実際の利用者、利用されている方から、訪問員の雰囲気が、相談できるような感じでないというような声を聞いたりしていますし、実働９名、今、動いている方がいらっしゃるうち、有資格者が１名ということで、相談体制がやはり弱いのではないかというのは、どうしても感じてしまうところです。実施可能でしょうか。","respondent":"石橋品川保健センター所長","answer":"今後、アンケートにつきましては、どういったところを検証課題にするかということを踏まえまして、受託者と連携して、またしっかりと調整して実施してまいりたいと考えております。","voiceIndex":178,"id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それと併せてですけれども、もともとこれは有資格者を中心に１２名、配達の職員を配置するという話だったと思います。今はほぼ、無資格者の方が多くて９名ということなので、こういったところの改善も、ぜひ受託先にしっかり区のほうで、もともとはそういう話だったので、もっと手厚くしてくださいというようなことを求めていっていただきたいと思います。最後にお願いします。","respondent":"石橋品川保健センター所長","answer":"その辺りにつきましては、今後検討してまいります。","voiceIndex":180,"id":"exchange-082"},{"speaker":"松永委員","kind":"質問・要望","question":"私からは、３０５ページの猫の適正飼養および活動支援事業について、３１３ページの環境対策費の野鳥への餌やりについて、３２３ページの武蔵小山創業支援センターについて、時間がありましたら３０７ページのネズミ対策事業について伺います。初めに３２３ページの武蔵小山創業支援センターについて伺います。こうした天職を求める方は多いかと思います。区として工夫されている点はありますでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"昨今は、割とオンラインで物を販売したり、小さい資金で起業できるようになったことから、割と女性の起業家が増えてきたところではあるのですけれども、それでも全体の起業家からするとまだ２５％ということで、少ない実情ですので、行政としてはこういったところの。","voiceIndex":183,"id":"exchange-083"},{"speaker":"松永委員","kind":"質問","question":"先ほど、例えばより一層の支援ということでございましたけれども、具体的にどういった支援なのかお知らせください。テストマーケティングについて、どういったものなのかを改めて伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"それから武蔵小山創業支援センターでＬＩＮＥのアカウントを持っておりまして、そのＬＩＮＥの会員が２,０００名弱おりますので、その方を対象にしたモニターや起業家のサービスと、それを活用して学びたい人をマッチングするカルチャースクールなども実施しています。","voiceIndex":185,"id":"exchange-084"},{"speaker":"松永委員","kind":"確認","question":"あさっては予算特別委員会があると思いますので難しいかと思いますが、よろしくお願いします。これはとても重点的な取組であるということが確認できましたので、ぜひとも今後もしっかりとした形で取り組んでいただければと思います。これは以上になります。次に、３１３ページの環境対策費の、野鳥への餌やりについて伺います。こうした視点から質問いたします。その理由について伺いたいと思います。","respondent":"中西環境課長","answer":"餌やり防止看板の記載内容のお話です。ハトに限らず、例えばムクドリや、ほかの野鳥のご相談が来る場合もありますので、そういうところでそういった記載になっているものです。","voiceIndex":187,"id":"exchange-085"},{"speaker":"松永委員","kind":"意見","question":"その中でも特に被害という観点から、「ハト」という文言も入れていただければと思います。ハトの餌やり禁止条例を制定されている自治体は、２３区内では、平成２０年から荒川区が早く条例制定をされて、それから世田谷区、大田区、港区、板橋区、豊島区など、様々なところで条例が次々に制定されております。その内容につきましては、５,０００円の罰金などとしている自治体もあります。","respondent":"中西環境課長","answer":"１つ、学説の中でも、動物に餌をやるという行為を禁止して、そこに罰則をかけるといったことが、果たして法的に大丈夫なのかといった議論もあるといったところも聞いてありますので、どういった形で効果が出せるかといったところはこれから研究してまいりたいと考えています。","voiceIndex":189,"id":"exchange-086"},{"speaker":"松永委員","kind":"提案","question":"３０５ページの地域猫活動について伺います。先ほどの質疑にもありましたが、地域猫によって苦労されている方からのご意見を伺わせていただきました。ぜひ、そうした方へのご理解の促進が必要であるという立場で伺います。本区では、猫の被害を受けた際、どういったご対応をされているのでしょうか。もしこうした補助が難しい場合は、被害を受けられている方への取組について併せて伺います。","respondent":"赤木生活衛生課長","answer":"被害を受けた方というところで、ふん尿被害というところでは、こちらとしても多数のご意見やご相談を頂いておりますので、そういったところにつきましては、個別の事案に応じて、それぞれ、こちらとしても真摯に傾聴させていただきながら。","voiceIndex":191,"id":"exchange-087"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、区としては調査をしていただいておるのですけれども、その調査の後、例えばいろいろ助言など、「ネズミ駆除にはこういう業者がいますよ」、「選定業者はこういうところがありますよ」など、いろいろ言ってくださるところはあるのですが、料金も高額なもので、なかなか難しいので、その辺をもし、リフォーム助成ではないですが、そうしたところの選定など。","respondent":"赤木生活衛生課長","answer":"ネズミの被害を受けられた方への助成という部分でのご質問かと思いますけれども、区としましては現在、ネズミ駆除費自体の助成というのは検討はしていないところではありますけれども、今後、他自治体の動向等も注視していきたいと思います。","voiceIndex":193,"id":"exchange-088"},{"speaker":"えのした委員","kind":"質問・要望","question":"商店街連携推進事業について。令和６年決算特別委員会では、区内の商店街イベントについて、東京都や品川区の支援の内容や状況について質問するとともに、東京都の補助金も入る大きなイベント以外に、小規模なイベントにも支援が行われているホリデー・トレーニング事業助成について、商店街支援をさらに拡充していただくよう要望させていただきました。そこでお伺いします。お聞かせください。","respondent":"小林地域産業振興課長","answer":"結論ですけれども、令和７年度の予算案におきまして、先ほど述べていただきました商店街連携推進事業という事業を新たに盛り込みまして、商店街と町会・自治会、ＮＰＯ、大学などと連携しながら、区の政策課題や地域課題について一緒に何か考えていく。","voiceIndex":196,"id":"exchange-089"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。政策評価委員会ですか、開催して、問題意識、様々ご意見があって、今までとは別に予算がついたということで、令和７年度からの新しい助成事業の内容について、ホリデー・トレーニング事業助成との比較があればお知らせください。","respondent":"小林地域産業振興課長","answer":"一方、新たに今回設定する助成金は、企業や団体、ＮＰＯなど複数の団体が連携するということを踏まえまして、助成金の上限は１イベント当たり４０万円、補助率を５分の４としまして、商店街の皆さん。","voiceIndex":198,"id":"exchange-090"},{"speaker":"えのした委員","kind":"確認","question":"助成率と上限も、２０万円から４０万円に上がったと、確認が取れました。同じく昨年１０月の決算特別委員会では、商店街に対する物価高騰支援についてもお伺いしました。商店街などへの支援実績はどのようになりましたでしょうか。令和６年７月から導入された新紙幣への対応券売機も本助成金の対象とする予定であるとのご答弁を頂きましたが、その動向なども併せてお伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"この点につきましては、令和７年度の新たな予算書の中に、ＤＸ・デジタル技術活用推進事業という支援対象も拡充しておりますけれども、この中で、省力化・省人化など人手不足対策につながる機器設備も新たに応援対象としておりまして、新紙幣対応券売機については。","voiceIndex":200,"id":"exchange-091"},{"speaker":"えのした委員","kind":"質問・要望","question":"当初１５０件から３８４件と倍ぐらい、件数が伸びておりますし、商店街の飲食業の厨房施設ですか、全体の５２％ということで確認が取れました。商店街支援や新紙幣券売機の支援も意識して、これは７件と少なかったところですけれども、補正予算や令和７年度予算が編成されていると確認が取れました。ご説明ありがとうございました。続きまして休日・応急診療費についてお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、３０６ページからの保健予防費について、メインは歯科健診についてです。それと、３０１ページの地域医療連携はＡＣＰ、アドバンス・ケア・プランニングについてお伺いします。時間があれば、３２０ページからの中小企業支援に行きます。初めに保健予防費であります。区の予防について、現在どのように取り組まれているのか教えてください。","respondent":"若生健康課長","answer":"基本的には、生活習慣病の予防という観点では、各種健康診査、歯科健診、それからがん検診等を実施しておりまして、まず健康な段階からスクリーニングということで自分の健康状態を把握していただいて。","voiceIndex":204,"id":"exchange-093"},{"speaker":"石田（し）委員","kind":"提案","question":"そのような中で提案したいのが、子どもの歯列矯正支援についてです。これは、ほかのところでは多分ほとんどやっていないのですけれども、これはぜひ品川区で、こういった歯列矯正の支援を行っていただき、子どものときから予防することによって、将来の医療費も削減するといった取組をしていただきたいと思いますが、いかがでしょうか。","respondent":"若生健康課長","answer":"こういった状況については、今後どういった形で、区が歯科の対応、特にお子様の歯科というところに関してできるかというところは考えてまいりたいと思います。","voiceIndex":206,"id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ取り組んでいただきたいです。続きまして、地域医療連携についてです。午前中に、つる委員から、本当に経験と思いの籠もった質疑がされていたので、私も今日やるつもりはなかったのですけれども、１つだけ、アドバンス・ケア・プランニングについてお伺いしたいと思います。現在、品川区では、いわゆる人生会議とも言われていますが、どのようにこれまで取り組んできているのか教えてください。","respondent":"若生健康課長","answer":"アドバンス・ケア・プランニングにつきましては福祉部で進めている事業と認識してございまして、私どもとしては、医療と介護の連携というところで、一定、医療のほうで関わっているところはありますけれども、詳しい状況については把握しているところではございません。","voiceIndex":208,"id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問","question":"もう、まさにここが課題なのだと思います。こういった中では、やはり医療従事者のチームやケアチーム、もちろん福祉の面も含めて、さらに言えば後見人などの連携といった制度をしっかりと構築し、取り組んでいかなくてはいけないという、これは本当に大きな、これからの日本の社会においても必要な制度だと思いますが、改めてこの点について、医療連携の部分でどのように感じているのか教えてください。","respondent":"遠藤健康推進部次長","answer":"私どももこれから、いろいろ福祉部門の勉強もしていかなくてはいけないところで、なかなかご答弁は難しい部分がありますけれども、そういう部分でしっかり周りの第三者も巻き込みながら進めていきたいと考えています。","voiceIndex":210,"id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問","question":"これを１つの指数として捉えている経済学者もいるわけです。カレーライス指数というのですか。目を品川区内中小企業に向けていると、いわゆる労働者の賃金を上げるために、中小企業の労働分配率は７０％から８０％です。であるならば、物価高対策もそうだし、賃金アップをするための対策というのもやはり考えていかなければいけないと思いますけれども、中小企業をどのように考えているのか教えてください。","respondent":"小林地域産業振興課長","answer":"区で様々な中小企業支援を行っておりますけれども、それは当面の資金繰りや事業継続ということではなくて、その先にある雇用の確保、あるいは賃上げをやっていくための余力をいかにつくっていくかということだと考えております。","voiceIndex":212,"id":"exchange-097"},{"speaker":"こんの委員","kind":"提案","question":"私からは、３０３ページ、５歳児健康診査、同ページで母子保健指導事業費、３０９ページ、予防接種。５歳児健康診査ですけれども、昨年の予算特別委員会の総括質疑でこの課題を挙げさせていただきました。この課題は、我が会派の先輩議員が２００５年より提案・要望してきた悲願の政策でした。ですので、いよいよこれが来年度実施されるということは大変に評価しております。","respondent":"石橋品川保健センター所長","answer":"そこから、国が参考として出しております５歳児健康診査マニュアル等を基に、区の手法もしっかりと考えて、次年度からモデル実施ということで進めてまいりました。","voiceIndex":216,"id":"exchange-098"},{"speaker":"こんの委員","kind":"質問・要望","question":"これも先日の一般質問で取り上げさせていただきました。内容的には、こちらが求める内容が網羅されていて、それを活用される区のお考えは理解いたしました。区で行う乳幼児健診、１歳半健診と３歳児健診は、リトルベビーも受診するようになると思いますけれども、都のハンドブックにおいては、乳幼児健診の記録のページがないので、これはどういうふうに取扱いをすると考えていらっしゃるでしょうか。","respondent":"石橋品川保健センター所長","answer":"リトルベビーハンドブック、東京都が出しておりますＮＩＣＵ退院支援手帳「のびのび」についてになります。こちらは東京都が本年度も改訂ということで、有識者等が集まってワーキンググループが発足し、改訂したものになります。","voiceIndex":218,"id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"なので、やはり品川区版という要望をしてきたのも、その意味も含めてのことです。ですので、２冊を持って使い分けるのは結構大変なことで、１冊でまとまっているということが非常に大事かなといった観点もあって要望させていただきました。そうした観点で、いま一度ご見解を頂きたいと思いますが、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"品川区としましては、今、こちらの手帳はいいものができていると東京都からも説明を受けておりますこともありまして、実際、こちらを積極的に活用して、様子を見て、今後のことを研究してまいりたいと考えています。","voiceIndex":220,"id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ研究していただいて、健診の記録は品川区の部分、こちらの記録は東京都のものと、要するに２つ合わせないと、一つ一つばらばらで記録するといったところのお母さんの負担と、後々お子さんが自分の記録を見たときに、２冊、あっちを見てこっちを見てということのないような手帳を求めていきたいと思いますので、今後研究していただきたいと思います。次に参ります。その辺を教えてください。","respondent":"五十嵐保健予防課長","answer":"Ｂ類疾病のほうは、個人の発症またはその重症化を防止して、併せて、これにより蔓延予防に資するためと決められているものですので、Ａ類疾病だから無料、Ｂ類疾病だからお金がかかるという分類にはなっていないところではありますが、ただ。","voiceIndex":222,"id":"exchange-101"},{"speaker":"こんの委員","kind":"確認","question":"Ａ類疾病、Ｂ類疾病、それぞれ自己負担はあると。特にＢ類だから自己負担だということではないということは確認いたしましたけれども、そうすると、Ｂ類疾病ということで、今回、帯状疱疹の定期接種化になるわけですが、一部自己負担という形は、どれぐらいを自己負担と予定されているのか教えてください。","respondent":"五十嵐保健予防課長","answer":"現在、まだ幾らということまでは決定できていない状況ではありますが、今までの……。","voiceIndex":224,"id":"exchange-102"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、３１３ページの温暖化対策事業について、それから２９５ページの保健師の体制、増員について伺いたいと思います。そこで、具体的に伺いたいのですけれども、今回、太陽光が最大２０万円に拡大されました。そのことによって、こういう助成というのは東京都でも助成があると思うのですけれども、例えば太陽光発電１キロワット当たり自己負担が幾らぐらいでつくことになるのか、伺いたいと思います。","respondent":"中西環境課長","answer":"なかなか個別のところで、例えば太陽光を今後どこまで増やしていくというところまでの目標を持っているわけではございませんが、今現状、今後、パンフレットの中でも、例えば「太陽光発電をつけるとどれぐらいの削減になります」といったような話など。","voiceIndex":227,"id":"exchange-103"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで、ぜひ支援策を周知、知らせていただきたいということと、例えば家を購入する、新築するなどのときに、「ここに行けばこういうのを全部教えてもらえます」というような、相談する仕組みというのをつくっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"中西環境課長","answer":"委員がおっしゃるとおりで、環境に意識がある方以外の方に届くように、どういう取組ができるかといったものに関しては積極的に検討してまいりたいと考えています。","voiceIndex":229,"id":"exchange-104"},{"speaker":"鈴木委員","kind":"質問・要望","question":"保健師の増員について伺いたいと思います。私は、この保健師の増員については、ずっと長い間求め続けてきたのですけれども、なかなか改善されない状況が続いていると思います。新年度の保健師の定数が何人になるのか、それから２３区で人口対比で何番目になるのか、また２３区平均まで何人足りないのか、伺いたいと思います。","respondent":"宮尾人事課長","answer":"離職の状況です。今、手元に詳細な数字を持ち合わせていないのですが、特段、保健師だけが突出して多いなどという状況にはないと認識しています。","voiceIndex":231,"id":"exchange-105"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点では、ずっと取り上げ続けてきているのですけれども、なかなか保健師の体制というのが充実というところに改善されていないと思うのですけれども、その点では、前も言ったのですけれども、保健師の人材確保の計画というのをつくることが必要なのではないかということで、これは厚生労働省のホームページにも出ていまして、自治体保健師の人材確保ガイドというのがありまして。","respondent":"宮尾人事課長","answer":"保健師に限らず、全ての職員、全ての職種において、年度ごとにしっかりと必要性を見極めながら、必要な人材の確保に取り組んでまいりたいと思います。","voiceIndex":233,"id":"exchange-106"},{"speaker":"田中委員","kind":"質問","question":"私は、３０１ページの地域医療連携、また３０９ページ、感染症予防費に、まずは関連してお伺いします。これは他区よりも相当詳しく、しっかりまとめていただいたことを改めて感謝します。つまり、コロナの結果を受けて、やはり区においても、医療、感染症に対する取組は、今まで以上にしっかりと、区でまとめていただいた報告書もしっかり踏まえた上で対応すべきだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-107"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど申し上げましたように、コロナの感染を受けて、ますます医療との連携が必要となっていると認識しております。ここでは地域医療連携会議なども行われて、地元医師会との連携が図られておりますが、これまでの医師会からの要望や対応、あと今後の課題などが新たに分かれば、そういった成果を教えていただきたいと思います。","respondent":"遠藤健康推進部次長","answer":"４月から地域医療連携課が設立されまして、先ほど委員からご指摘のあったコロナ検証の影響で、顔の見える関係が必要だろうというところで、今、医師会を中心にいわゆる定例会というものをしています。","voiceIndex":239,"id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"私は一般質問で少し触れましたけれども、区民の意識もいかにして持続するかということも課題だと思います。まだこの時期ですから、多くの方は、私も含めてマスクをしたり、まだコロナの意識は残っておりますが、これから時間の経過とともに薄れることもまた懸念されます。そういった意味の区民の意識の継続という取組について、お考えがあればお伺いしたいと思います。","respondent":"五十嵐保健予防課長","answer":"何かの感染症がはやった機会に、なるべくお伝えして、また思い出していただきたいと思いながら、ホームページの更新をさせていただいたり、感染症についても啓発させていただいているところですが、やはりなかなか継続していくのは本当に難しいと考えています。","voiceIndex":241,"id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば今、新庁舎の建設が行われようとしております。そういった意味で、商店街を所管する課として、横の連携、様々な区の事業を行う部署に対して、いや、その部分はぜひ商店街の振興にもつながる、影響を受けるようなテーマだから、そこはこうしてほしいなど、オール区庁としての、商店街振興も含めた視点での対応を取っていただくことも、ぜひ課長にお願いしたいと思いますが、そこはいかがでしょうか。","respondent":"小林地域産業振興課長","answer":"新事業の中で、いろいろな影響が出てくると思いますけれども、まず我々としてそういうところのお声をきちんと聞くということと、我々が間に入る形も含めてですけれども、関係部署をきちんとおつなぎして、商店街連合会にとって誤解のないようにというか。","voiceIndex":243,"id":"exchange-110"},{"speaker":"田中委員","kind":"意見","question":"もう時間がないので一方的にしゃべります。デジタル商品券に関しても、これまで既存の商店街の振興という意味で共通商品券の活用がありました。そういった視点も配慮していただいた上で対応をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":245,"id":"exchange-111"},{"speaker":"西村委員","kind":"質問","question":"３１３ページ、省エネルギー対策事業、３１５ページ、環境啓発・推進事業と資源回収・中間処理事業について、脱炭素とごみの減量に向けて伺ってまいりたいと思います。省エネルギー対策事業として私も注目していたのですが、宅配ボックス設置助成が始まり、しばらくたったのですけれども、広がりや経過を伺えればと思います。","respondent":"中西環境課長","answer":"今年度９月より開始いたしました宅配ボックス設置助成です。","voiceIndex":247,"id":"exchange-112"},{"speaker":"西村委員","kind":"質問","question":"実際にこれでどれぐらい成果が出ているのかというのは、なかなか数字を出すのは難しいと思うのですが、私も興味を持っておりますので、認知度や執行率の向上に向けてお願いしたいと思います。品川区は食品ロス削減に向けた連携協定を結びまして、フードシェアリングアプリ「ＴＡＢＥＴＥ」をスタートさせています。こちらもどのような事業か伺えればと思います。","respondent":"中西環境課長","answer":"一般的には、出品されている食品に関しましては、通常より安く購入することができるものですので、フードロスの一助になるものと考えているところです。","voiceIndex":249,"id":"exchange-113"},{"speaker":"西村委員","kind":"意見","question":"閉店間際にレスキュー依頼というのができるのですけれども、この仕組みが大変ユニークだと思っておりまして、店側は廃棄を減らせますし、区民はお得に食事を楽しみながら、フードロス削減に参加できるというのが面白いと考えています。楽しさや便利さをプラスすることで、区民の皆さんが自然と参加したくなる取組をこれからもお願いしたいと思いますが、一言お願いいたします。","respondent":"中西環境課長","answer":"食品ロスに関しましては、私どもとしましても課題であると考えています。今後も、もったいない推進店の皆様に、このアプリへの登録をお願いするとともに、１０月に食品ロス削減月間等もありますので、そういったところも捉えまして、大きく展開してまいりたいと考えています。","voiceIndex":251,"id":"exchange-114"},{"speaker":"西村委員","kind":"質問","question":"もったいない推進店も増えていると伺っておりまして、ぜひお願いしたいと思います。新たな課題であると思うのですが、日本のエネルギー消費量の約３割を占める建築物の分野における取組が急務となっており、伺いたいと思います。区としての考えや来年度の取組について伺えればと思います。","respondent":"中西環境課長","answer":"そういった中で来年度、区といたしましても、新築住宅を建てられる際にＺＥＨ補助、ＺＥＨの認証を取られた場合に関する補助金、それから事業者向けには、工場・事業所をＺＥＢ化する際の設計補助といったものを開始いたしまして。","voiceIndex":253,"id":"exchange-115"},{"speaker":"西村委員","kind":"質問","question":"ごみ減量に向けて伺ってまいりたいと思うのですが、先日お話を伺う機会がありまして、東京湾にある２３区のごみ処理を担う中央防波堤の埋立て処分場が、あと何年でいっぱいになってしまうのかというような話を伺う機会がありました。実績と資源回収の状況、また実際に燃やすごみが減少しているのかどうか伺います。","respondent":"篠田品川区清掃事務所長","answer":"ごみ減量についてのお尋ねです。製品プラスチックの回収は今年度から本格実施、令和５年度にモデル実施をしたという経緯があります。この間、いわゆる製品プラスチックを含むプラスチック製容器包装につきましては、令和２年度から毎年、大体二、三％程度、増加の傾向にあります。","voiceIndex":255,"id":"exchange-116"},{"speaker":"西村委員","kind":"意見","question":"混ぜればごみでありますが、分ければ資源であります。今朝のニュースで、まちからごみ袋が消えたと、茨城県潮来市が話題になっておりました。原材料の高騰などを理由に、資源物専用ごみ袋を値上げした結果、価格が今の３倍近くになったというものでした。生活する上で、ごみは必ず出てきます。各自治体でこういうふうに広がっている、ごみ袋の有料化に関しまして、区はどのようにお考えか、お聞かせください。","respondent":"篠田品川区清掃事務所長","answer":"ごみの有料化に伴いまして、ごみが減量するというのは、一般的には広く認識されているところではあるのですけれども、品川区といたしましては、それは確かに１つの方策かもしれないけれども、まず有料化に入る前にやるべきことがあるだろうと考えております。","voiceIndex":257,"id":"exchange-117"},{"speaker":"西村委員","kind":"提案","question":"危機感の中で動くというよりも、やはり先ほどいろいろご提案させていただいたような、生活の中に組み込みながら、こういった課題に関して積極的に、まさに言っていただいたように一丸となって取り組めればいいなと思うのですが、ごみの発生抑制や、製品設計の段階での対策を、もうしていかなければいけないのだろうと思っておりまして、区でできるだけではなくて、２３区全体で動くことでありますので。","respondent":"篠田品川区清掃事務所長","answer":"毎年、ここのところ、大体年に０.５％から１％ぐらいずつ増えていっていますので、おおむね、このままの推移で進めば、その数字も達成できる可能性は十分あるのではないかと捉えているところです。","voiceIndex":259,"id":"exchange-118"},{"speaker":"若林委員","kind":"質問","question":"３０３ページの５歳児健診、モデル実施ですが、来年度の進め方をいろいろお聞きしたいと思います。スクリーニングを３００人のお子さんにされるということですけれども、このスクリーニングというのはどのようなものでしょうか。その後、６０人程度を対象に健診を受けてもらうということですが、３００人から６０人になる抽出というか、内容はどのようなものでしょうか。","respondent":"石橋品川保健センター所長","answer":"専門医、専門職、それぞれ健診での役割というところになりますが、初めに保健師が問診等、予診を行いまして、その後、医師に診察を行っていただいて、個別相談で心理職等の専門職をお願いしたいと考えております。","voiceIndex":263,"id":"exchange-119"},{"speaker":"若林委員","kind":"質問","question":"これで、保健部門の内部での、いわゆる５歳児健診のシステムが１つ、モデルですけれども、次々年度が本格実施へということで、様々検証しながらということだと思います。この５歳児健診システムを、最終的に保健部門の内部でも、さらに何か活用するということもあるでしょうし、また福祉の部門、また教育の部門といったところには、どのようにこのシステムを活用してもらいたいのか、お考えをお聞きします。","respondent":"石橋品川保健センター所長","answer":"保育部門でしたら、就学までの１年前に実施する関係もありますので、その１年間、保育にどう反映させていくかというところも含めまして検討していきたいと、関係各課で連携を取ってやっているところになります。","voiceIndex":265,"id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"今、３部門で連携を密に取っているというところで、大変心強いお話を伺いました。この３部門の関係性をつくるに当たって、連携体制を構築するために必要なことは、今、密に連携を取っている最中ですというお言葉がありましたけれども、もう少し具体的なところで、この連携体制を構築するためにさらに必要なことは、何を考えていらっしゃるかお聞きします。","respondent":"石橋品川保健センター所長","answer":"ワンストップの窓口というところになります。健診の対象者を６０人という形で、モデル実施のときは選定する形にはなりますが、５歳児健康診査のスクリーニングのアンケートが送られてきて、やはり不安に感じるご家庭はあると思います。","voiceIndex":267,"id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"厚生委員会でもお話もさせていただきましたけれども、次々年度に向けて、またこの１年間、しっかりこの５歳児健診のモデル実施を完成させて、３部門の連携のまさに強化を具体化させていただきたい。教育部門にも福祉部門にも保健部門からしっかりお伝えしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"本日は、ダブっている事業が多いので、もう少し整理できないのでしょうかという観点でお聞きしたいと思いますが、決算特別委員会のときにも質問しました。片や、０歳児見守りのほうは資格は問わないということでは、これはどうなのだろうなという疑問を呈しました。そこで今回、赤ちゃん訪問は３,１８０件ということで、これは実績として９４％を超えているのです。この違いは何ですかということです。","respondent":"石橋品川保健センター所長、中西環境課長、小林地域産業振興課長","answer":"相談に関してですが、保健センターでも相談を専門職がしっかり行っておりますので、もし見守りおむつ定期便を利用できない日にちがという話であっても。こちらの専門部会に関しましては、今後、区としてどういった取組をさらに進めていくかなど。これまでの委員会の審議の中でも、「予算案の議決の後ということですけれども、直ちに地元の既存の事業者に丁寧な説明や意見交換を行い。","voiceIndex":271,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"質問にきちんと答えてほしいと思うのですけれども、すくすく赤ちゃん訪問と、見守りおむつ定期便ですけれども、これはやはりダブっていると思うのです。地域課題のために、品川区は平成２０年からやっているのです。それを、区のほうが、「いや、オーガニックをやりますから、契約なし」といって、それで不満がないところはないし、だから地域産業としてどうなのですかと。そこだけ答弁をお願いします。","respondent":"石橋品川保健センター所長","answer":"本事業は育児用品のみのお渡しということは一切考えておりません。重複というわけではありませんが、今後、すくすく赤ちゃん訪問と見守りおむつ定期便に関しましては、別の事業として実施するべきこととして認識しております。","voiceIndex":275,"id":"exchange-124"},{"speaker":"せお委員","kind":"確認","question":"３０９ページ、各種がん検診、時間がありましたら２９９ページ、保健所管理運営費なのか、３０１ページ、地域医療連携なのか分からないですけれども、ＮＩＣＵから退院して在宅になるというところの支援のところをお聞きします。さらに、令和７年度の予算書にも、前立腺がんや喉頭がんなどの検診の予算も計上されていますので、令和７年度は変わらず実施していく方向でよいのか、確認だけさせてください。","respondent":"若生健康課長","answer":"それから次年度につきましては、すぐに全部の指針外を廃止していくというところはなかなか難しいというところもありますので、前立腺がんや喉頭がんといったところは、今後、段階的に見直していくということで、令和７年度に関しては実施の方向で、今、予算計上しています。","voiceIndex":278,"id":"exchange-125"},{"speaker":"せお委員","kind":"質問・要望","question":"理解いたしました。今は前立腺がんの例だけ出しましたが、時代によって医療も変化しますし、前立腺がんをはじめとしたがん罹患者数などの推移・変化を区で引き続き見守っていただいて、国や東京都の動向もしっかり注視していただきたいと要望いたします。さらに、こちらも要望なのですけれども、先ほどの前立腺がんや喉頭がんをなくしていく方向ということのお話でした。","respondent":"若生健康課長","answer":"精神面でのケアについても相談できるような、がん相談支援センターが、区内に２か所ありますし、マギーズ東京との連携なども図りながら、そういった支援機関につなげる取組をさらに推進してまいります。","voiceIndex":280,"id":"exchange-126"},{"speaker":"せお委員","kind":"質問・要望","question":"１点だけ。先ほどお伝えしましたが、今年度から医療的ケア児は、切れ目のない支援というところでやっていらっしゃると思うのですけれども、医療的ケア児だけでなく、生まれてすぐ障害が分かったというところの、病院から地域への連携というか、在宅への連携のところ、今どのように取り組んでいるかだけ教えてください。","respondent":"福地大井保健センター所長","answer":"保健センターでは、病院から未熟児や医療的ケア児のお子さんについて、地区の担当の保健師に連絡が来ます。そうしましたら、地区の担当の保健師が、ご家族や医療機関に状況を聞きに行ってケアします。","voiceIndex":282,"id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"３２１ページのスタートアップ推進事業について伺います。その前に、産業経済費全体について伺います。産業経済費が数年間、全体の予算からの比率が変わりません。どれぐらいの割合で推移しているか、お尋ねします。","respondent":"小林地域産業振興課長","answer":"例年というか、ここ５年ぐらい、コロナの関係もございましたので、若干増えている、あるいは減っているという変動はありますけれども、平均してですけれども２％前後というのが１つの目安だと考えておりまして、この数字というのが、ほかの区で見ても。","voiceIndex":285,"id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうですね。１.９％、２.１％、２.１％。ところが、令和７年度は当初で１.６％です。それでマイナス１０.６％で、４億円マイナスです。そういった全体の割合の中で、今少しお話しいただきましたが、産業経済費の割合をどう捉えて、どのようにしていくつもりでしょうか。その第２の円が品川区なのですが、もっと力を入れてもよいのでしょうか。いや、入れるべきではないかということで、お伺いします。","respondent":"小林地域産業振興課長","answer":"産業経済費をどう捉えるかという視点ですけれども、直近の推移で見ますと、３つ視点があると考えています。","voiceIndex":287,"id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"３つの視点をお話しいただいたということですが、まだまだパーセンテージを上げる、様々、今言われた３つの視点で事業を増やしていけるのではないかと思っています。令和６年度は、新たにスタートアップ・エコシステム推進事業などを実施しているところです。お尋ねします。それから、これらのスタートアップ支援は、区内産業全体の振興にどのようなメリットをもたらすのでしょうか。お願いします。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"スタートアップの定義につきましては、一般的には、新しい技術で数年以内に急成長してＩＰＯなどを目指す企業と捉えているところです。一方、例えば、まちのラーメン屋や塾といったところは、着実に持続可能な成長を目指す企業と認識しています。","voiceIndex":289,"id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"意気込みを伺ったのですが、それはいいです。そういうご答弁なのですが、令和７年度の予算編成過程の公表を見てみると、要求額が１億８,０００万円です。予算額は４,５００万円です。１億３,４００万円が切られています。令和６年度の予算から見ても、７００万円減っています。意気込みがあって、こんなにすばらしい事業性がある事業なのに、なぜ予算の査定で削減したのか、お伺いします。","respondent":"加島財政課長","answer":"産業経済費に関する査定の理由・過程というところですけれども、査定の詳細につきましては明かすことができませんけれども、編成過程の公表をさせていただいている中で、主な増減理由のところに理由を記載させていただいているところになります。","voiceIndex":293,"id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、所管課はそれで納得しているのでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"区の予算編成につきましては、区政全体のバランスを見ての結果と捉えておりますので、結果として編成された内容の中で、来年度、少しでも成果を上げていく努力をしてまいりたいと考えているところです。","voiceIndex":295,"id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"所管課の意気込みややる気、そして、それを活かす予算編成査定が求められますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-133"},{"speaker":"松本委員","kind":"質問","question":"３０５ページ、食品衛生、３２５ページ、展示会出展支援について伺います。食品衛生なのですけれども、区民の方からご意見を頂いたので、それに基づいて少し伺っていきたいと思います。それで、臨時営業については、食品衛生法施行条例第３条に根拠があるのですが、私はなかなか見つけられなくて、臨時出店の届出の法律上または条例上の根拠は何なのか伺います。","respondent":"赤木生活衛生課長","answer":"ただいま頂きました、行事等における臨時出店における法的な根拠というところのご質問ですけれども、根拠としましては、先ほど委員におっしゃっていただきました、「品川区行事における臨時営業等の取扱要綱」において規定されているものと認識しています。","voiceIndex":299,"id":"exchange-134"},{"speaker":"松本委員","kind":"質問","question":"かつ届出なので、許可ではない。一般的には、区が後援や協賛するような行事、あるいは町会・自治会、商店会が主催するような行事というのはすごくよく分かりやすいのですけれども、一応この要綱を見ると、任意のグループや、あるいは場合によっては個人が企画するイベントであっても、公共的目的を有する行事と判断される場合があるというふうに読めるのですが、その理解でよろしいでしょうか。","respondent":"赤木生活衛生課長","answer":"臨時出店における個人の方や、町会・自治会等以外の方がやられたところの部分についての公共性の判断に関するご質問にお答えします。","voiceIndex":301,"id":"exchange-135"},{"speaker":"松本委員","kind":"質問","question":"おっしゃるとおりの考慮要素が書かれているかと思うのですけれども、地域の実情というのは、具体的にはどういう内容といいますか、どういうことを考慮されるのでしょうか。分かる範囲でお願いします。","respondent":"赤木生活衛生課長","answer":"地域の実情という部分をどのような形で判断するのかというご質問についてお答えします。","voiceIndex":303,"id":"exchange-136"},{"speaker":"松本委員","kind":"確認","question":"続きまして、展示会の出展の支援なのですけれども、今年度の最終補正では６００万円の減額補正で、当初予算から３割減と、比較的大きな減額でした。一方、事務事業評価シートを拝見すると、展示会の出展費助成交付企業数の目標は、令和５年度の７６件から、令和６年度は６０件と下がっているのです。その辺りはどういうご事情なのでしょうか。","respondent":"小林地域産業振興課長","answer":"目標の件数にやや足りなくてという部分はありますけれども、我々はこういう取組を、助成制度の説明会などを通じて、「こういう中で売上げを伸ばした企業もたくさんありますので、こういうものを使ってください」というところで、来年度の予算の中でまたしっかり。","voiceIndex":305,"id":"exchange-137"},{"speaker":"松本委員","kind":"質問","question":"この展示会の出展ですが、東京都でも類似の政策があるかと思うのですが、こことの違いはどこにあるのでしょうか。","respondent":"小林地域産業振興課長","answer":"その分、区のほうが、金額は小さいですけれども小回りが利くといいますか、支援のスピードというのは速いのかなということで、こういう部分で、都の強みというのもありますし、区の強みというものもありますので、両方見せていきながら。","voiceIndex":307,"id":"exchange-138"},{"speaker":"松本委員","kind":"質問","question":"おっしゃるとおりで、本当に都のほうは少し縛りが大きいのかと考えていますので、大事だと思っています。ただ一方で、１点、見ていて思ったのが、これは申請の期間が、１０月１日から１０月３１日までの１か月間だけなのです。ここは、ほかの自治体を見ていると、通年でやっているところもありますので、そこは改善をお願いしたいのですが、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"申請期間をどう設定するかというところではありますけれども、我々は年間を通して応援していくというところは変わりませんので、今後もいろいろ考えていきたいと考えています。","voiceIndex":309,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"私は、３２３ページ、中小企業活性化事業費についてお聞きいたします。１年以内に倒産する確率の高い企業は、品川区内や東京都内では何社ぐらいあるのでしょうか。これは分かるのでしょうか。教えてください。そして現在、中小・零細企業や個人事業主は、経営内容や資金繰りは厳しい状況が続いているため、存続が難しくなり、廃業や倒産の危機を迎えているということですが、その理由を教えてください。","respondent":"小林地域産業振興課長","answer":"ただし、その件数としましては、リーマンショックが起こっていたような２００９年、２００８年頃に比べると半分以下というような形ではありますので、そういった倒産の動向といいますか、推移というのは、我々も引き続きしっかり見ていきたいと考えています。","voiceIndex":312,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、物価高騰というお話が出ました。転嫁するわけですから、また物価が上がる。もう何もすることは、恐らくほとんどの会社、企業は持っていないと私は思うのですが、それだったら、こういう状況なら、区から国や都へ緊急支援を要請するべきだと私は思うのですが、どうなのでしょうか。その辺について教えてください。そういう実情の中で、今の支援ということをどのようにお考えでしょうか。教えてください。","respondent":"小林地域産業振興課長","answer":"国と都の関係というところでいきますと、実際、国がやる施策、あるいは都がやる施策というのはありますけれども、その中で、今回の補正予算などもそうですけれども、国から財源が下りてくる中で、やはり事業者にとって身近な存在である区が、きちんと小回りの利くという。","voiceIndex":314,"id":"exchange-141"},{"speaker":"須貝委員","kind":"意見","question":"品川区の、今回、令和７年の区長の施政方針ですが、２０２２年の全世帯当たりの平均所得金額は５２４万円。そして、なぜ安心できる社会をつくれないかというと、東日本大震災は１４年たっても、いまだに２万７,０００人の避難民がいる。そういうことを品川区でやるべきだと私は思います。もう待っているのではなくて、こちらから進んでいってほしいと私は思います。ご見解をお聞かせください。","respondent":"小林地域産業振興課長","answer":"こういう中で、事業者の方の不安というのもありますし、そういう中の「不」を取り除く形で、新しいチャンスが少しでも見えていくような方向性を、区として、国や都の財源なども使いながらですけれども、施策の協力も得ながら、しっかりやっていくということが、区の取組ですし。","voiceIndex":316,"id":"exchange-142"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"だから、国民健康保険の基本健診で見ると、健診の受診率が低くて、医療費はがん等が増えて２３区で２位ということで、やはり、がん検診というのが大事になってくるというのが、これを見ても分かるのですけれども、早期発見・早期治療につながるものに、がん検診がなっているのかということなのですが、品川区の保健衛生と社会保険というものを見て、実績等を見ても。","respondent":"若生健康課長","answer":"直近で申し上げますと、東京都に報告しています、東京都の集計しているところでのがん検診の受診率につきまして、５つのがんで申し上げますと、胃がん検診については、令和５年度ベースですけれども１１.１％、肺がん検診については９.１％、大腸がんは２０％。","voiceIndex":319,"id":"exchange-143"},{"speaker":"石田（ち）委員","kind":"質問","question":"この受診率というのは、高いのか、上がっているのか。要は、先ほどもおっしゃっていましたけれども、死亡を減らすために、がん対策推進計画というのも立てていると思うのですけれども、この検診率というのを区はどう見ているのか伺います。","respondent":"若生健康課長","answer":"受診率につきましては、がん種別によりますけれども、胃がん、肺がん、乳がん、子宮がんについては年々上昇しているところでございまして、大腸がんについては横ばいというところで、課題と感じております。","voiceIndex":321,"id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"質問","question":"例えば、先ほど言った品川区の保健衛生と社会保険というものを見ますと、胃がんの内視鏡検診は２,０００円の自己負担がかかります。対象者は４万２,２２３人。そのうち健診を受診された方は、令和５年で４,１６５人。なので、精密検査につながり、早期発見されることは大変大事なことだと思いますし、さらに無料にすることで早期発見につながると思いますけれども、いかがでしょうか。","respondent":"若生健康課長","answer":"国の指針外のがん検診というのを見直していく。こちらの計画に位置づけておりますので、そちらをしっかり進めていくとともに、無償化についても、がん検診の全体の在り方を検討する中で、今後考えてまいりたいと考えています。","voiceIndex":323,"id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問","question":"無料化することは一定効果があると。そして５番目の「費用がかかる」というところは、さらに区が助成していけば、これは解決していけることだと思うのです。なので昨年も、４,０００万円程度の負担で無料化できると、区もお答えいただいているのです。ですので、区が行った調査を見ても、啓発と無料化で改善できると思うのですけれども、いかがでしょうか。","respondent":"若生健康課長","answer":"いわゆる５人に１人ぐらいの方が、そういった認識をしているというところで、これについては、必要性を感じていただくような努力を、区としても進めていかなければいけないということで、こちらをやはり重く受け止めているところです。","voiceIndex":325,"id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問","question":"それが、４０歳以降が多いのです。安心して早期発見・早期治療につながるように、検診があるべきだと思うのです。それをどう捉えるかとおっしゃるのですけれども、「費用がかかるから行かなかったのです」という、もうストレートだと思うのです。なので、そこを改善させていく。無料がどうか、議論があるとおっしゃっていましたけれども、改善させていくという考え、検討はあったのでしょうか。伺います。","respondent":"若生健康課長","answer":"その中では、例えば国の指針外のがん検診をなくすことで、その財源を無償化のために充てていくというのはどうかというようなご意見もございました。そういった議論も踏まえまして、まずはがん検診の見直し。これは、全体として、無償化も含めまして、総合的に検討してまいります。","voiceIndex":327,"id":"exchange-147"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういう使い方ができてしまうのかどうかというところを教えていただきたいのと、本人確認ができるようになったので、今回ついた予算を全て区民が使えるということで、前回、キャッシュレス決済ポイント事業のときには、区民以外の方もたしか使えて、区民に納得できるような予算として今回出てきて非常に安心しておりますというところで。","respondent":"栗原創業・スタートアップ支援担当課長、篠田品川区清掃事務所長、中西環境課長","answer":"１点目、デジタル商品券の店舗での運用についてなのですけれども、細かいことはこれから詰めていくところですけれども、例えば他区の事例ですと。それで、実際に何が変わってきたかというと、先ほど少しお話しいただきましたけれども、粗大ごみのいわゆるシステム化によって。","voiceIndex":330,"id":"exchange-148"},{"speaker":"大倉委員","kind":"質問・要望","question":"今気になったのは、免許証、マイナンバーを持っていない人はどうやっていくのだろうというのが若干気になったので、そういったところの対応があれば教えていただきたいのと、これは、デジタル化することで、こうした様々なデータが取れるというところで、どこでどのような店舗で使われたとか、どのように買われたとか、利用状況などというのが分かってくると思うのですが。","respondent":"栗原創業・スタートアップ支援担当課長、篠田品川区清掃事務所長","answer":"その後、６月中旬ぐらいに専用のホームページを立ち上げる予定ですので、そこから利用する店舗の方や区民の方への周知を図ってまいりまして、８月から申込みを開始して、秋からの運用開始というような。なかなか申請いただいたものを確認するためには、申請番号など確実なところで、今、紙にご記入いただいて貼っているというのがあるのですけれども、確かに委員のおっしゃるとおり、現実に、逆に言うと写真で申請していただいたほうが。","voiceIndex":334,"id":"exchange-149"},{"speaker":"藤原委員","kind":"確認","question":"デジタル商品券、私も期待しているのですけれども、１点確認します。今年度中に業者というか、プロポーザルを受けてとおっしゃっていました。今年度中というのは、もうあと２週間ぐらいしかないのですけれども、この短い期間の中でできるのでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今後は、あと二、三週間というところなのですけれども、こちらはちょっと頑張りまして、１次審査、２次審査、それから面接審査と、プロポーザルの区内の基準に基づきまして、きっちり公平・公正に実施していくところです。","voiceIndex":339,"id":"exchange-150"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３０３ページ、産後ケア事業、訪問型と宿泊型の拡充について伺ってまいります。昨年の決算特別委員会で、ご相談を基に、産後ケア事業、特に宿泊型について、具体的な課題をお示ししながら拡充を求めておりましたので、抜本的にどのように拡充されたのか確認してまいりたいと思います。１点目は、宿泊日数と分割利用について伺います。","respondent":"石橋品川保健センター所長","answer":"自己負担額も軽減させていただきまして、宿泊施設の利用料の１割負担という形で軽減しています。","voiceIndex":343,"id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問","question":"宿泊料についても１割負担と。昨年は、港区のある有名な医療機関が人気で、そこは１泊６万円余というところでしたけれども、そこについてある程度伺いたいのですけれども、今回、品川区は、宿泊型は７つの医療機関に委託していますが、一番低い自己負担額、一番高額な自己負担額、そして契約している医療機関の平均の自己負担額を教えてください。","respondent":"石橋品川保健センター所長","answer":"自己負担額になりますが、１泊２日で一番安価な料金で３,８００円、一番高額といいますか、一番利用料が高いというところで７,０００円という形になります。大体、平均値が５,０００円前後というところで認識しているところになります。","voiceIndex":345,"id":"exchange-152"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。はご自身の選択ということで、確認させていただきました。宿泊型の手続の簡便化についても伺いました。しかし、昨年の決算特別委員会で確認しましたところ、電子申請をしてから、医療機関への予約に必要な利用通知書の発行までに１週間から２週間ほどかかるという課題があるということでした。","respondent":"石橋品川保健センター所長","answer":"本年度、宿泊型につきましては、電子申請に変えたところがありましたが、電子申請から承認証の発行まで、一週間、二週間程度の時間を頂いていましたので、すぐに申込み利用の予約ができないということがありまして、そこを課題として捉えておりました。","voiceIndex":347,"id":"exchange-153"},{"speaker":"あくつ委員","kind":"確認","question":"今回、宿泊日数が一気に倍になったということ、そして自己負担額も１割ということで、選択するところによっては非常に低額になる。そして、手続についても劇的に簡便化されたということを確認しました。次に訪問型産後ケアについて、区民のご意見を基に伺ってまいります。品川区は訪問型産後ケア事業を、今まで五反田の東京医療保健大学に委託しておりましたが、今回の変更点を教えてください。","respondent":"石橋品川保健センター所長","answer":"そこで、どうしても利用したい日にちに利用できないという声も上がってきたという現状があります。そこで、次年度より事業者を１事業者、追加することを決定して、手続を今進めしています。","voiceIndex":349,"id":"exchange-154"},{"speaker":"あくつ委員","kind":"提案","question":"個別に委託されているということです。もう、すぐ受けたい、乳房ケアを受けたいとなった場合に、４時間前にホームページは締め切られる。これは、やはり他区のように、利用者に複数の選択肢をご用意していただきたいというのが今回のご提案です。その辺り、まだ始まっていない事業ですから、時間はかかるかもしれませんけれども、ぜひこれからご検討いただきたいと思うのですが、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"次年度１事業者を増やすというところで、合わせて２事業者の連携をしっかり図りつつ、どのように進めていくかということもしっかりと検討してまいりたいと考えております。","voiceIndex":351,"id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問","question":"３０１ページ、災害医療関係費から質問をしてまいります。先ほど田中委員の質問にもありましたが、地域医療連携課が新設されました。大まかに言うと、次の２点です。１点目のＯＩＭＡＣＨＩ ＴＲＡＣＫＳと品川区との帰宅困難者受入れスペースとの連携。これは防災課マターだと思うのですけれども、２点目に関連するので、どの程度分かっているのか、進んでいるのか、教えてくださいというのが１点目です。","respondent":"遠藤健康推進部次長、羽鳥防災体制整備担当課長","answer":"というところで、この辺ですと東京品川病院に、区では緊急医療救護所を設置する形になりますので、そちらが中心になるのかなと考えているところです。委員がおっしゃられたとおり、３,０００名の帰宅困難者を受け入れる一時滞在施設としてご協力いただくように話を進めております。具体的には、来年度の夏頃から協定締結に向けた話をするという予定です。","voiceIndex":353,"id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"はＤＭＡＴという、厚生労働省が編成している緊急医療災害対策チームにも加入している医師の方がたくさんいらっしゃるということで、防衛省の医官ですから、そういった訓練を常日頃していたということで、ぜひそういった意味も含めて、先ほど申し上げましたけれども、地域防災計画が基本なのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":356,"id":"exchange-157"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、３２３ページ、中小企業活性化事業費、そして同じく品川産業支援交流施設経費、および品川ビジネスクラブ助成金に関連して、中小企業やスタートアップ事業、随分質問が出ましたけれども、支援についてお聞きします。新型コロナ、原材料の高騰など、この５年間、中小企業にとっては大変な状況が続きまして、その中で各企業の事業継続をどう図っていくのかが大きな課題です。そこでお伺いいたします。","respondent":"小林地域産業振興課長","answer":"こういうものを通じて、稼ぐ力といいますか、攻めの力というところを引き続き伸ばしていく予算というものに、令和７年度の中でしっかり取り組んでまいりたいと考えているところです。","voiceIndex":358,"id":"exchange-158"},{"speaker":"まつざわ委員","kind":"質問","question":"融資やチャレンジ、それと商談会のマッチングですか。商談会のマッチングというのは、ＳＨＩＰですね。ＳＨＩＰというのは補正予算でも大きくプラスの補正がしてあったと思います。ＳＨＩＰというのをお調べしましたら、今年で１０年目を迎えますが、改めてＳＨＩＰや品川ビジネスクラブによるスタートアップ支援の取組や成果についてお聞かせください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"４階のコワーキングスペースでは、現在、約２００名程度の会員がいらっしゃいまして、年間大体４０回ぐらいのセミナー、それから二百五、六十件の個別相談、それから２回の大規模交流会などを実施しています。","voiceIndex":360,"id":"exchange-159"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、ＳＨＩＰというのは、スタートアップや起業家だけではなくて、要は中小企業、個人事業主というところまで幅広くビジネスを展開されているということですね。これで、スタートアップ・エコシステム推進事業の中身を聞こうと思いましたが、今、高橋しんじ委員の質問がありまして、３つの大きな目的・意義があります。この事業にどういうふうに関わっていくのか、お聞かせください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ビジネスクラブは、そこを運営する指定管理者として、区と一緒に事業の周知や運営を協力してやっていくという存在と考えておるところです。今年度もエコシステムの事業を、ＳＨＩＰを含め、全８回実施しまして、１３１回の商談や３件の具体的な成果を創出しています。","voiceIndex":362,"id":"exchange-160"},{"speaker":"まつざわ委員","kind":"意見","question":"そういった幅広い企業と団体が集まる中で、ＳＨＩＰの中から、やはり大きく羽ばたいて、起業家、そして若者をどれだけ育てていけるか。その中から生まれた画期的なビジネスアイデアというものが、１人の起業家の成長や発展にとどまらず、地域や社会を変える起爆剤になり得ると期待しています。こうした中から、ＳＨＩＰや品川ビジネスクラブというのはどのような支援を行っているのか、お聞かせください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"一般枠といって、年齢を制限しない枠においては、小学生、中学生、高校生、大学生、それから大人と、幅広い世代からレベルの高いビジネスプランがありました。そういったところを、今後は区や、いろいろなところに、事業化につなげていけるような支援をやっていくところです。","voiceIndex":364,"id":"exchange-161"},{"speaker":"まつざわ委員","kind":"質問","question":"引き続き積極的な取組を期待しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":366,"id":"exchange-162"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7009#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":129499,"voices":367}},{"id":"r07-20250313-3","meetingId":"r07-c-budget","date":"2025年3月13日","dateIso":"2025-03-13","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時２１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"おはようあります。ただ一方で、交通サービス圏域外とされた残りの２地区、こちらのうち荏原地区においては、私の一般質問でも伺い確認しましたが、令和７年度にＡＩオンデマンド交通の実証運行が行われる予定となっていることから、一定の取り組みが進んでいると認識しております。そこでお伺いします。区は、大崎地区の交通課題について、どのように取り組んでいこうと考えているのでしょうか。","respondent":"櫻木地域交通政策課長","answer":"しかしながら、依然として大崎地区の交通課題の解決は区としても重要なこととは考えており、今後はコミュニティバスにこだわることなく、ＡＩオンデマンド交通や、新たな交通サービスなど、どのような交通が大崎地区にふさわしいかという観点を見定めつつ。","voiceIndex":4,"id":"exchange-001"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認がとれました。次に、災害時応急物資確保費についてお伺いします。先日、会派での要望で実現した２３区初となるトイレトラック、３月３日、品川区は、助けあいジャパンが企画する災害派遣トイレネットワークプロジェクト「みんな元気になるトイレ」に参画し、災害が起こった地域にトイレトラックを派遣する協力締結式が行われました。そこでお伺いします。区のご見解をお伺いします。","respondent":"羽鳥防災体制整備担当課長","answer":"今後、地域のイベントにトイレトラックを活用いただく際は、清掃や汲み取り、そういった費用をなるべく区民の負担にならないように、今後、検討してまいります。","voiceIndex":6,"id":"exchange-002"},{"speaker":"えのした委員","kind":"提案","question":"啓発品が予算化されていることの確認がとれました。当日のペーパークラフトについては職員のアイデアだと伺いました。そこで、私からは、塗り絵をご提案します。こちらを要望させていただき、清掃費や汲み取り費については進めていただければと思います。今回、名称が「資機材整備」から「活動支援」に変更しておりますが、どのような背景があるのでしょうか、お知らせください。","respondent":"平原防災課長","answer":"防災資機材整備助成金は、平成２９年から８年間行われてまいりました。この間、東京都におきましても、町会の防災活動に必要な資機材の支援が行われておりまして、一定程度の物資の面での充実が図られているところだと思います。","voiceIndex":8,"id":"exchange-003"},{"speaker":"新妻委員","kind":"質問","question":"おはようあります。３５５ページ、立会川・勝島地区まちづくり、同じく、新浜川公園基本設計委託、３５７ページ、公衆便所費から八潮多目的広場についてお伺いいたします。勝島人道橋の設置完了時期、花海道の整備完了時期、立会川雨水放流管建設関連整備事業の終了時期と今後の動向や跡地の所有について、また、浜川ポンプ場解体工事完了時期と、同じく今後の動向や跡地の所有についてお伺いいたします。","respondent":"森道路課長、大友公園課長、北原河川下水道課長","answer":"現時点では、令和１０年１月、令和９年度の後半に設置を完了したいというふうに考えております。しながわ花海道につきましては、令和６年度から設計に着手しているところでございまして、こちらにつきましても、新浜川公園と同様。本事業については、下水道局で実施している事業であるため、確認をとったところ、立会川雨水放流管事業につきましては令和９年の中頃。","voiceIndex":12,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"新浜川公園の基本設計がやっとここで入ってまいりました。２０１６年の決算特別委員会から重ねて、ここの公園の中に設置されている公衆便所の移設について要望してきましたが、この周辺の整備に合わせて、ここも検討していくということでご答弁をいただいておりますので、今回のこの公園の整備に当たって、設置されている公衆便所が適地に移設されるのかということをお伺いしたいと思います。","respondent":"北原河川下水道課長、大友公園課長","answer":"勝島運河にある民間の非動力船用の小型桟橋についてですが、令和７年度予算では、老朽化の状況も踏まえまして、勝島運河で地域が水辺に親しむイベント等を継続できる環境を整えるという目的で。このトイレについては、昭和６３年に改築されたトイレであり老朽化が進んでいることから、来年度実施する設計におきまして、公園全体の中で、設置する位置も含めまして、地域の声を踏まえて検討してまいりたいと考えているところです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"新妻委員","kind":"確認","question":"前向きなご答弁をありがとうございました。地域の方が待ち望んでおられますので、反映された設計をお願いいたします。先ほど、勝島運河周辺で行われているそれぞれの工事の状況を確認いたしましたが、３月５日の歳入の款別質疑で、この周辺にありますなぎさ会館が廃止に向けての検討がされるということが公表されました。所管が違うのですが、よろしくお願いします。","respondent":"高梨都市計画課長、吉岡政策推進担当課長","answer":"今、委員からご案内のありました立会川・勝島地区まちづくりビジョンにおきましては、まちづくりの方針として、勝島運河を中心とした地区を回遊したくなるまちづくりの推進を掲げておりまして。今、委員からもお話しありましたとおり、なぎさ会館の廃止を検討することとして今後進めていくところですが、同時に、跡地活用の検討も、何ができるかというところを含めていくですけれども、検討に当たりましては、行政需要。","voiceIndex":19,"id":"exchange-006"},{"speaker":"新妻委員","kind":"確認","question":"続きまして、公衆便所費から、八潮多目的広場の公衆便所についてお伺いいたします。当初、故意に壊されたというお話もありましたけれども、天井に水がたまって劣化から起きたことと確認させていただきました。災害時には、この広場に人が集まることも想定があるかと思いますので、災害時も活用ができるようなトイレの整備が必要かと考えますが、区のお考えをお伺いいたします。","respondent":"大友公園課長","answer":"このような公園の改修時期を機に、利用状況などを踏まえて、改めて検討してまいりたいと考えているところです。","voiceIndex":22,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"具体的なご答弁をいただきまして、ありがとうございました。計画を立てて改善されるように取り組みをお願いして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問","question":"本日もよろしくお願いいたします。私からは、３３５ページ、しなみちレポート、３５３ページ、子どもたちのアイデアを活かした公園づくり、３６９ページ、避難行動要支援者経費について、順不同でお伺いいたします。最初に、避難行動要支援者経費についてです。今回は、次のステップとして作成した計画が実用性のあるものにする必要があるといった視点で質問をします。","respondent":"平原防災課長","answer":"具体的な項目につきましては、個別避難計画の作成がまだ進行中ですので、その状況と合わせながら検討をさらに深めてまいりたいと考えています。","voiceIndex":26,"id":"exchange-009"},{"speaker":"ひがし委員","kind":"意見","question":"町会の方々に聞いていくと、個別避難計画の作成が進んでいるとは聞いているけれども、なかなかフィードバックというか、情報が回ってこなくて、どういうふうな進捗になっているのだろうというようなことを聞いております。町会・自治会だけでは、なかなか不十分なのかなというところ、また、福祉的な対応が難しいといったようなお声が聞かれておりますが、その点について、区の進捗もお聞かせください。","respondent":"平原防災課長","answer":"町会等の支援に当たる方について、ご説明ですけれども、各町会長会議に毎年出席させていただきまして、今年度の状況をお知らせするとともに、こちらの考え方をお示ししていますが、個別避難計画との統合につきましては、システム上の関連もありますので。","voiceIndex":28,"id":"exchange-010","title":"町会・自治会支援"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回、区議会として、ユニバーサルマナーの研修に参加させていただいたときも、車椅子の階段のおろし方だったりとか、介助の仕方はこうだよという視点もすごく取り入れられていて、防災にもこのような観点を取り入れて進めていくことで支援者を増やすことができるのかなというふうに思いますが、その点についての区の見解をお聞かせください。","respondent":"平原防災課長","answer":"福祉的なところにつきましては、現在、国会で審議がこれから始まります災害対策基本法の一部改正法案におきましても、福祉的な視点が新たなところで入ってきてありますので、区でもしっかりとそのような動きを踏まえまして。","voiceIndex":30,"id":"exchange-011"},{"speaker":"ひがし委員","kind":"提案","question":"次に移ります。３５３ページの子どもたちのアイデアを活かした公園づくりについてです。子どもたちのアイデアを活用した公園づくりについて、私は子どもたちの声をしっかりと聞いてくださいというふうに提案しておりましたので、このようなことが進んでいることはとてもうれしく思っております。品川区内に子どもたちのアイデアを活かした公園が幾つあるのかということをお聞かせください。","respondent":"大友公園課長","answer":"子どもたちのアイデアを活かした公園づくりといたしましては、平成２０年度よりこの取り組みが始まった以降で申しますと、平成２２年度の鮫洲運動公園から令和６年度の西五反田公園まで９公園で実施をしております。","voiceIndex":32,"id":"exchange-012"},{"speaker":"ひがし委員","kind":"確認","question":"今、９公園進んでいるということで確認いたしました。今回の予算書を見てみると、子供の森公園改修工事が予算として計上されております。この子供の森公園の改修に当たって、子どもの声をどのように反映していくのか、また、どうやって声を聞いていくのかという点についてもお聞かせください。","respondent":"大友公園課長","answer":"子供の森公園の改修におきます子どものご意見、アイデア等々の反映の仕方についてなのですけれども、実施した中でお話ししますと、品川学園は道路を挟んで反対側にある学校です、そちらの小学３年生を対象にワークショップを実施し。","voiceIndex":34,"id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひこのような声を反映させた公園を広げていただきたいなというふうに思っているのですが、まず、効果検証として、この子どもたちのアイデアを活かした公園づくりを行った前と後、例えばたくさん人が来るようになったねとか、子どもがたくさんいるねとか、そういう効果検証はどのようにされているのかという点を最後にお聞かせください。","respondent":"大友公園課長","answer":"子どもたちのアイデアを活かした公園づくりの効果ですけれども、大人では考えつかないアイデアを活かした改修ができているというところで考えてあります。","voiceIndex":36,"id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"子どもたちのアイデアを活かしたことで、大人だと発想がない部分で取り入れることができたということで確認いたしました。もしそういうものをつくる場合には、ぜひ障害があるお子様たちの声も取り入れていただきたいなというふうに思いますが、その点についてお聞かせください。","respondent":"大友公園課長","answer":"整備する際にいただいたアイデア等々に加えまして、現在も進めているところでいきますと、東大井の公園についてもインクルーシブの視点での整備というところで進めているところです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"今、進めているところについては、障害がある方とか、お子様とか、ご家族の声を取り入れたようなインクルーシブ公園になるということで認識は合っていますでしょうか。","respondent":"大友公園課長","answer":"そのとおりです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちら、事務事業評価を確認させていただきました。前回の２０.２％から下がってはいるのですけれども、令和５年度の区民要望件数が、そもそも前回の９６６件から１,２９５件と上がっているので、割合的には下がってしまったけれども、件数は増えているのかなというふうに思っております。この令和５年度に区民要望の件数が増えた理由を、区としてどのように分析をしていますでしょうか。","respondent":"森道路課長","answer":"今、委員のご指摘のとおり、２００件ほど増えてきておりますけれども、その分、令和４年度からしまして、しなみちレポートによる陳情件数は１９６件から２５２件というふうに増えておりまして、着実に広がっているというふうに考えております。","voiceIndex":42,"id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ進めていただきたいなというふうに思いますし、電話で受けるよりも、やはりアプリに登録してもらって、実際の場所が分かったりとか、進捗が分かるというのは、職員にとっても区民の方々にとってもメリットがあるのかなというふうに思っておりますが、こちらを導入してからのお声だったりとか、職員の方々の負担はどうなっているのかというところも伺います。","respondent":"森道路課長","answer":"それが写真１つ、それからＧＩＳにより地図上で分かるということが、非常にスムーズな連絡、情報把握にもなっているかなというふうに思っております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"区民要望についても、パーセントは上がっていますけれども、やはり１,０００件以上は電話でのご相談が来ているということなので、ぜひこのしなみちレポートはいい事業だと思っているので、これを進めていくために、例えば、町会の方々、いろいろと町のことを知っていて、「ここ、困っているよね」というところでなかなか声が届けられていないと聞いておりますので、町会の方々へも。","respondent":"森道路課長","answer":"様々周知についてご提案をいただきました。それぞれの所管と話をしながら、どういった周知方法が適切かということをしっかり検討していきたいというふうに考えております。","voiceIndex":46,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"３４８ページ、都市開発費、武蔵小山駅周辺地区再開発事業、３４９ページ、五反田駅周辺地区コーディネート業務委託で伺います。伺いますけれども、この経費で五反田駅の東口周辺の検討を始めたのはいつからか、何年度からなのか伺います。これ、何の方針を定めることを目指しているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"五反田駅周辺地区コーディネートの中で東口の検討時期ですが、令和元年から進めているところです。","voiceIndex":50,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"事実を確認させていただきたいのですが、小山三丁目第１地区、第２地区、それぞれについて伺いたいのですけれども、今時点で本組合設立認可申請は出されたのか伺います。認可申請には少なくとも権利者の３分の２の同意書が必要ですけれども、どれぐらいの同意がとれていると区は聞いているのか伺います。併せて、現在予定されている事業費と、補助金額を、両地区それぞれ伺いたいと思います。","respondent":"中道都市開発課長","answer":"小山三丁目第１地区の総事業費は９６３億円、三丁目第２地区の総事業費は１,０７６億円を予定しているというふうに聞いております。想定の金額となります。","voiceIndex":52,"id":"exchange-021"},{"speaker":"安藤委員","kind":"確認","question":"認可申請も出されていないということも確認がとれました。パルム駅前地区は、住宅が６２８戸、補助金は１０９億円でした。伺いたいのですけれども、既存の２地区と比べ、なぜこれだけ補助金が上がっているのか伺います。それと、これは事業費が上がっているということだと思うのですけれども、事業費が上がれば、税金投入も増えるということになるのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"現在聞いている中では、３－１、３－２地区ともパルム商店街の通りにつきましては、１階の部分を回遊していますけれども、２階の部分にもデッキを造って回遊できるような形を検討しているなど、様々にぎわいの創出をしていきたいというふうに聞いておりますので。","voiceIndex":54,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"ある第１地区の分譲マンションで一人暮らしている高齢女性が、今回の定例会に、「私はどうしていいかわかりません品川区長森澤恭子さんに小山三丁目第一地区・第二地区再開発中止を求める陳情」を出されました。ここで再開発をやろうとしているわけで、区として、一人暮らし高齢者など、あるいは、要介護者数など、実態を把握するべきなのではないでしょうか。伺いたいと思います。","respondent":"中道都市開発課長","answer":"こういった再開発を含めたまちづくりというのは、非常に時間のかかる事業となっています。そうした中で、様々なご意見または不安な声、区のほうにもいただきますので、そうした声に丁寧に対応するよう指導してまいります。","voiceIndex":56,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。私からは、３４１ページ、水辺利活用事業、３６９ページ、マンション防災推進事業、また、３６６ページ、防災費全般から、富士山噴火降灰対策についてお伺いいたします。時間があれば、３３１ページ、地域交通検討経費。ぜひ非動力船のための船着場の増設、どんどん増やしていっていただきたいと思うのですけれども、その点、区としてはいかがお考えでしょうか。","respondent":"北原河川下水道課長","answer":"そういった活動を通じて、まずは、非動力船がより一層安全に楽しめることがスタートかなと考えています。その後、委員からご指摘あったようなことについても、必要に応じて検討してまいりたいと考えております。","voiceIndex":59,"id":"exchange-024"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。安全性の検証をされるということで、要は、動力船の引き波で非動力船があおられるとか、そういったことかなとは思うのですけれど、その考えでいいのかということと、あと、どちらにしても、川とか運河とか、水は１つですので、どうやってそういうふうにうまく動力船と非動力船を分けるのか、安全性を高めていくのか、現時点のお考えをお聞かせください。","respondent":"北原河川下水道課長","answer":"そういった意味で、非動力船をやっている団体と、動力船を扱っている業者と一緒に、安全性をお互いの船に乗って確認するといった取り組みを地域でやったり、様々取り組んでおる状況でして、そういった中で、お互いに理解を深めるとともに。","voiceIndex":61,"id":"exchange-025","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"マンション防災、マンションのエレベーターに閉じ込められたときの訓練、防止についてお伺いいたします。昨年１１月に、森澤区長は、港区長、江東区長、そして小池都知事と一緒にマンションのエレベーターに閉じ込められたことを想定した訓練を行われ、また、今月もマンションのエレベーターに閉じ込められるという訓練をされました。ぜひ区長の率直な感想を簡潔にお伺いいたしたいと思います。","respondent":"森澤区長","answer":"やはり停電したりして暗くなったりですとか、あと、狭い場所ですので、やはり初めて経験するとパニックになってしまうということは感じるところでありますので、やはり訓練をすることの重要性は感じているところであります。","voiceIndex":63,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"やはりあまり閉じ込められるという経験をされる方は少ないと思うのですけれども、それを受けて、具体的に区としてはどういった対策をしていくのか伺いたいと思います。","respondent":"平原防災課長","answer":"区では、エレベーター閉じ込め対策といたしまして、現在、令和６年度から、エレベーター用防災チェアを希望するマンションに配布させていただいておりまして、まずはそういったものの配布の中から、マンション側でどういった対策が必要かといったことを考えていただく。","voiceIndex":65,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした配られたチェアを使っての訓練とかを、ぜひマンション管理組合にお伝えしていっていただきたいと思いますけれども、一方で、東京都の予算で、都民ファーストの会として要望させていただいて、審議中ですけれど、エレベーター閉じ込め防止対策、リスタート機能の補助を行っていくという東京都の対策がありますけれども、そうした都の閉じ込め防止対策の事業と今後どのように連動していくのか。","respondent":"平原防災課長","answer":"そういったところで、それを得られましたら、どのようなメリット措置があるのか、そういったところは東京都の事業を、しっかり私どもも連携しながら進めてまいりたいというふうに考えてあります。","voiceIndex":67,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。品川区も、地域防災計画で、かなり分量多く書かれていると思います。普通の地震と異なるような被害が発生するかと思いますけれど、地域防災計画では、応急－２７７ページで、東京都とか国とかの機関の情報連絡体制が書かれておりますけれども、現在そうした行政機関同士のシミュレーションというか、そうした準備や訓練などはやられているのでしょうか。","respondent":"平原防災課長","answer":"東京都は、それを受けて、令和５年１２月に対策方針を出して、現在、東京都の地域防災計画の火山編の修正に向けて作業を進めているところですが、その作業の中で、区市町村と連携いたしまして、実際に広域で降った降灰、火山灰をどのように除灰するのか、どこが拠点になるのか。","voiceIndex":69,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ進めていっていただきたいと思います。１７０７年の宝永大噴火以来の出来事になるかもしれないのですけれども、３２０年前です。ただ一方、繰り返しになりますけれども、区民側の意識がまだまだ足りないのではないかと考えております。区民への周知と、独自の避難訓練の実施などを検討するべきだと思うのですけれども、その点、いかがお考えでしょうか。","respondent":"平原防災課長","answer":"ですので、在宅避難ができるようなところといった意味で、しっかりと備蓄の考え方、あるいは火山灰が降ったときのライフラインの考え方などは、地域防災計画を修正した時点では、各町会で説明させていただきましたが。","voiceIndex":71,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひよろしくお願い申し上げます。降った後の対策として、原則、所有者や管理者が対応することが原則で、区民で対応が困難なときは区が対応するというふうに、今、地域防災計画がありますけれど、やはり除去は、区民の方が自分でやるということは大変なケースもあるかと思いますので、降った後の対応ということもぜひお考えいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"},{"speaker":"せらく委員","kind":"確認","question":"子供の森公園のリニューアルにおいては、先ほども出ておりましたが、品川学園３年生からアイデアを集めるワークショップを開催したということで、子供の森公園は、かつて品川区で初めて子どもたちの意見を取り入れた公園であることを確認しております。間違っていたらすみません。園庭代わりや散歩で利用する近隣の保育施設の数も分かれば教えてください。","respondent":"大友公園課長","answer":"この公園の再整備に当たりまして、区民の意見の反映方法についてなのですけれども、公園近隣にお住まいの方や公園周辺の保育園のアンケート調査、また、公園利用者へのヒアリング調査、先ほど少しお話しさせていただいたところもあるのですけれども。","voiceIndex":75,"id":"exchange-032"},{"speaker":"せらく委員","kind":"質問","question":"区内の公園の遊具について、続いてお聞きしていくのですけれども、大きさだったり、小さかったり、あと楽しいものにしてほしいなどお話を聞いたりするのですけれども、区として、公園の遊具について、ご意見は把握していますでしょうか。","respondent":"大友公園課長","answer":"遊具の選定の考えですけれども、公園を大規模に改修する際には、設計段階におきまして、公園近隣にお住まいの方や利用者へのアンケート調査などを実施し、意見を聴取しております。","voiceIndex":77,"id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"近隣の方にアンケート調査をしていただいているということで承知しました。子どもの遊び場のリスクベネフィットアセスメントについて学んできましたので、品川区の公園について聞いてみたいと思います。区として、公園のリスクとベネフィットのバランスはどう考えていらっしゃいますでしょうか。子どもたちにとって、公園はどのような場所であると、心身の発達や成長に有益なものになると考えていますか。","respondent":"大友公園課長","answer":"しかしながら、その点も踏まえ、設置を検討しているところはあるかと思いますけれども、設置につきましては、合意形成も踏まえ、なかなか難しいところと考えているところです。","voiceIndex":79,"id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"おっしゃっていること、大変理解できます。子供の森公園においては、管理事務所があったり、また、近隣保育園が利用する際には、保育士の指導管理下のもと、子どもたちが遊べることもあります。ほかの管理人のいない公園と比べると、そういった公園は子どもたちにベネフィットにある遊具の設置が期待できるのではないかと思うのですけれども、そういったところのお考えを教えてください。","respondent":"大友公園課長","answer":"様々そういうような状況等々を注視して情報収集したいと考えています。","voiceIndex":81,"id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。次に、公園遊具の定期点検についてお聞きしたいのですけれども、頻度や、どのような業者が行うか教えてください。その際に、ぜひリスクベネフィットアセスメントを活用して、例えば老朽化した遊具があれば、リスクを低減しつつ、子どもにとってのベネフィットを最大限に活かす対策をしていただきたいと思いますが、教えていただきたいと思います。","respondent":"大友公園課長","answer":"それに伴って評価をさせていただきまして、その安全状況等を確認しています。その中には、老朽化であったり、現状の規格に合っているなど、様々な点検項目を設けて点検しています。","voiceIndex":83,"id":"exchange-036","title":"町会・自治会支援"},{"speaker":"せらく委員","kind":"質問","question":"年に一度点検をして評価しているということです。点検は専門業者が行っているのでしょうか。その点も教えてください。","respondent":"大友公園課長","answer":"遊具の点検につきましては、公園遊具等の知識のある専門業者で点検をしています。","voiceIndex":85,"id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"子どもたちの有益になる公園について、様々な質問をさせていただきました。引き続き、安全面の確保と、子どもたちにとって有益になるような公園の整備に向けて、区としても取り組んでいただきたいと思います。防犯カメラの部分を聞こうとしたのですけれども、時間がなくなってしまったので、以上にします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"私からは、３３１ページ、やさしいまちづくり整備費、３４３ページ、下水道管改修事業、３６７ページ、防災関係組織経費、時間があれば、５９０ページ、災害復旧費についてお伺いいたします。１点目に、防災関係組織経費についてお伺いいたします。内閣府は、策定の遅れの原因として、地元の社会福祉団体との連携不足を挙げていますが、課題についても確認させてください。","respondent":"平原防災課長","answer":"実際に支援に当たる方をそれだけスピーディーに確保できるのかどうかという点もありますけれども、そういったところは様々な方のネットワークづくり等々も含めまして、今後、さらに取り組みを進めてまいりたいというふうに考えてあります。","voiceIndex":89,"id":"exchange-039"},{"speaker":"横山委員","kind":"確認","question":"ご答弁ありがとうございました。しながわ防災学校では、子育て中の防災をテーマにコースを開講していますが、各保健センターで実施している両親学級と連携して、出産を控える方々に向けた子育て家庭の防災講座を実施してはいかがでしょうか。区のお考えをお聞かせください。２点目にいきます。やさしいまちづくり整備費についてお伺いいたします。目黒駅の工事の進捗状況について確認させてください。","respondent":"平原防災課長、櫻木地域交通政策課長、高梨都市計画課長","answer":"区では、しながわ防災学校の１つのコースといたしまして、「乳幼児のパパ・ママ×防災」という形で、子育て中にどのようなリスクがあるのか。ＪＲ目黒駅のエレベーターですが、令和６年度から工事着手しておりまして、今年の秋頃の完成を見込んでいるとＪＲからは報告を受けております。目黒線の混雑についてですが、現在、区へ直接お問い合わせ、苦情等をお寄せいただいている状況ではございませんが、東急目黒線は、令和５年３月より。","voiceIndex":91,"id":"exchange-040"},{"speaker":"横山委員","kind":"確認","question":"企業による勤務制度の見直しへの後押しや、鉄道事業者の混雑緩和の取り組みに対する支援方法の検討を行うなどが挙げられています。３点目にいきます。下水道管改修事業についてお伺いいたします。２０１７年の予算特別委員会でも確認させていただいたのですけれども、立会川幹線の老朽化と幹線の再構築の現状について、区が把握している最新の進捗状況を教えてください。","respondent":"高梨都市計画課長、北原河川下水道課長","answer":"区としましては、区内各鉄道事業者との共有を引き続き密に行っていくとともに、必要な支援や働きかけについて積極的に行ってまいりたい、このように考えてあります。立会川幹線再構築の進捗状況についてですが、こちらの幹線は、一部で老朽化が進んでいる状況でして、再構築を行う幹線として位置づけられておる全長約１０kmの幹線でございまして、令和５年度末現在では。","voiceIndex":95,"id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"下水道管の立会川幹線についてなのですけれども、１０kmのうち９００ｍが完成ということで、暗渠ですから、地盤が強いとは言いづらいのかなというふうに思っておりまして、都によっても優先して再構築を進めていただいているとは思うのですが、着実に再構築が推進していくよう、引き続き都への働きかけをよろしくお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-042"},{"speaker":"澤田委員","kind":"質問","question":"３５３ページ、公園・児童遊園設備費、３５７ページ、おもてなしトイレ整備でお伺いいたします。は３５３ページ、公園・児童遊園設備費についてお聞きします。昨年２０２４年では、東京でも６月中旬で３０度を超える日が続くなど、猛暑日も珍しくありませんでした。令和７年度、いよいよ工事が始まりますけれども、改修後にも子供の森公園での水遊び施設は設置されるのでしょうか。","respondent":"大友公園課長","answer":"開設当時からかいじゅう公園として愛されてきた公園ですけれども、改修後においても、子どもからご高齢の方まで、多くの方から愛される公園となるよう努めてまいる所存です。","voiceIndex":100,"id":"exchange-043"},{"speaker":"澤田委員","kind":"意見","question":"ミスト広場のような水遊び施設が設置されるということで、よかったなと考えています。水遊びなのですけれども、子どもたち、本当に大好きという子が多いと思うのですが、子供の森公園をはじめ、ほかの公園の水遊び施設も含めて、稼働状況と、その方法についてお聞かせください。","respondent":"大友公園課長","answer":"この稼働状況ですけれども、公園施設によって異なりますが、７月から９月を中心に稼働させております。その方法につきましては、管理スタッフにより、稼動の開始時にシステムを設定しています。","voiceIndex":102,"id":"exchange-044"},{"speaker":"澤田委員","kind":"質問・要望","question":"７月から９月を中心にというか、その時期に管理スタッフによって運営されている、稼働しているということですけれども、７月以外でも、６月とか１０月でも３０度を超える暑い日が多々ありますので、水遊び施設の稼働時間の延長を望む声もお聞きしています。気候変動に合わせて、水遊び施設の稼働時期の柔軟な対応を要望いたしますが、区のご見解をお聞かせください。","respondent":"大友公園課長","answer":"水遊び施設の稼働時期ですけれども、梅雨時期や子どもの夏休みなどを考慮して決めているところです。近年におきましては、５月でも３０度を超えるような日が観測されていることも踏まえ、来年度の稼働時期については検討してまいりたいと考えているところです。","voiceIndex":104,"id":"exchange-045"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ５月でも暑い日ということで、おっしゃるとおりだと思います。ぜひ柔軟な対応について、前向きなご検討をしていただければと思います。こちらは要望として次に移ります。続いては、おもてなしトイレ整備についてお聞きします。現在、区として、公園内のトイレの洋便器化を進めてくださっていますが、現在の状況をお示しください。","respondent":"大友公園課長","answer":"区が設置している公園・児童遊園トイレ、計１２９か所について、令和９年度の完了を目指して、年間１０か所程度、洋便器化を進めているところです。現在、１０５か所の洋便器化が完了しております。","voiceIndex":106,"id":"exchange-046"},{"speaker":"澤田委員","kind":"質問・要望","question":"残すところ僅かということが、２４か所ということが分かりました。東品川海上公園には幼児用補助便座が設置されているとお聞きしたことがあるのですが、区内の公園において、そのような幼児用補助便座を設置している公園はあるのでしょうか。今後、洋便器化を行う際や、子供の森公園のように改修する公園があれば、幼児用補助便座の設置もご検討いただきたいと考えますが、区のお考えをお聞かせください。","respondent":"大友公園課長","answer":"トイレの利用者の利便性向上に向け、幼児用補助便座の設置については、今後も検討してまいりたいと考えているところです。","voiceIndex":108,"id":"exchange-047"},{"speaker":"澤田委員","kind":"質問","question":"最後になりますけれども、公園の遊具について質問です。安全面等を考慮されてのことだとは思いますが、今後、公園の改修時には、幼児だけでなく、もう少し大きなお子さんでも楽しめるような遊具を望む声もありますが、区として、遊具についてどのようにお考えなのか、考え方や基準などがありましたらお聞かせください。","respondent":"大友公園課長","answer":"リニューアルに伴う交換の際には、最新の遊具の安全に関する基準に示されています遊具の安全領域を確保して整備していることから、同じ敷地であっても、取り替え前と同じ大きさの遊具が設置できないという場合が多くなっておりまして。","voiceIndex":110,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"よろしくお願いします。３７３ページ、防災総務費、３５０ページ、公園管理費、３５３ページ、公園ミスト設備設置、時間があれば、３５９ページ、私道整備事業について伺っていきます。重ならないようにということで、そこも少し当日も伺ったところではあったわけですけれども、気になったところでありましたので、そこはしっかりと先ほどの質疑のとおりかなというふうに私も思いました。","respondent":"羽鳥防災体制整備担当課長","answer":"イベント時に、どのようにＰＲしていくかというところで、今ご提案いただきました動画での使い方の説明など、今後、まだ導入したばかりで、まず、これからいろいろイベントに活用していただく機会がありますので、その中で、いろいろなお声も伺いながら。","voiceIndex":114,"id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"ぜひ動画を検討いただきたいと思います。今、職員の提案で、ガチャガチャとかやられていると思うのですけれども、例えばそういった形で販売をしていく、それは区の独自の歳入になったりとか、トイレトラックそのものの周知にもなるし、これは助けあいジャパンとかとのいろいろ関係とか、いろいろあろうかと思いますけれども、この辺をやったらどうかなというふうに思っています。すごいなと思いました。","respondent":"羽鳥防災体制整備担当課長","answer":"先ほど、えのした委員からも、塗り絵というお話もありましたけれど、今回、工作ができない小さいお子様もいらっしゃるということも想定されましたので、デザイン化されたものと、無地の白紙バージョンを作って、白紙バージョンに関しましては。","voiceIndex":116,"id":"exchange-050"},{"speaker":"つる委員","kind":"提案","question":"その葛飾区なのですが、葛飾区の新宿交通公園というところで、まさにトミカとかプラレールをイメージした公園が、その世界感をつくって公園ができるというところで、いろいろな公園の工夫があるのだなと、今日もいろいろな質疑が出ているわけでありますが、そうした中で、私も、２０２２年の予算特別委員会のときに、東京大空襲の様々な出来事に関連して、品川区の中に。","respondent":"大友公園課長","answer":"平和の名を冠した公園についてですけれども、公園の新設や改修の際を機に、どのような公園にするのか、いただいた意見も踏まえて検討してまいりたいと考えているところです。","voiceIndex":118,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ引き続き検討いただきたいと思います。ただ、今、品川区は、企業と協定を結んで、それに基づいて展開いただいているという側面もあろうかと思いますけれども、所管も当然違うわけでありますが、公園課として、例えば、先日も質疑させていただきました自動販売機の設置、増設、拡大だとか、屋外用のマイボトル給水機とか、この辺のことについて、公園課としての考え方を教えてください。","respondent":"大友公園課長","answer":"熱中症対策、また、公園利用者からの声や災害時の区民の飲料水確保などの視点を踏まえて、自動販売機の設置を引き続き検討してまいりたいと考えています。","voiceIndex":120,"id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"ただ、公園に行くと、そういえば自販機があるな、屋外用のマイボトル給水機があるな、そういった形で、そこでしっかりと涼を確保できるということの展開をぜひ公園課としても積極的に検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いいたします。本日は、３４５ページ、都市計画関係事務費から、羽田空港アクセス線新駅可能性地域まちづくり検討経費、３３１ページ、駅周辺等放置自転車対策事業についてお聞きします。最初に、羽田空港アクセス線新駅可能性地域まちづくり検討経費についてお伺いします。","respondent":"高梨都市計画課長","answer":"羽田アクセス線の新駅の可能性地域まちづくり検討についてですけれども、今、委員からご説明あったとおり、ＪＲ東日本によりアクセス線の工事が令和５年度より着手して進められているところです。","voiceIndex":124,"id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区としては、特に駅を要望しているわけではないということでよろしいでしょうか。東京貨物ターミナル駅ができるとすれば、恐らく八潮ということで、駅の有無によっては、八潮の都市整備計画にも関わってくると思うのですが、決定権は国土交通省とＪＲ東日本にあると思いますが、品川区の希望等があればお聞かせください。","respondent":"高梨都市計画課長","answer":"やはりＪＲとしましては、乗り降りするお客様がいないところには、なかなか駅を設置することは難しいですので、区としましては、いたずらにというか、新駅をただ要望するということだけではなくて、区民にとって、どのような利便があるのか、また。","voiceIndex":126,"id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問・要望","question":"来年度はこちらの予算で多方面からしっかりと検討していただきたいと思います。次に、駅周辺等放置自転車対策事業についてお聞きします。昨年７月より、放置自転車を減らす対策として、一部の区営駐輪場を２時間無料にするという試行を行っておりますが、放置自転車は、この実施により少し減ったのでしょうか。効果のほどをお聞かせください。","respondent":"山下交通安全担当課長","answer":"５駅８施設で実施したところなのですけれども、その周辺におきましては、全体で２４台の減少が見られました。","voiceIndex":128,"id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問","question":"若干減少が、効果があったということで、併せて啓蒙もされていらっしゃるので、少しずつ放置自転車が減っていくといいなとは思います。ただ、実際、自転車の駐輪場が足りているのかといった疑問があります。場所によっては、そもそも自転車の駐輪場が足りていないのではないかなと思いますが、いかがでしょうか。見解をお聞きします。","respondent":"山下交通安全担当課長","answer":"確かに区営の駐輪場は満車でご迷惑をかけているところはあると思いますけれども、例えば、定期の利用の空いている場所を当日利用に変えるとか、そういった対策等も行って利便性の向上に努めているところですので、その辺。","voiceIndex":130,"id":"exchange-057"},{"speaker":"おぎの委員","kind":"意見","question":"対策としてアプリなどもつくられているということで、そうしますと、まだ知らない方が多いのかなと思いますので、私のほうからも発信していきたいと思います。先日、ご答弁でも、品川区内では共働き世帯が７１.２％となっており、リモートワークなど、朝、出勤しないスタイルや、時間が違う働き方の業種などもあるとは思いますが、多くの方が、朝、通勤や通学で駅に向かわれると思います。","respondent":"山下交通安全担当課長、櫻木地域交通政策課長","answer":"先ほどお話がありましたけれども、短時間無料というのは、この４月から、当日利用できる駐輪場に展開していく予定なのですけれども、そういったところを踏まえまして、また対策を今後も検討していきたいと考えているところです。働き方の多様化ということで、通勤手段ということで、区では、シェアサイクルという形で、シェアリングエコノミーの一環として多様な交通手段も提供を進めているところです。","voiceIndex":132,"id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"通勤手段、自転車が今は結構多いのかなと考えていますが、シェアサイクルを含め、いろいろなものを検討していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３５１ページ、戸越公園駅前広場整備の中止、戸越公園駅周辺地区再開発事業に関わって、北地区の中止、そして３６５ページの区営住宅管理費に関わって、借上型区営住宅の実施について伺います。駅前広場です。計上した理由を伺います。立ち退かされる地権者も、区から一度も説明を受けていないと言っているもとで進めるべきではないと、中止を求めますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"もう１点、地域からは、駅前広場の必要はないのではないかというご意見ですが、昨年度、説明会等でもいろいろなご意見をいただいたところですが、区といたしましては、交通結節機能の強化であったり、商店街の再編に合わせまして、にぎわいの維持向上につきまして、現状。","voiceIndex":137,"id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"この中止を求めておきたいと思います。その隣で行われる戸越公園北地区再開発の問題です。今回、特に風の問題を伺いたいのですけれども、この駅前には四間通りがあって、１９番地が建ったことによって風がとても強くなったということで、お年寄りは、その道を通れない。実際に私も風速を測ってみました。この超高層によって住環境が悪化しているということを区は認識をしているのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"このような状況を踏まえまして、区では、再開発組合に対しまして、対応策の検討の実施について、今、話をしています。再開発組合からは、モニタリング調査や専門家のヒアリング等によりまして対応策を検討すると聞いているところです。","voiceIndex":139,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"１月の説明会の意見書の中でも反対の声のほうが多かったということで、これは既に３月の説明会のお知らせが配布されておりますけれども、予定どおり、また５月頃ですか、都市計画審議会にかけていくという段階ではないと、進めるべきではないと思いますが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、まちづくりの主体はそこに住む地域住民でございまして、その声に引き続き耳を傾けるとともに、１件１件真摯に対応してまいりたいと考えているところです。","voiceIndex":141,"id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"真摯に対応するということでしたら、これ、中止をするべきだと私は思いますけれども、まずは少なくとも一度立ち止まって、住民の皆さんと話し合いをする場を設けるべきだと思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"説明会等では、様々な意見、意見書でも区に寄せられているところではありますが、こうした声を真摯に受け止めるとともに、準備組合に対しては、届いた意見を届けるとともに、地域住民に対し、引き続き丁寧に説明するよう指導してまいりたいと考えているところです。","voiceIndex":143,"id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり住民の願いは、このように高い建物は戸越公園の町には必要ないという思いですので、中止をしていただきたいというふうに求めておきたいと思います。次に、区営住宅です。なので、民間アパートを活用して、借上型公営住宅を実施していただきたいと思うのですけれども、実施に向けての課題や、区の予算がどれくらい必要なのか伺います。","respondent":"川原住宅課長","answer":"賃借人が末永くお住まいいただくための施策というところではすごく難しいのかなと思われます。資金面については、実際に計上はしてございませんので申し上げることはできませんが、様々な使用料の徴収など債権管理業務なども発生するかと思います。","voiceIndex":145,"id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ有効期限はないようにしていただきたいと思いますが、切れた場合は、家賃補助で対応するなどしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-065"},{"speaker":"吉田委員","kind":"提案","question":"私は目黒川の近辺に住んでいて、地域を歩くと、福祉のことなどを伺おうと思って行っても、この目黒川の水をどうにかしてほしいというご意見があって、そのときに、目黒川の水が汚いのは、実はあなたのおうちの排水がということがうまく説明できなくて、そのような意味でも、雨水利用タンク設置助成というものは、区民に対しても生活改善のいい提案になると思いますし、ただ、やはり表現が難しいのです。","respondent":"北原河川下水道課長","answer":"合流式下水道に家庭内排水が流れ出てしまうことにより、油等が流れ出て汚れにつながるといったチラシについてですけれども、そういったものを見てもらうことで啓発につながるということで、私ども河川下水道課の前に置いて。","voiceIndex":150,"id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"それで、その置場のことなのです、今日ご意見を申し上げたいことは。少なくとも環境課や、それからエコルとごしもありますので、そのようなところで常設的に置く。環境問題に関心のある方は、福祉の部門にも、それから戸籍住民課にも行かれると思いますので、そのようなところに置き場所を広げるということは考えられないのか伺いたいと思います。","respondent":"北原河川下水道課長","answer":"ただ、確かに委員のご指摘のとおり、河川下水道課にいらっしゃる方は事業者が多かったりなど、そのようなところもありますので、どこに置いたら適切かというところも今後検討してまいりたいと思います。","voiceIndex":152,"id":"exchange-067"},{"speaker":"吉田委員","kind":"質問","question":"エコルとごしに置くということは、これ本当に環境の活動につながると思うのです。その視点でエコルとごしに置いていただくということや、それから環境系のイベントなどに置いていただくことはいかがでしょうか。","respondent":"中西環境課長","answer":"引き続きイベント、エコルフェス等もあります。講座もありますので、どういった形でそういったものが周知できるかといったものは、河川下水道課と連携しながら前向きに検討してまいりたいと考えています。","voiceIndex":154,"id":"exchange-068"},{"speaker":"吉田委員","kind":"提案","question":"展示の中では今までも私たちの提案を受け入れていただいて、例えば有害化学物質のことが、１行か２行だったかもしれないですけれども、採用していただいたり、とても環境のことについては採用していただけていると思うので、このたびは河川下水道課と併せて、この事業についての啓発をエコルとごしでぜひやっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"今後もどういった形で啓発を図っていくことが効果的かということは、環境課とも連携して検討してまいりたいと思います。","voiceIndex":156,"id":"exchange-069"},{"speaker":"吉田委員","kind":"質問・要望","question":"断水、まさに災害時には断水することが前提になっているわけですけれども、災害時の生活用水に使えるということを表示してはいかがでしょうか。ですから、浄水器と併せて使えばなおいいかなと思います。そのように考えると、しながわ防災体験館にこの雨水タンクのチラシを防災グッズの位置づけで置いて、一緒に簡易浄水器のアピールもしてはどうかと思うのですけれども、いかがでしょうか。","respondent":"平原防災課長","answer":"委員のご指摘のとおり、災害時の生活用水を含めた水の確保というものは非常に重要ですので、河川下水道課としっかり連携いたしまして、どのようにするか検討させていただければと思います。","voiceIndex":158,"id":"exchange-070"},{"speaker":"吉田委員","kind":"質問・要望","question":"１５０ｌのタンクなのですけれども、区があそこに展示しているものはもっと大きいのかな、やはりそれだけの生活用水がためてあるということは、１つ安心にもつながりますし、自宅避難を考えると、そのようなことも１つのアピールになるかなと思いますので、ぜひご検討いただきたいと思います。しながわ防災体験館で。ぜひ一緒にセットがいいかなと思うのですけれども、いかがでしょうか。","respondent":"平原防災課長","answer":"現在のあっ旋というところでは、簡易浄水器というものは入ってございませんけれども、そういったところ、仮に河川下水道課とセットでやるときには、どのようなものが水の確保の際必要なのかといったところも、きちんと併せてお示ししていきたいと考えています。","voiceIndex":160,"id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ合流改善、環境の視点、それから防災の視点で、この雨水タンクの利用を進めていっていただきたいと思います。雨水タンク何基助成するという目標の数が書いていなかったことが少し気になるところですけれども、ぜひ、この予算の決算のときに楽しみにしていきたいと思います。次に、しなみちレポートについて伺います。ただ問題なことは、これ視覚障害者はどうやって活用するのか伺いたいと思います。","respondent":"森道路課長","answer":"視覚障害者の方にしなみちレポートを使っていただくときに、今は視覚障害者の方がスムーズに使えるようなシステムにはなっていないというところは、１つ課題として認識しております。","voiceIndex":162,"id":"exchange-072"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、道路課だけで解決することは難しいかなと思いますので、ぜひ福祉の部門も一緒に検討していただけたらいいかなと思います。ぜひ福祉部のほうとも一緒に連携しながら、この制度が視覚障害者の方も使えるような形にしていっていただきたいと思うのですけれども、そちらのほかの部門との連携については、現状と今後の方針について伺いたいと思います。","respondent":"森道路課長","answer":"日頃からそういったブロックについては、しっかりと障害者支援課と連携して情報共有を図っておりますので、引き続き努めていきたいと思います。","voiceIndex":164,"id":"exchange-073"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろなところ、いろいろな場面について、全て、これは障害者のための制度、そうではない人のための制度などと分けないで、どの制度も、これはいろいろな障害がある方にとってどうだろうかという視点を、これは最後要望にとどめますけれども、ぜひ皆さんその視点で、先ほどの公園のことも一々障害者のためのなどと考えなくてもいいかなと。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"３６７ページ、防災対策総合推進費に関わって、国民保護共同訓練について、後半は、避難所における食事の質の確保を伺いたいと思います。抗議行動について中止を求めたり、住民を公道から排除したりしたとの事実はあるのか伺います。一般歩行者の通行の妨げにならない公道上の抗議活動について、品川区は表現の自由を守る立場に立つべきだと思いますが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"東京都に確認をいたしましたけれども、そういったことは把握していないと聞いております。あわせまして、品川区、東京都も含めてですけれども、反対する自由というものもあると思いますので、そういったものを排除するという意識は、私どもは持っていないと言わせていただきます。","voiceIndex":168,"id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"排除する意識はなかったとのご説明でした。私に寄せられた当日の写真でも確認しましたけれども、一般歩行者の通行を妨げている事実はありません。先ほど反対する住民の云々とありましたけれども、改めて品川区は、この表現の自由を守る立場に、つまり憲法の要請にのっとって、表現の自由を守る立場に立つべきだと、そこに言及していただきたいと思いますが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"そういったところで、一時的に立ち止まった方を促す、歩行するように促すような行動はあったやもしれぬという回答は受けておりますけれども、重ねまして、排除するというような行動は取っていないと聞いてあります。","voiceIndex":170,"id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"いずれにしても、この予算特別委員会の冒頭でも述べましたけれども、今回の訓練自体は、この非核平和都市宣言品川に反する訓練の参加や実施は行わないように、その点も重ねて強く要望したいと思います。続いて防災対策を伺います。国が指針を出しました。この食事の質の確保へ、思い切った対策強化を求めますが、いかがでしょうか。具体的に、何をどのように具体化していくのかも伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"その事業と連携いたしまして、災害時協力協定を締結する予定です。そういった形で、避難所で温かい食事を提供できるような体制を強化してまいりたいと考えています。","voiceIndex":172,"id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"キッチンカーとの連携強化で温かい食事の提供をということは歓迎したいと思います。これら一つひとつをどのように具体化していくのか、また、どのように具体化に向けた検討を進めていくのか、ここを伺いたいと思います。改めて私は、この防災計画上の位置づけを強化、充実させて、さらには様々な形での防災訓練の実施で、計画の実践度を高めていく必要があると思いますが、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"そういった中で、様々項目ある中で、全てを区として即時に対応するということは、やはり現実的に困難かなとは考えておりますが、可能な限り対応できるところから実施するということで、今回、まずは協定事業者との提携を始めたところです。","voiceIndex":174,"id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"可能な限り実施していきたいとのことでした。１点だけ、学校給食の活用についてさらに伺いたいと思います。つまり、民間業者が災害時に学校給食で被災者への食事の提供をどのように行うのか、どのような計画になっているのか、いずれにしても、この業者とも連携をして、災害時での食事の質の確保に向けて具体化を進めていただきたいと思いますが、現状と今後の改善、充実点などを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"学校給食の活用についてですが、こちらは他自治体の動向等も観察しながら、様々研究してまいりたいと考えています。","voiceIndex":176,"id":"exchange-079"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ他の自治体で見て研究はしていただきたいと思いますけれども、国の指針にも学校給食室の活用と位置づけられておりますので、早急に進めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-080"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"よろしくお願いします。３４７ページ、旗台小学校前地区整備事業、３４１ページ、雨水利用タンク設置助成についてお伺いをいたします。初めに、３４７ページ、旗台小学校前地区整備事業についてお尋ねをします。今回都内初となります、この密集法についてお伺いをさせていただきたいと思います。","respondent":"小川木密整備推進課長","answer":"今回はこの本地区の防災上の課題や権利者の状況等踏まえて、しっかりと地区における防災まちづくりを強力に進めていくために、都内初となる密集法に基づく防災街区整備推進機構を指定させていただいたところです。","voiceIndex":180,"id":"exchange-081"},{"speaker":"高橋（伸）委員","kind":"確認","question":"これ面積が約１,０００m2あると。荏原町の駅前の再開発のときも、同じく１,０００m2あって、敷地的には大体同じような敷地なのかなと考えています。今回プレスの発表ですと、長屋の建物が６列あって、４９戸あるとあります。共同住宅が２棟あると書いておりますけれども、これ確認であります。これ４９戸で正しいのかどうかということを、まず確認させてください。","respondent":"小川木密整備推進課長","answer":"長屋４９戸が正しい数字です。","voiceIndex":182,"id":"exchange-082"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ今後、早急にとは当然いかない問題、多々あるかと思いますけれども、様々な諸問題、課題ありますが、特にこの当該町会や近隣の町会には丁寧な説明をしていただきたいと考えています。今後恐らく丁寧に説明していただくと思うのですが、この先どのように取り組んでいくのかということをお尋ねさせてください。","respondent":"小川木密整備推進課長","answer":"引き続きそういったような場面を捉えながら、しっかりと取組についても周知のほうは行ってまいりたいと考えています。","voiceIndex":186,"id":"exchange-083"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひよろしくお願いをいたします。続きまして、３４１ページ、雨水利用タンク設置助成、グリーンインフラについてお尋ねをします。先ほど吉田委員からも質疑がございました。なるべくかぶらないように質問させてもらいたいと思います。建築用語だと「うすい」と私は認識しているのですけれども、これどちらでもよろしいのですか。","respondent":"北原河川下水道課長","answer":"一般的には「うすい」という形で呼んではおるのですけれども、ただ「うすい」という言葉が、言葉だけ聞くと少し伝わりづらいということもありまして、状況に応じて「あまみず」という表現をすることもあります。","voiceIndex":188,"id":"exchange-084"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私も建築に携わっているものですから、やはりもう当たり前に「うすい」と言っていて、「あまみず」と先ほどおっしゃったときに少し違和感があったので確認をさせてもらいました。それで、雨水利用タンク、私もすごいいい制度だ、設置というものはすごいいい。理由はいろいろあるかと思うのですけれども、実際理由はどういった点で伸びないのかということをお知らせいただきたいと思います。","respondent":"北原河川下水道課長","answer":"今年度の助成事業の利用の見込みですけれども、６件という形になってございまして、委員がご指摘のように、私たちが目指している量よりはちょっと少ないのかなという考えです。","voiceIndex":190,"id":"exchange-085"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。これも、先ほど来エコルとごしというお話が出ていました。実際これ展示をして、来場者の声がどのようにあったのかということのお尋ねと、もう１点が、これ周知について、増改築施工業者事務連絡会というものが、これもＰＲをしているということなのですけれども、事務連絡会というものが私よく分からないので、どのような連絡会なのかということをお知らせいただきたいと思います。","respondent":"北原河川下水道課長","answer":"エコルとごしで展示をやった際の声ということですけれども、例えば雨水タンクにつきましては、雨水をためておくといざというときに役に立つという意見や、雨水タンクを実際にもう設置をしている方などが、夏の水まきに実際に使っているというような意見がございました。","voiceIndex":192,"id":"exchange-086","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"提案","question":"分かりました。やはりそのような、何というのですか、創意工夫をしていく、防災訓練などでも、いろいろ区の訓練などでも、イベントには展示して、いろいろ周知をしていることは私も分かっているのですけれども、やはりそのような手法も必要なのではないのかなと考えていますが、それについて、私は今後ぜひ提案をしていただきたいと考えていますけれども、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"区政協力委員会でのそういった情報提供等、いろいろ委員からもご提案いただきましたので、我々としても少しでも普及が進むように、どういったやり方がいいか、今後も引き続き検討してまいりたいと思います。","voiceIndex":196,"id":"exchange-087","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"確認","question":"分かりました。ぜひよろしくお願いします。エコルとごしもすごく私は有効的だと思っているので、お子さんも目に触れて、その保護者の方も目に触れる、それで確認をして取り付けてもらう、それは有効的だと思いますので、ぜひ含めて、区政協力委員会を含めてよろしくお願いをいたします。今後引継ぎなどきちんとやっていただいて、ぜひよろしくお願いをいたします。何かあればよろしくお願いします。","respondent":"北原河川下水道課長","answer":"私もこの２年間、この議会の場で様々な意見をいただきました。改善できるものは速やかに改善してきたつもりですけれども、２年間という期間では解決できないこともありますので、きちんと引き継いで、１歩ずつ進むようにしてまいりたいと思います。","voiceIndex":198,"id":"exchange-088","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問","question":"私は、今日は３６５ページ、住宅確保要配慮者入居促進事業ならびに住宅支援経費、それから３６９ページの防災体制整備費でいいのかな、というところです。あわせて、居住支援法人にお願いをするということになると思いますけれども、見守りというものについて、見守りというものはどのようなことをイメージ、想定をしているのかお聞きいたします。","respondent":"川原住宅課長","answer":"１点目の居住支援法人の協議の進捗状況についてのお尋ねからご回答をします。居住支援法人の状況についてですが、現在区内の３者の事業者が、指定に向けて、指定申請窓口はこちら東京都となりますけれども、東京都のほうにも出向いていただいて、具体的な協議中です。","voiceIndex":201,"id":"exchange-089"},{"speaker":"塚本委員","kind":"確認","question":"昨年法改正があって、この居住支援法人の、そういったいろいろな見守りとも密接に関係すると思いますけれども、居住サポート住宅というものができると。どういったことを主に基準として考えていくのか、また、認定に向けた現在の進捗状況、国からの指針が少し遅れているのだという話をお聞きしておりますけれども、その点についても確認したいと思いますが、よろしくお願いいたします。","respondent":"川原住宅課長","answer":"認定の基準となる住居の平米数であるとか、耐震化の基準とか、そういった細かいところが分かれば、住宅のある程度の候補とする目安が分かりますので、そういった住戸の候補をでき次第、こちらが協力させていただいている不動産団体への周知などに努め。","voiceIndex":203,"id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"まだこれからそういった認定に向けてのいろいろな努力が必要だというところは伺いましたけれども、ニーズはこれ非常に多くて、３戸、４戸ではまだまだ最初の一歩というようなところで、大きく拡大していく必要性のある事業と考えておりますので、ぜひこの認定に向けて、また居住支援というものの法人の指定に向けて、進めていただきたいと考えています。","respondent":"羽鳥防災体制整備担当課長","answer":"区といたしましては、都のひな形に沿いまして、現在各区のトイレの状況を確認して、先ほど５０人に１基、２０人に１基というところは、スフィア基準でも示されている数値ではありますが、そちらに現状がどうなのかというところをまず分析をして、今後の課題を出して。","voiceIndex":205,"id":"exchange-091"},{"speaker":"塚本委員","kind":"質問・要望","question":"非常に大事な計画でありますし、都と区と、そのような中での、今後は都のほうからきっといろいろな補助金などもつくのであろうというような予測がされますので、そういったこともしっかりと受け止めながらというか、認識しながら進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お願いします。私からは、３５７ページのしながわ水族館リニューアル経費です。昨年、私は神戸市のアトアという都市型水族館を視察してまいりまして、しながわ水族館の目指すべき方向性に非常にマッチしているかなというように感じました。質問ですが、区として、アトアですけれども、調査されたり、現在されていますでしょうか。","respondent":"大友公園課長","answer":"アトアという水族館についてですけれども、神戸市にある民間の水族館と認識しています。こちらにつきましては、昨年私どもも都市型水族館の参考といたしまして、視察をさせていただいているところです。","voiceIndex":209,"id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"であれば、ぜひその感想などがあればお聞かせいただきたいのですが、いかがですか。","respondent":"大友公園課長","answer":"アトア、こちらのほう、アートとアクアリウムが融合した新しい形の水族館であったと認識しております。視察した感想ですけれども、感想なので個人的なところもあるのですが、全体といたしましては、美術館や博物館といったような落ち着いた印象を受けたところです。","voiceIndex":211,"id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私もほぼ同意見で、非常にいい展示というか、本当に都市型の水族館だなというように感じました。それで、広さの面でいうと、現在のしながわ水族館の延べ床面積が約４,０００m2ということで、アトアは大体５,６００m2ということ、少し大きいぐらいなのですけれども、リニューアルした後のしながわ水族館の延べ床面積、大体どれぐらいになるかという目安がもしあれば教えてください。","respondent":"大友公園課長","answer":"現在の想定ですけれども、令和４年に策定いたしましたしながわ水族館リニューアルの方向性についてでは、中規模、延べ床面積５,０００m2程度の水族館とすることが示されているところです。今後この方向性に沿って、リニューアルの検討を進めてまいりたいと考えております。","voiceIndex":213,"id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"かなり少ない。でも人気を博しているということで、サイズ感で見ても、やはりアトアというものは非常に参考になるかなとは思うので、ぜひ積極的に研究して、取り入れていただきたいと思うのですが、最後に何かあれば一言お願いします。","respondent":"大友公園課長","answer":"都市型水族館として、水量で勝負するのではなくて、その見せ方で勝負するというところでほかの水族館との差別化を図っているところで、非常に参考になるものであると認識しています。","voiceIndex":215,"id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"提案","question":"これは要望です。続いて提案したいことが、ＭＲ技術を活用した展示です。昨今ＶＲとか、ＭＲとか、ＡＲとか、様々あるのですけれども、ちなみにＭＲという技術についてはご存じでいらっしゃいますでしょうか。","respondent":"大友公園課長","answer":"バーチャル体験の１種というところで認識していますが、現実とバーチャルの融合体験を含みで、ＭＲという形でそうしているのかなと考えております。","voiceIndex":217,"id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そうですね。例えばＶＲというものは仮想現実ということで、結構ごついゴーグルをつけて、言ってみたら、何ですか、全てが仮想空間ということです。現在、こういったＭＲの技術を採用している水族館、もし把握していれば教えてください。","respondent":"大友公園課長","answer":"様々なデジタルの手法というところが最近の水族館で取り入れられているというところは認識しているところ、また調査しているところではありますけれども、ＭＲというものを前面に打ち出して導入している水族館は把握をしているところはございません。","voiceIndex":219,"id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"質問","question":"このＭＲ技術を提供している会社がティフォン株式会社なのですけれども、ご存じでしょうか。品川区にあるのです。ＭＲであれば定期的に映像を変えることができるので、リニューアルが簡単だと。ぜひ、もし研究といいますか、してほしいなと思うのですが、いかがでしょうか。","respondent":"大友公園課長","answer":"委員からの提案の内容も含めまして、先ほどご提案いただいた内容の活用等々も調査、検討してまいりたいと考えているところです。","voiceIndex":221,"id":"exchange-099"},{"speaker":"松永委員","kind":"質問・要望","question":"３３１ページの交通安全啓発事業について、３３９ページの橋梁維持管理費について、３５３ページの可動式ドッグラン設置について、３５３ページ、大森貝塚遺跡庭園改修工事実施設計委託について、時間がありましたら、３５５ページの新浜川公園基本設計委託について、３５７ページのしながわ水族館のリニューアルについて伺います。３３１ページの交通安全啓発事業について、自転車マナーについて伺います。","respondent":"山下交通安全担当課長","answer":"区といたしましても、ＳＮＳ、また広報紙等を用いまして、そういった周知の広報、啓発活動は行っているところですが、また引き続き、こういった広報も実施してまいりたいと考えているところです。お子さんの逆走ですが、逆走というものはなかなかなくならない。","voiceIndex":225,"id":"exchange-100"},{"speaker":"松永委員","kind":"質問・要望","question":"誰でも参加できるスケアード・ストレート方式の自転車安全教室を、ぜひまた西大井などでやっていただければというように要望します。私ちょっと現場を見ていましたので。こうしたことが、どちらが悪いのか理解されていない方がおられると思います。これに関連して、交通渋滞について伺います。その現状について把握されておりますでしょうか。その対策について、警察署との連携について併せて伺います。","respondent":"山下交通安全担当課長、森道路課長","answer":"ヘルメットのお話ですが、将来的に義務化になるかというところですけれども、確かに委員のおっしゃるとおり、シートベルトの着用率や原付のヘルメットの義務化に伴う着用率。今後、新しい庁舎の建設が進みまして、車の流れ、人の流れが変わってきますと、また状況変わってくると思いますので、その頃にはまた再度検討させていただければと思います。","voiceIndex":227,"id":"exchange-101"},{"speaker":"松永委員","kind":"質問","question":"ちょっと順番を入れ替えまして、次に３５３ページの大森貝塚遺跡庭園改修実施設計委託について伺います。それに伴って損傷箇所などの改修工事を行われると伺っておりますが、バリアフリーについてはどうなのでしょうか。そうしたところも含めまして、バリアフリー化を進めて、内容がちょっと分からないので、そういったところもバリアフリーになっているのか伺います。","respondent":"大友公園課長","answer":"令和７年度に設計をしまして、令和８年度に工事を進めていくところなのですけれども、現在もこちらのほう、バリアフリーの視点というところでは不足しているところが多々あるかと思います。その視点についても、この設計の中で含んで検討してまいりたいと考えているところです。","voiceIndex":230,"id":"exchange-102"},{"speaker":"松永委員","kind":"提案","question":"２年後のこの１５０周年記念という形で、式典やイベントというものは行われるのでしょうか。例えばイベントが行われるのであれば、以前もちょっとご提案させていただきましたけれども、キッチンカーで縄文クッキーや大森貝塚マドレーヌなどを販売するなどの、１５０周年にふさわしいイベントにしていただきたいと思いますが、いかがでしょうか。式典は行われるのでしょうか。伺います。","respondent":"大友公園課長","answer":"１５０周年である令和９年度、どのような形で迎えるかにつきましては、関係部署との連携をしまして、検討してまいりたいと考えているところです。基本的にはイベント等々、何かしらの形で実施するものと捉えております。","voiceIndex":232,"id":"exchange-103"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ盛大にイベントを開催していただきたいと考えています。そこで、もし式典を行うのであれば、どういった形で行っていかれるのかなということで、いろいろ私も考えたのですが、例えばモース博士につながりのある方を来賓として呼んでみてはいかがでしょうか。","respondent":"大友公園課長","answer":"公園課の所管を少し超えてのお話をすることもあるかもしれませんけれども、関係部署との連携をして、どのような形でのイベントが適切かというところは検討してまいりたいと考えているところです。","voiceIndex":234,"id":"exchange-104"},{"speaker":"松永委員","kind":"確認","question":"３５５ページの新浜川公園のことについて伺います。先ほどの公衆便所についての質疑がありましたが、公衆便所以外に浜川砲台、キャッチボール場、砂場、そして北側にあります一部の雑草が生えている公園、全体の整備を検討されているということでよろしいのでしょうか。確認です。","respondent":"大友公園課長","answer":"来年度に予定しております新浜川公園の改修の設計ですけれども、便所の改修等々のみではなく、公園全体の改修ということで検討しているものです。","voiceIndex":236,"id":"exchange-105"},{"speaker":"松永委員","kind":"質問・要望","question":"あそこの新浜川公園のところでは、なかなか自転車をとめるスペースがないという要望も受け取っております。これは要望で終わります。次に、３５７ページのしながわ水族館のリニューアルに伴って、しながわ区民公園の池の利活用について伺います。以前この質問をさせていただいたときに、実際やってみたのだけれども、日光、日当たりがよくて藻が多く発生して難しいと伺った記憶があります。","respondent":"大友公園課長","answer":"こちらのほう、水質浄化の機器等にボートが当たり破損するなど、先ほど委員がお話しいただいたように、水質の影響等々課題があり、ちょっとなかなか断念したというところがあると認識しているところなのですけれども。","voiceIndex":238,"id":"exchange-106"},{"speaker":"こしば委員","kind":"提案","question":"西村委員の質問、提案のほう、２点ございまして、近年の交通サービスの状況を踏まえて、コミュニティバス試行運行の延長を求めたこと、また、もう一つは、地域住民にオンデマンドがいいのか、また、従来型のコミュニティバスがいいのか、意識調査をすべきという提案がございました。ですから、その評価項目の１つ、高齢者の居住状況も、コミュニティバスの導入に向けては欠かせない項目であったと思います。","respondent":"櫻木地域交通政策課長","answer":"一定、収支の議論等様々積み重ねていく中で、本来的に区として、高齢者の方に一定の配慮が必要であるということと、今回そのタイミングで新たに試行するに当たって、利用状況が読めないということであったことから一定の判断を下したと、そのような認識です。","voiceIndex":242,"id":"exchange-107"},{"speaker":"こしば委員","kind":"質問","question":"高齢者への一定の配慮が必要であったということと、利用状況はなかなか予測できなかったという答弁をいただきました。その中で、これでいろいろと年月もたちましたけれども、高齢者の中でシルバーパスの割合というものは、大体全体の中で何割ぐらいなのか教えていただけばと思います。","respondent":"櫻木地域交通政策課長","answer":"シルバーパスの収支割合ですが、おおむね４３.５％がシルバーパスの利用により無料でご利用いただいているという形になります。","voiceIndex":244,"id":"exchange-108"},{"speaker":"こしば委員","kind":"質問","question":"４３.５％、高齢者のかなりの数がやはりシルバーパスを利用していますね。確かにシルバーパスの利用が多ければ多いほど、その分の、本来ならば得られるはずの運賃収入が得られないというわけですから、これが、例えば民間のバス会社であれば、この東京バス協会に加盟していない民間バス会社であれば、これ事業評価はマイナス、大きなマイナスになってしまうと思います。","respondent":"櫻木地域交通政策課長","answer":"シルバーパスの適用有無等については、様々な住民合意の中で考えていくものだと考えております。","voiceIndex":246,"id":"exchange-109"},{"speaker":"こしば委員","kind":"質問・要望","question":"コミュニティバスの本格運行に進むかどうかの判断で、仮に進まないと判断をしたとしても、それで終わりではなく、先ほども話しましたが、コミュニティバスの導入計画に当たって、この１３地域の中で最も交通の利便性が求められてきたものが西大井のエリアでありましたので、その辺り、しっかりと利便性の向上を図り、あまねく住民の皆様に移動の自由を提供できるよう求めますが。","respondent":"櫻木地域交通政策課長","answer":"区としましては、引き続き課題は残っているということは認識しておりまして、委員からご指摘いただきましたとおり、オンデマンド交通や新しい交通サービスの提供可能性などの動向を注視して、考えてまいりたいと考えています。","voiceIndex":248,"id":"exchange-110"},{"speaker":"こしば委員","kind":"質問・要望","question":"地域住民から移動の自由を求める声も届いておりますので、ぜひその辺りも勘案していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"３５１ページ、公園・児童遊園維持管理費について、３３１ページ、交通安全対策について、３４１ページ、水辺利活用促進、３３１ページの地域交通検討経費について、コミュニティバスです。これ答弁求めません。今自動運転だ何だと、どんどん進歩しているのに、今さら、これもう何年検討するのですか。これぜひ考えていただきたい。その点についてどのようにお考えか教えてください。はそこまでお願いします。","respondent":"北原河川下水道課長、大友公園課長","answer":"そういった意味で、様々な部署でいろいろな取組がなされているということで、連携もきちんとしながら効果的な事業の推進に努めてまいりたいと考えております。その必要性を加味して、ではどのような形で遊べる場を設けていくのか、また過ごせる場を設けていくのかということは課題として考えておりまして、こちらについては、具体的に示せるところはございませんけれども。","voiceIndex":252,"id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"だからそこの利活用として、そういったものを民間業者と連携をして行っていくなど、様々な、これはちょっと所管が変わってくるのであれですけれども、そこは公園課と福祉部と、福祉というか、子育てのほうとぜひ連携をしていただければと思いますが、これ全体的に企画は大丈夫ですか。こういった意味では、死亡事故があった交差点や通学路などは優先をするべきだということで求めました。","respondent":"山下交通安全担当課長","answer":"ただ、区として一概にここでやりましょうというわけではなく、やはり警察との連携等も必要になってきますので、そういったご意見や、また必要性を、我々のほうでも様々考えながら、警察のほうに申入れするなり。","voiceIndex":255,"id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ進めて、もちろん信号機は警察の管轄ですからあれですけれども、いわゆる通学路だったり、高齢者の安全対策だったり、区民の安全対策というものはやはり品川区でしっかりと検討していかなければいけないと思いますので、ぜひそこは警察との連携をしていただいて、また通学路だと教育委員会とも連携をしながら、ぜひ進めていっていただきたいなと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-114"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３３１ページ、西大井駅自転車等駐輪場改修工事実施設計、３４９ページ、大井町駅周辺地区社会実験委託、３６５ページ、住宅確保要配慮者入居促進事業経費、順不同でお聞きしてまいりたいと思います。大井町駅周辺地区社会実験委託、これは新規事業と認識しておりますが、まず、どこでどのような社会実験を実施されようと考えているのか、簡潔に、具体的な事業内容をお願いしたいと思います。","respondent":"中道都市開発課長","answer":"社会実験の場所ですが、大井町のどんたく通りで、実施するというような予定をしています。","voiceIndex":259,"id":"exchange-115"},{"speaker":"こんの委員","kind":"確認","question":"秋口を目指して、社会実験を実施してくださるということです。大いに期待しておりますので、よろしくお願いいたします。次に参ります。そこでお聞きするのですが、この入居促進事業を、これそれぞれの所管でやってくださっているのですか。この事業を統括する課というものは、住宅課でよろしいのでしょうか。そこを確認させてください。","respondent":"川原住宅課長","answer":"ただ、今のすみ分けとしては、大家や不動産会社への支援の部分は住宅課で予算を取ってございまして、いわゆる要配慮者、それぞれの要配慮者に応じて各課が支援をしていますところについては、居住支援においては各課で予算を取っているような形ですが。","voiceIndex":263,"id":"exchange-116"},{"speaker":"こんの委員","kind":"質問","question":"高齢者と障害者においては、礼金、敷金、仲介手数料、これを合わせて単身者は１０万５,０００円、世帯は１６万５,０００円を補助している。ここを同じメニューにすることが必要ではないかと考えるわけですが、そうしたことも、情報収集しながらそこを整理していくということも住宅課ではないかなと思われるのですけれども、その辺はどのようにお考えでしょうか。","respondent":"川原住宅課長","answer":"住宅課におきましても、来年度組織を強化できる見込みでございまして、今後におきましては、まず各課の支援メニューをしっかりと知るというところからスタートにはなるのですけれども、必要な協議については関係各課と引き続き行っていくところと。","voiceIndex":265,"id":"exchange-117"},{"speaker":"こんの委員","kind":"提案","question":"そこで１つ提案なのですけれども、この要配慮者の方々が、要配慮者だけではないのですが、いわゆる賃貸の物件を借りていらっしゃる方々に共通してある課題なのですけれども、２年ごとに更新が、家賃の更新、契約の更新が行われます。この更新料、このときに苦労されているお話をよく聞きます。","respondent":"川原住宅課長","answer":"様々なご意見をいただきまして、ありがとうあります。更新料の部分の支援というところのご意見もいただいたかと思います。現在実施している、先ほど……。","voiceIndex":267,"id":"exchange-118"},{"speaker":"鈴木委員","kind":"提案","question":"そしてその中で、新たな整備方針の策定に向けて、路線ごとの状況や必要性の検証を行い、優先整備路線や見直し、工法、路線等の検討を行っていくということなのですけれども、この検討というものはいつ頃までにまとめるということなのかということと、それから区のほうから、第５次に向けて優先整備路線の、何というのですか。","respondent":"高梨都市計画課長","answer":"今、具体的に細かいスケジュール等々はまだ示されているところではございませんけれども、令和７年度末までが現在の事業化計画ですので、それが終わるまでには次の新しい整備計画を策定するべく、検討を進めているといったようなところです。","voiceIndex":270,"id":"exchange-119"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう決まってしまってからでは遅いなと思っていまして、その辺のところをぜひ声も届けていきたいと思いますし、聴いてもいただきたいなと思っているのですが、１０年ごとの計画になるので、１０年前にも、第４次に向けて、ぜひこれを優先整備路線に入れないでくださいということが、地域でもかなり運動になりまして、私の地域でも中延駅前の３０号線がその検討の対象になったということで。","respondent":"高梨都市計画課長","answer":"ただ、道路という、やはり都市施設の性格上、その場だけではなくて、広域に見て、防災機能や市街地形成のための機能など、求められる必要性というようなものをしっかりと検討しなければいけないという部分もありますので。","voiceIndex":272,"id":"exchange-120"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ地域で反対運動が起こっていて、地域の方が望まないということがはっきりしている３０号線や３１号線、２７号線は、優先整備路線の中には入れないようにしていただきたいということで要望もさせていただきたいと思います。ちょっと時間がなくなってきてしまったのですけれども、あと下水道の耐震化について伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長、北原河川下水道課長","answer":"私のほうからは避難所のトイレについてお答えします。避難所までの下水管のほうは、耐震化１００％済んでいるところです。各避難所に関しましても、耐震化のトイレの整備も進んでおります。そういった意味では、下水道管の耐震化がなされていれば、基本的にはトイレも利用できるという状況になります。一般の住宅につきましては、優先順位をつけて進めているところで、そういった計画は今のところございません。","voiceIndex":274,"id":"exchange-121"},{"speaker":"田中委員","kind":"質問","question":"ですから、いわゆる被害想定、どのような観点で見るかということが大きな問題、課題だと思いますが、ざっくりでいいのですけれども、この１０年間見て、１０年前と今とで、いわゆる被害想定、どのような変化があったのかという認識をされているのか、まずお伺いします。","respondent":"平原防災課長","answer":"例えば建物の倒壊棟数につきましても、１０年前は２万４,０００棟ぐらいが想定されていたところ、令和４年想定では９,０００棟といったところで、大幅に減少しています。それに伴いまして、死者数等々の人的被害も減少しているものというように認識しています。","voiceIndex":278,"id":"exchange-122"},{"speaker":"田中委員","kind":"質問","question":"届きましたでしょうか。これは災害復旧特別会計の表なのですけれども、令和７年度１５億円で、平成２８年に特別会計の条例ができ、およびその基金条例ができて、平成２９年から特別会計が始まっています。要は、このように状況変化があるにもかかわらず、全く１円たりともその変化のない特別会計を、新年度もまた予算計上して議決をしてしまっていいのか、ここをお伺いしたいと思います。","respondent":"平原防災課長","answer":"例えば能登半島地震発災直後に、これ輪島市の事例ですけれども、直ちに１月４日に専決処分で予算を計上しているのですが、どういったものにどれぐらいのものが必要だったかといったところの分析も、私どものところで行っておりますので、そういったところを。","voiceIndex":280,"id":"exchange-123"},{"speaker":"田中委員","kind":"質問","question":"１０年間変えていないという、この間、能登半島でもあったり、大阪でも大きな地震があったりと、見直すタイミングはいっぱいあったと思います。私はこの数字が全く変わっていないということは、その意識が本当にここにどこまで伝わっているのかという思いをしてならないのですけれども、改めてお伺いしたいと思います。","respondent":"平原防災課長","answer":"今何もやってないというような、お答えがそのように聞こえたかもしれませんけれども、令和５年の地域防災計画の大規模修正の際には、そういったところを加味して行っておりまして、現状予算額で変更といったところまではいかなかったといったところですが。","voiceIndex":282,"id":"exchange-124"},{"speaker":"田中委員","kind":"質問・要望","question":"いっぱい言いたいことはあるのですけれども、ぜひ最新の想定を踏まえて、本当に起きたときにしっかり対応できるような備えをしていただきたいと思います。これは東京都の事業ではありますが、このようなところこそ都と連携して、河川下水道課としても住民にアピールをしていただきたいと思いますけれども、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"下水道に油を流さないようにお願いする内容を、東京都下水道局のホームページのリンクを河川下水道課で貼っておりまして、ポスターも河川下水道課の前に掲出しております。今後も連携を図ってまいりたいと考えています。","voiceIndex":284,"id":"exchange-125"},{"speaker":"せお委員","kind":"質問","question":"よろしくお願いします。３３１ページ、交通安全啓発事業、３３５ページ、しなみちレポートについてお伺いします。これが書かれています。こういった安全教育する場としては、ご家庭、幼稚園、保育園、学校、地域と様々、区や警察でも取り組んでいただいていますけれども、子どもへの安全教育の取組の中で、どれが効果があったのか、あるのか、その辺どう感じておられるか教えてください。お願いします。","respondent":"山下交通安全担当課長","answer":"子どもの事故についてですが、委員のご指摘のとおり、歩行者の事故で一番多いのは７歳の子どもという統計結果も出ております。","voiceIndex":287,"id":"exchange-126"},{"speaker":"せお委員","kind":"質問・要望","question":"これは、教育委員会、学校、あと道路管理者、警察と３か所でそれぞれ取り組んでいただいたようなので、分かる範囲で結構ですけれども、令和５年度までにどのような対策完了したのか、おおむねのところで教えてください。続けます。ですから、そもそも子どもが飛び出すことができないだったり、子どもが線引きしやすいところで仕組み、道路をつくることが必要だと考えています。","respondent":"山下交通安全担当課長","answer":"今後やるかやらないかですけれども、こういったことは必要であれば継続していくことも大切だと考えています。必要に応じて必要なことを、できることを一つひとつ対策、対応してまいりたいと考えています。","voiceIndex":289,"id":"exchange-127"},{"speaker":"せお委員","kind":"提案","question":"もう起こってからでは遅いので、ぜひ積極的に計画的に進めていただきたいと思います。次に移ります。しなみちレポートです。こちらも会派のまつざわ委員が提案しています周知と、あと利便性の向上のために、公園の看板などにしなみちレポートに飛べるＱＲコードなど貼っておけば活用できるのではないかと、こちらも検討状況を教えてください。","respondent":"森道路課長、大友公園課長","answer":"町会への働きかけということもご提案いただきましたので、しっかりとその辺は地域活動課と進めてまいりたいと考えております。現在の周知方法といたしましては、チラシ配布等々、工事案内等々について登録アプリの形態であったり、様々な手法で登録しています。引き続き公園の看板についても検討してまいりたいと考えているところです。","voiceIndex":291,"id":"exchange-128"},{"speaker":"若林委員","kind":"質問","question":"３６６ページの防災費について伺います。避難所の環境整備や機能強化が、来年度は特にスフィア基準への対応も始まるというタイミングです。この両面の状況を総合的に判断して、脆弱な避難所、いわゆる避難所のエリアをしっかりとてこ入れして、強化していく。こういったものがハード的にしっかり機能するのかどうか。こういった考え方について、品川区の見解を伺いたいと思います。","respondent":"平原防災課長","answer":"そういったところは、地域防災計画とは別計画になりますけれども、国土強靱化のところ、品川区強靱化計画でも併せて実施しているものですので、今後そういったところを総合的に評価していく必要があるものと認識しています。","voiceIndex":296,"id":"exchange-129"},{"speaker":"若林委員","kind":"質問・要望","question":"地区防災計画がありました。私の記憶だと、スタートしたのがもう数年前ぐらいかな、要はモデルということで、今の視点も踏まえて、しっかり進めていただきたい。品川区では２０２５年度までに不燃化領域率を全体で５４.５％に引き上げる目標は変わっていないと思います。最終的には７０％だと思います。老朽住宅が密集する。両避難所と周辺の環境について、当局はどのように捉えているかお聞きします。","respondent":"小川木密整備推進課長","answer":"拡幅整備に当たりましては、こちらの事業はまだ任意事業とはなりますけれども、沿道建物の建て替えの際に順次拡幅が進むよう、密集事業であったり、細街路拡幅整備事業の中で積極的に取り組んでいきたいというふうな考えです。","voiceIndex":298,"id":"exchange-130"},{"speaker":"若林委員","kind":"質問","question":"避難所を中心に見ると、人がいる。今の２つの学校については、改築困難という難題を今抱えているところです。避難所を中心に見たときに、また学校を中心に見たときに、まちづくり部門として、これはいろいろな形、意味があると思いますけれども、連携とかという形も含めて、どのような形で進めれば、一段とこの脆弱な地域の防災強化がなされるのか、その進め方について現在のお考えをお聞きしたいと思います。","respondent":"小川木密整備推進課長","answer":"そういった取組の中で、避難所であったり、そういう面的なところの取組についてのご意見等もいただきながら、総合的な防災まちづくりに取り組んでまいりたいというふうに考えてあります。","voiceIndex":300,"id":"exchange-131"},{"speaker":"若林委員","kind":"質問","question":"学校についての言及は、今のご答弁の中ではございませんけれども、また、それについては、別途取り上げたいと存じております。時間の中で３４１ページの来年度新規事業かと思いますが、水辺利活用に向けた基礎データ調査委託が８４０万円ほど計上されておりますけれども、これについてのご説明を、最後にお聞きしたいと思います。","respondent":"北原河川下水道課長","answer":"現在策定しております水辺利活用推進計画におきましては、イベントだけではなく、日常的な水辺のにぎわいを創出することをキーワードの一つとしておりまして、その評価に当たっては、ＥＢＰＭ、エビデンスに基づく政策立案が重要と考えています。","voiceIndex":302,"id":"exchange-132"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなってくると、品川区は狭いですから、保管する場所がない。なので、これからどう考えられているのかということと、これは試行ですから、いずれは結論を出さなければいけないと思うのですけれども、いつ結論を出すのですか。一番交通の便が悪いということで、そこで一番先にコミュニティバスの運用を始めたわけですから、そこをまず考えていただきたいと思いますが、いかがでしょうか。","respondent":"伊藤災害対策担当課長、羽鳥防災体制整備担当課長、櫻木地域交通政策課長","answer":"例えば、先にもありました、しながわ水族館でも行わせていただいた自衛隊防災フェアinしながわ水族館であるとか、ほかにも今年度。発災後４日目以降からは、プッシュ型の支援物資が届きますが、１週間までに関しましては、例えば薬ですとか、アレルギー対応食品ですとか。区としましては、引き続き課題が残っているという認識がありますが、新たな交通サービス状況等を注視して、考えてまいりたいと考えています。","voiceIndex":307,"id":"exchange-133"},{"speaker":"西本委員","kind":"質問・要望","question":"地域の中で気軽に備蓄ができる、そういうことも考えていただきたいなというふうにお願いしたいと思います。それから、コミュニティバスなのですが、これはいつまでに結論を出すのかなというところでは、やっぱり西大井四丁目周辺は一番交通の便が悪いので、ぜひ検討を早急にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-134"},{"speaker":"西村委員","kind":"質問","question":"お願いいたします。３６６ページ、防災費全般について、国民保護訓練について、および区における自衛隊と防災力の強化について伺ってまいります。世界を見渡せば、ミサイル発射やテロの脅威は決して人ごとではないと思います。その概要や成果について伺います。","respondent":"伊藤災害対策担当課長","answer":"国民保護訓練の戸越銀座商店街、戸越駅の訓練について説明をいたします。戸越銀座商店街、地下鉄戸越駅での訓練につきましては、委員もご案内のとおり、地域住民など１８名の方が参加されて、Ｊ－ＡＬＥＲＴが発令されたという想定で訓練を行った内容です。","voiceIndex":313,"id":"exchange-135"},{"speaker":"西村委員","kind":"質問・要望","question":"今ご答弁いただきましたように、国民保護訓練は、国民保護法に基づく訓練であり、災害対応能力の向上にも寄与していると考えます。訓練の多面的な意義を考えたいと思います。訓練の中止を求めるのではなく、むしろその充実を図り、地域住民が安心して暮らせる環境を構築することこそが政治の責任だと考えます。平和宣言に反するものではないと考えますが、国民保護共同訓練における区の考えを伺います。","respondent":"伊藤災害対策担当課長","answer":"国民保護共同訓練における区の考え方ですが、国民保護共同訓練につきましては、実施主体であります東京都からの依頼を受けて実施したという前提があります。一方で地震、風水害などの対応と同様に、区民の安心と安全を守るため必要な訓練であると考えています。","voiceIndex":315,"id":"exchange-136"},{"speaker":"西村委員","kind":"質問・要望","question":"自衛隊防災フェアinしながわ水族館においても質問させていただきたいと思いますが、防災意識の向上に向けて、自衛隊の仕事を知ることに問題はないと私は考えます。例えば、水族館内で防災クイズや避難訓練を組み合わせたり、より体験型のイベントとなれば、さらに効果的ではないでしょうか。今後も様々な取組をきっかけに、自衛隊の役割や仕事を知る機会が必要だと考えますが、区のお考えを伺います。","respondent":"伊藤災害対策担当課長","answer":"先ほども答弁申し上げましたが、自衛隊の募集広報につきましては、区の法定受託事務ということで実施をしている内容です。関係法令に基づいて実施をしています。一方、警察、消防と同じように、国防、防災面で活躍される自衛隊の皆さんを紹介することは重要だと考えています。","voiceIndex":317,"id":"exchange-137"},{"speaker":"西村委員","kind":"質問・要望","question":"そして最後に、自衛隊と防災力について伺いたいというふうに思います。２０２０年、災害対策担当部長として滝澤部長が着任されました。東日本大震災を自ら経験され、南海トラフの防災計画改定や広島の土砂災害、数々の台風被害にも直接携われたと伺っております。区には現在４名の元自衛官の方がいらっしゃると伺っております。自衛隊と防災力について、一言いただきたいと思います。お願いをいたします。","respondent":"滝澤災害対策担当部長","answer":"最後に、私がいる間に、四十数年ぶりの東京都との総合防災訓練が実施できたこと、初めて国、東京都、関係自治体、そして区民の方にも参加をいただいて、国民保護訓練が実施できたことは、区の安心、安全のための一助となれたかなと考えています。","voiceIndex":319,"id":"exchange-138"},{"speaker":"西村委員","kind":"意見","question":"今、言っていただいたようなことを私が言えるわけもなく、高いリーダーシップを発揮していただける、こういった元自衛隊の方々が自治体にいるということを本当に誇りに思っておりますし、品川区だけではなくて、全自治体でこれが広がれば、全国的に広がればいいのにというふうに思っておりますので、ぜひ引き続きよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":321,"id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"よろしくお願いします。土木費全体と、３５５ページ、勝島人道橋整備工事、それから３３５ページ、道路安全施策費です。そういう形で、子育て支援という視点をさらに都市環境、防災、まちづくりが持って、常に考えながら事業を進めていっていただきたいと思います。社会全体で子育てを支えるということは、区の所管全体で支えるということにもつながると思いますが、そこの辺りいかがでしょうか。","respondent":"溝口防災まちづくり部長","answer":"多くの方が、区民様々な方がご利用いただける施設を管理していますので、子育てといったものにもしっかり資するような公園づくりですとか、道路の整備、そういったものには取り組んでいきたいというふうに思っているところです。","voiceIndex":323,"id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"ぜひともそういうアイデアを引き出す、そして、できればママやパパたちとタウンミーティングや意見交換をして、意見を吸い上げて、土木系というか、都市環境部と防災まちづくり部にはお願いしたいと思います。子育てというところから考えると、子育ての公園だけではないかもしれませんけれども、ここら辺の２億円、３億円の削減というのはどういうような状況なのでしょうか。","respondent":"大友公園課長","answer":"この件についてなのですけれども、所管として維持管理上、施設の長寿命化計画であったり、点検の結果、こういう改修をしたほうがいいのではないかというところがあるのですけれども、その結果、今の時期が本当に適切なのかどうかというのを財政の目で見た結果。","voiceIndex":325,"id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"様々な要素があって、要求から予算案をつくられていると思いますので、この件に関してはまた別の機会にお尋ねしたいと思います。３５５ページの勝島人道橋整備工事などについてお尋ねします。それで令和６年度に、しながわ花海道水辺広場の設計、そして令和７年度に新浜川公園の基本設計委託が行われました。先ほどほかの委員の方の質問にもありましたので、時期とかそういうのは理解しました。","respondent":"大友公園課長","answer":"人道橋に併せてしながわ花海道、新浜川公園の改修を実施していくというところにおいて、しながわ花海道についても、上面の部分、こちらは護岸の上部を品川区が表面管理をさせていただいて、公園としているというところがありますので、その表面をどうしつらえたら。","voiceIndex":327,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それに関して、東京都建設局が平成２７年に河川整備工事を発表しました。それで、立会川幹線雨水放流管整備が令和９年に終われば、工事の立坑のヤードがなぎさ会館の裏にあります。それから、立坑のところのヤードを、あそこはもう川の上に造っているわけですけれども、そういったところも含めて、ちょっと大きな話で、長いレンジの話になりますけれども、どのように考えになっていらっしゃるでしょうか。","respondent":"大友公園課長","answer":"公園の連続性の視点というところも踏まえて、ちょっとお話をさせていただければと思います。そこについては、長期のスパンのところで、なぎさ会館の今後の活用等も含まれているところですけれども、多角的な視点から検討すべきものというところで考えてあります。","voiceIndex":329,"id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"随分先の話になるのですけれども、その前段階として現在ここをこうする方向というのを考えて計画しておいていただきたいと思います。３３５ページのほうは、ガードパイプ、多摩産材を活用した木柵の整備事業なのですが、令和６年にはあったのですが、令和７年の予算書からは消えてしまいました。非常にメリットがあって、温かみ、景観があるのですが、そこら辺の事情をお願いします。","respondent":"森道路課長","answer":"材料として木材を使っているですので、普通の鋼材のものと維持管理上、課題がいろいろあるのかなというふうに考えておりまして、そういった部分を、少し検証を挟んで、今後増やしていくかどうか確認をしていきたいというふうに思っております。","voiceIndex":331,"id":"exchange-144"},{"speaker":"松本委員","kind":"質問","question":"よろしくお願いします。私からは３３７ページ、自転車通行空間整備、３６７ページ、防災関係組織経費について伺います。車道の左端から１ｍの位置を走行する自転車の増加、あるいは逆走の自転車の減少というふうな記載はされているのですけれども、自転車の交通事故という点で、既存の整備の結果、減ったというふうなデータがあるか伺えればと思います。","respondent":"山下交通安全担当課長","answer":"自転車事故の増減についてのご質問についてお答えいたします。昨年発生は４３８件、令和５年と比べますと、マイナス２４件となっておりまして、減少傾向にあるのかなと。今年に入りましても、自転車の事故というのは減少傾向にあります。","voiceIndex":335,"id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"交差点で、どうしても車道側で交差点の赤信号を待つので、それで左折する自動車に巻き込まれるというふうな研究とかもあるのですけれども、この辺り品川区において、整備結果の増減はなかなか難しいかとは思うのですけれども、ナビライン、ナビマークを整備したところで、例えば交通事故が発生してしまったというふうな事例はあるのでしょうか。","respondent":"山下交通安全担当課長","answer":"今、委員からお話がありました因果関係についてですが、整備をしたから減った、またどういった原因なのかというところは、分析がなかなか難しいところでございまして、そのほかに安全啓発ですとか、警察の取締り、そういったもろもろの。","voiceIndex":337,"id":"exchange-146"},{"speaker":"松本委員","kind":"質問","question":"因果関係を証明していくのはなかなか難しいのかなと思うので、推測というか、推論で考えていくしかないのかなと思っています。一方で、交差点の左折の巻き込みについては、歩道のほうにはソフトポールが立っているのをよく見るのですけれども、例えば交差点のところで、車道側に自転車の巻き込みを防止するためのソフトポールを立てるというふうな対策もあるやに伺っております。お願いいたします。","respondent":"森道路課長","answer":"今回、来年度から改めて自転車走行空間の整備をしていくという中で、当然そういう交差点のところで歩行者や車との接触というのは出てくるのではないかというおそれが検討の中で出てくると思いますので、そういった部分も考慮しながら、複数の対策を組み合わせながら。","voiceIndex":339,"id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"交差点のところ以外でも、逆走です。令和４年の区の自転車利用に関するアンケート調査を拝見すると、車道左側通行の原則を知らなかった人というのは４.２％で、知っているが遵守できなかったという人が１０.５％です。なので、自分たちの目線に合うところで、禁止なのだということが分かるように示していただくという手法があると思いますが、いかがでしょうか。","respondent":"森道路課長","answer":"一方で、委員がおっしゃったように、逆走が禁止されている、罰則があるということにつきましては、交通安全担当としっかり情報共有しながら、いろいろなところで周知・啓発をしていければなというふうに思います。","voiceIndex":341,"id":"exchange-148"},{"speaker":"松本委員","kind":"質問","question":"引き続きよろしくお願いします。最後に防災関係組織経費について伺います。プレス発表の資料を拝見すると、防災に関心のある方々が、日常的に顔の見える関係をつくることができる場を提供しますということがあります。これはどういう事業なのか伺えればと思います。","respondent":"平原防災課長","answer":"女性の参加率が低いとかというのは、防災学校とかでそういうコースをつくっていくなど、複合的に積み重ねたような事業を行っていく予定です。","voiceIndex":343,"id":"exchange-149"},{"speaker":"松本委員","kind":"質問・要望","question":"時間がないので、もうご答弁まではあれかと思うのですけれども、要望というところで、私の周りも、防災にすごく関心があるのだけれども、防災関係はどうしても町内会、自治会が中心になってやられていて、本当は入っていただければいいのですけれども、やっぱり入りにくいという方も結構いらっしゃって、一方で、防災の関係は喫緊なので、ここの部分はとても大事なことだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":345,"id":"exchange-150"},{"speaker":"藤原委員","kind":"質問・要望","question":"私はこの委員会があるたびに、不燃化特区は令和７年度に終わるけれども、どうしても令和１２年度まで延長してほしいと、東京都に要望してほしいと言ってきましたが、今どういう状況にあるか教えてください。ですから、補助２９号線のときに、ぜひ東京都に要望していただきたい。お掃除にこれだけ、３億７,０００万円もお金をかけて、空洞に六百何万円、これはどういうことですか。ちゃんとできるのですか。","respondent":"小川木密整備推進課長、高梨都市計画課長、大友公園課長、中道都市開発課長、川原住宅課長、森建築課長、森道路課長","answer":"初めに、令和８年度以降の不燃化特区制度が続くのかといったご質問ですが、こちらは現在東京都が行っております防災都市づくり計画の基本方針の中で。私からは、ニコン本社開業と補助２９号線と横須賀線の交差部のことについてお答えをします。その中で壁泉、またはそれに代わる水系施設を整備するのか、引き続き検討しています。駐輪場を一定確保する形で設計を進めているです。そうしたことを踏まえて、今後どのように検討を行っていくかというふうに進めていきたいというふうに聞いてあります。","voiceIndex":347,"id":"exchange-151"},{"speaker":"藤原委員","kind":"質問","question":"まちづくりとして伺います。課長、今のは聞き間違いですよ。何でその花壇を移してしまうのですか。違うでしょう。何であえてみんなが見ないところに置いて維持するのですか。そして花壇を移しますと、課長、どういうことですか。そうしたら、お花だらけにすればいいではないですか。きれい。そして、喫煙所の横に品川１００景の看板が立っている。だから、あのまちのこと、でも、総括でまた聞きます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":355,"id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは３５１ページの品川駅南地域周辺まちづくり事業から、品川浦周辺地区再開発について伺いたいと思います。それで、この地域も以前にここで示したことがありますけれども、まちづくり協議会が出した再開発の完成イメージ図です。１４棟のビルが立ち並ぶ状況です。今日は、質問は、この間は地権者数を聞いてきましたけれども、計画地域に住んでいる住民数を地区別に教えていただきたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"一方で、区では令和５年度に「まちづくりニュース」というものを委託で発行しておりまして、地区内の全戸に配布しています。その数が約２,８００世帯となっていますので、ちょっと参考値にはなってしまうのですけれども、今このような状況となっています。","voiceIndex":357,"id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この開発地域内には、都営住宅が６６５戸ありますけれども、先日共産党の白石たみお都議と安藤委員と、都営住宅の自治会長に話を伺ってきました。自治会長の言っている話を聞いても、ついの住みかにしていきたい、安心して住み続けているという声ですので、この都営住宅を残すようにぜひ都に求めていただきたいと思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"一方で、準備組合のほうでは、品川浦の歴史や水辺、そういった地域資源を活かしながらまちづくり検討を行っているものと認識してございまして、地域経済の発展のためにまちづくりの検討を行っているものです。都営住宅をなくすような検討しているとは、区は認識してございません。","voiceIndex":359,"id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど言ったように、都営住宅の住民には説明されていないわけです。ぜひ東京都に残すように求めていただきたいと強く要望したいと思います。２人分のまちづくり視察として、１回の費用が含まれています。伺いたいのですけれども、誰と誰が毎週都庁の誰に会いに何の目的で行くのか、そしてまちづくり視察の費用は、どこに何を見ることを目的に行くのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"まちづくり視察ということなのですけれども、こちらは１,０００円×２人分を計上させていただいているのですけれども、こちらも具体的にどこというところは、まだ特に予定はないのですけれども、同様な事例として、近接的に近いところの視察を行って。","voiceIndex":361,"id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうやって頻繁に東京都に職員の方も行かれているということであれば、なおさら都営住宅を残すように求めていただきたいと思いますし、都営住宅に限らず、高齢者もたくさんいる地域です。資材高騰や人件費の高騰等、あらゆる建築コストが上がり続けています。まちづくりの方法は超高層だけではありません。住み続けたい人が住み続けられるまちづくりに転換すべきだと思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"まちづくりは地域住民が主体となって現在検討を進めてあります。今後もまちづくりに関する地域住民の様々な声に耳を傾けてまいりたいと考えているところです。","voiceIndex":363,"id":"exchange-156"},{"speaker":"大倉委員","kind":"質問・要望","question":"ボランティア団体のほうは、前回聞いたときは２３団体ということで、周知がなかなか進んでいなくて、参加者が少ないのかなという認識の中で、これは地域貢献という点がすごく大きいというふうに思っていて、ボランティアというところなのですが、ボランティアの周知をしっかりしていくということと、地域貢献だけれども、やっていただいた方には何かもらえるインセンティブを出していくということで。","respondent":"平原防災課長、山下交通安全担当課長、川崎土木管理課長","answer":"その後、国の動きがありましたら、一緒に導入を検討していくです。保管所のキャッシュレスにつきましては、たしか決算特別委員会のときもお話があったかもしれませんが、進めているということで話を伺っているところですが。令和６年度に電子申請サービスを導入し、若い方も含めて幅広く、ボランティアに協力してくださるようにということで、取組を進めてまいりました。","voiceIndex":366,"id":"exchange-157"},{"speaker":"大倉委員","kind":"質問","question":"ＤＸ化のほうは、避難所ですね。分かりました。できるところを進めていくということで分かりました。避難所の情報発信と情報収集についてもＤＸ化できないかということも聞いたので、伺えればと思います。そういった団体の交流を進めていく中で、また新たな広がりがあったりするのかなということもありますので、併せて伺えればと思います。お願いします。","respondent":"平原防災課長、川崎土木管理課長","answer":"なお収集については、これまでは基本的に区民からの通報等により対応してきたところ、例えばＸなどの発信を、ＡＩによる分析を踏まえた形で残っていくような形での収集といったところも。インセンティブの部分についてですけれども、恐らく以前もそのようなご質問がおありだったかと思うのですけれども、やはりボランティアで携わってくださる方ということで、これは区としても真剣に取り組んで。","voiceIndex":370,"id":"exchange-158"},{"speaker":"大倉委員","kind":"質問","question":"一点、カラーコーンが結構大きくなってきていて、そういったものの取締り、景観美化だけだと厳しいのかなという、重さもあったり、大きさもあるので、しなみちレポートとかを活用して、うまく回収してくださいみたいになれば、回収が進むのではないかというところで、活用も含めてそういった情報提供をしていっていただければと思うのですが、いかがでしょうかということと、防災費のほうで。","respondent":"川崎土木管理課長、平原防災課長","answer":"ただ現在、品川区の事情としては、肌感覚ではあるのですけれども、カラーコーンが少しずつ減ってきているかなといった状況ではありますが、検討を進めていきたいと思います。いわゆる１.５次避難所としての福祉避難所の活用は、補完避難所を活用して福祉部とともに進めているところです。","voiceIndex":373,"id":"exchange-159"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは３６９ページ、消防団運営費から、まずは品川消防団第三分団の施設に関しまして、品川消防団長からぜひ議会で取り上げてほしいという要望がありましたので、質問していきます。都内で初めてとなる女性の消防団長とこの間複数回お目にかかった際に、何回か議会への同じ要望をいただきました。現在第三分団の施設である品川消防団第三分団詰所の現場を確認してまいりました。","respondent":"伊藤災害対策担当課長","answer":"こちらについては、品川消防署のほうともしっかり情報共有しておりまして、品川消防署のほうからも、東京都の本部庁舎、消防団課とも連携しているというような状況であります。区内でも情報共有をしておりまして、適地について今、検討しているような状況です。","voiceIndex":378,"id":"exchange-160"},{"speaker":"あくつ委員","kind":"質問","question":"３５３ページ、子供の森公園改修工事、今日も様々な質疑がありました。後々分かったのですけれども、下神明にある神明児童遊園ですか、たこ公園。昨年８月の子供の森公園改修工事説明会の説明資料には、整備方針としてこのような記載があります。怪獣のコンセプトを継承し、かいじゅう公園として再整備、これは区立子供の森公園の名称をかいじゅう公園に変更するということでしょうか。","respondent":"大友公園課長","answer":"子供の森公園の名称を変更するかというご質問なのですけれども、子供の森公園の名称はそのまま「こどものもりこうえん」となりますが、今回都市計画公園という形にするに当たり、「子供」の「供」をひらがなに変更させていただいてあります。","voiceIndex":380,"id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点、昨年８月の説明会で、高齢者クラブの皆様からこのような要望がありました。特に天王洲地域でそれができるようになれば一石二鳥なので、ぜひお願いしたいという要望でした。天王洲都営団地の自治会長からも同様の要望もいただいておりまして、所管課にもお伝えして、先ほど申し上げた都市計画審議会、様々な場でお願いをしてまいりましたが、この点のご検討はいかがでしょうか。","respondent":"大友公園課長","answer":"野球場のような広さは確保できませんが、仮設の広場を設けたいと考えているところです。委員からもお話がありましたような代替等も含め、引き続き工事期間のご不便を少なくするための手法を検討しています。","voiceIndex":382,"id":"exchange-162"},{"speaker":"あくつ委員","kind":"確認","question":"今あるところでできるだけグラウンドゴルフが継続できるということと、それ以外のこともできることはまた引き続き考えていただくということで確認させていただきました。３６３ページ、マンション管理支援事業から伺ってまいります。マンション管理支援事業のうち、建替・修繕支援についてどのような事業であるのか教えてください。","respondent":"川原住宅課長","answer":"マンション管理支援事業のうち、建替・修繕事業の内訳に対するご説明をします。","voiceIndex":384,"id":"exchange-163"},{"speaker":"あくつ委員","kind":"質問","question":"以前の一般質問への答弁では、少し古いデータですけれども、区内にはこのような築４０年以上の区分所有マンションが約４７０棟あるということでした。品川区が把握をする中で、老朽化と高齢化、この２つの老いに対する対策として、区内で建て替えを行ったマンションがあるのか、あるとするならばそれは何棟なのかお知らせください。","respondent":"川原住宅課長","answer":"こちらについて、マンションの建替円滑化法に基づいた建て替え事業ということで、区が間接的に関与することで、区分所有者からの信頼等も得られやすかったのだと考えられます。","voiceIndex":386,"id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"建替円滑化法に基づいたからこそ把握ができたものが１件、築４０年以上が４７０棟あるうちで、現在まで建て替えは僅か１件である。そういった建て替えのノウハウについて、品川区でもぜひ押さえていただきたいというのが１つです。それと建て替えの管理組合の意向調査も含めて、先立つ準備をいろいろ行っていく必要があるのではないでしょうかという質問です。２つお聞きします。","respondent":"川原住宅課長","answer":"そして今後こういった建て替えのニーズの調査であるとか、必要性についての区の認識ですが、現在品川区においては、マンション管理適正化推進計画を令和５年につくりまして、こちらが令和９年までの５年の計画期間という形ですので、これまでの計画が終了し。","voiceIndex":388,"id":"exchange-165"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"私からは、予算書３６７ページ、防災普及教育費、３６９ページ、消防団運営費についてお聞きします。代表質問でも触れましたが、防災士の助成金の予算計上というのは大変に評価をしております。区内で防災士を受講した人数というのは、把握が難しいのかもしれないですけれども、防災学校を受講した人数は、数字を取っているものなのか教えてください。","respondent":"平原防災課長","answer":"令和７年度予算で新たに防災士資格の取得支援を行うこととなった理由ですけれども、品川区では、しながわ防災学校の防災区民組織コース、地域実践コースを地域防災の柱というふうに位置づけているところです。","voiceIndex":391,"id":"exchange-166"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"６４４人、数字が分かるのですね。４５３人、それで６人はあまりにも少ないですね。だからまず防災士を取って、それから防災コースにつなげようという取組は理解しました。防災士は私も取得しました。地域の防災リーダーというのは町会長ですので、町会長と防災士、また防災区民組織をしっかりとつなぐ組織というのは、まず品川区でやるべきではないかなと思いますけれども、ご見解をお願いします。","respondent":"平原防災課長","answer":"さらにはそういう方々を防災区民組織とつなげていくといったところが、区がハブとなってやっていく役割かなというふうに思ってあります。そういう中から地域防災の担い手を拡大していこうといったところを今考えているところです。","voiceIndex":393,"id":"exchange-167","title":"町会・自治会支援"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"１点だけ気になっているのが、品川区も避難行動要支援者計画というのがありますね。なので、防災学校の受講の中で、要配慮者の勉強も入れるべきではないかと考えます。ご見解を聞かせてください。私は学校の先生、例えば中学校の先生、こういう方たちに受講してほしいという思いがあるのです。でもこれは所管が違うので、今日は要望します。要配慮者の勉強についてご見解をお聞かせください。","respondent":"平原防災課長","answer":"災害発生時に要配慮者を支援する体制というものを強化していく必要がまだまだありますので、今後ともこのような取組を充実させていければというふうに考えてあります。","voiceIndex":395,"id":"exchange-168"},{"speaker":"まつざわ委員","kind":"質問","question":"私は個人的に防災ジュニアプロジェクトというのを大変応援していますので、引き続きよろしくお願いします。次に、消防団です。例えば、町会で、火事で家が燃えました。そうすると、そこに住む人がいないのですけれども、公助につながるまでにはどうしても時間があるのですよね。例えば、品川区から３消防団にお願いというのはできるのか、できるならどういうふうにやっていくのか、まずそれを教えてください。","respondent":"伊藤災害対策担当課長","answer":"ただいま消防団から区のほうに何らかの依頼があった場合に対応できるかということで、例えば既に行っておりますけれども、地域の防災訓練等で、地域から要請があった場合に出てきていただいております。","voiceIndex":397,"id":"exchange-169"},{"speaker":"まつざわ委員","kind":"確認","question":"それは確認しました。それでご存じのとおり、消防団の入団率というのは下がっていますね。制度というとちょっと難しいと思うのですけれども、例えば短時間消防団とか、イベント消防団というのですか、何が言いたいかというと、私もそうなのですけれども、消防団に入っていると、夏は総合訓練とか週３回、これが相当なストレスというか、ハードなのですよ、になってしまうという声も聞いています。","respondent":"伊藤災害対策担当課長","answer":"現在品川消防団のほうでは、東京医療保健大学と連携してございまして、昨年ですと２０名程度の方が品川消防団に入団されたというような話も聞いております。こういった方々をイベント等、訓練ですとか、地域活動していただいているというような実績も伺っております。","voiceIndex":399,"id":"exchange-170"},{"speaker":"まつざわ委員","kind":"質問","question":"区民組織なのですけれども、結局消防団は東京都なので、何かあったとき、区がやるのではないではないですか。東京都からの指示でしか動けないというジレンマがあるのです。守りたいまちを守れないというジレンマもあるのが、消防団の大きな課題だと私は思っているのです。それはちゃんと対面でいいですよと言ってくれるのですから、そういう関係性を生み出していくべきだと思っていますね。","respondent":"伊藤災害対策担当課長","answer":"ですので、平素からのつながりという面で考えたときに、防災訓練、また防災訓練の会議等で、消防団の方々、分団も含めまして会議に出ていただいておりますので、そういった中でコミュニケーションを図っていただきまして。","voiceIndex":401,"id":"exchange-171"},{"speaker":"まつざわ委員","kind":"意見","question":"いろいろありがとうあります。最後ですけれども、伊藤課長も品川区に来られて２年ですね。いよいよ消防庁になるのか、異動になるのかは私も分かりませんが、消防団運営委員会会議を始めて、消防団に対しては、私も随分いろいろな意見を交換してきました。この２年間を振り返って品川区、また、消防団に対する思いというのを最後にぜひ聞かせてください。","respondent":"伊藤災害対策担当課長","answer":"荏原消防団におかれましても、全国大会にて準優勝されたということで、こういう限られた制約のある中で非常に頑張っている存在だと認識しております。","voiceIndex":403,"id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7011#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":132737,"voices":405}}]);
